export type ParamSink = { params: Param[]; base: string; item: string; ability?: string; abilityName?: string };
export function addParam(s: ParamSink, rel: string, kind: ParamKind, cap: CapName | [number, number], value: number | string, label: string, role: string): Param {
  const [min, max] = Array.isArray(cap) ? cap : CAPS[cap as CapName];
