type Obj = Record<string, unknown>;

function iconSet(icon: Obj | undefined, field: string, value: number | string): string | null {
  if (!icon) return "no icon";
  if (field === "name") { (icon.name as Obj).text = value; return null; }
  if (field === "amount") { icon.amount = value; return null; }
  const l = /^lore(\d+)$/.exec(field);
  if (l) { const line = (icon.lore as Obj[] | undefined)?.[Number(l[1])]; if (!line) return "no lore line"; line.text = value; return null; }
  return `unknown icon field ${field}`;
}
function clickSet(c: Obj, rest: string[], value: number | string): string | null {
  if (rest.length === 1) return iconSet(c.icon as Obj, rest[0], value);
  if (rest[0] === "cost" && rest.length === 2) { const cost = c.cost as Obj | undefined; if (!cost) return "no cost"; cost[rest[1]] = value; return null; }
  const a = /^a(\d+)$/.exec(rest[0]);
  if (a && rest.length === 2) { const act = (c.actions as Obj[] | undefined)?.[Number(a[1])]; if (!act) return `no action ${rest[0]}`; act[camelKey(rest[1])] = value; return null; }
  return `unknown path ${rest.join(".")}`;
}

