// Cyrus Config and Stats Studio: ConfigSpec v1, the ONE typed model of a mod's tunable settings (mob stats, weapon
// stats, ability cooldowns, shop prices, boss phases, quest rewards, arena timers...). GAME-NEUTRAL: a param is a
// typed value at a dotted key with limits, units and how a change takes effect; per-game exporters (./exporters.ts)
// say how a file is written and reloaded. The designers' params (lib/cyrus/designer) convert into this model
// (./designer.ts), imported mods get an inferred spec (./infer.ts), AI-built mods declare one (assets/config/schema.json).
// Pure + client-safe. Zod in code, `configSpecJsonSchema()` is the portable contract. Rule failures come back as
// structured issues { path, code, message }, never a thrown error.
import { z } from "zod";

export const CONFIG_SPEC_VERSION = 1 as const;

export const PARAM_TYPES = ["number", "int", "range", "bool", "enum", "text", "color", "duration", "sound-ref", "asset-ref", "list", "table"] as const;
export type ParamType = (typeof PARAM_TYPES)[number];
export const NUMERIC_TYPES: readonly ParamType[] = ["number", "int", "duration", "range"];

/** How a changed value reaches a running server: re-read on its own / the mod's reload command / a server restart. */
export const APPLIES = ["live", "reload", "restart"] as const;
export type Applies = (typeof APPLIES)[number];
export const APPLIES_RANK: Record<Applies, number> = { live: 0, reload: 1, restart: 2 };

/** Stat -> viewport links (./visual.ts): clip playback rate, model scale, fire cadence, colour. */
export const VISUAL_CHANNELS = ["clipRate", "attackRate", "scale", "fireRate", "tint"] as const;
export type VisualChannel = (typeof VISUAL_CHANNELS)[number];

export const DURATION_UNITS = ["ticks", "s", "ms"] as const;
export type DurationUnit = (typeof DURATION_UNITS)[number];
export const ASSET_REF_KINDS = ["texture", "model", "sound", "item"] as const;

export const CONFIG_LIMITS = { params: 400, groups: 32, presets: 12, options: 64, listItems: 256, tableRows: 256, columns: 12, textChars: 1024, keyChars: 160, keyDepth: 10 } as const;

/** One dotted config path segment: letters, digits, `_` and `-` (imported mods use camelCase and kebab-case keys). */
export const KEY_SEGMENT_RE = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/;
export const ID_RE = /^[a-z][a-z0-9_-]{0,31}$/;
export const COLOR_RE = /^#[0-9a-fA-F]{6}$/;
/** A namespaced sound key (minecraft:entity.zombie.ambient, nx_abcd1234:gun.fire); other games use the same shape. */
export const SOUND_KEY_RE = /^[a-z0-9_.-]{1,64}:[a-z0-9_.-]{1,128}(\/[a-z0-9_.-]{1,64})*$/;
export const UNIT_RE = /^[A-Za-z%°/ .-]{1,16}$/;
export const RELOAD_COMMAND_RE = /^\/?[a-z0-9_:-]{1,32}( [a-z0-9_-]{1,32}){0,3}$/;
export const FILE_RE = /^(?![/\\])(?!.*\.\.)[A-Za-z0-9_./-]{1,120}\.(yml|yaml|json|toml|cfg|properties)$/;

export function isConfigKey(k: unknown): k is string {
  if (typeof k !== "string" || !k.length || k.length > CONFIG_LIMITS.keyChars) return false;
  const segs = k.split(".");
  return segs.length <= CONFIG_LIMITS.keyDepth && segs.every((s) => KEY_SEGMENT_RE.test(s) && s !== "__proto__" && s !== "constructor" && s !== "prototype");
}

const line = (max: number) => z.string().trim().min(1).max(max);
const Scalar = z.union([z.number(), z.string().max(CONFIG_LIMITS.textChars), z.boolean()]);
export type ScalarValue = z.infer<typeof Scalar>;
/** A value as stored: number (number/int/duration), [lo, hi] (range), boolean, string (enum/text/color/refs), list, table rows. */
export const ConfigValueZ = z.union([
  z.number(), z.boolean(), z.string().max(CONFIG_LIMITS.textChars),
  z.array(Scalar).max(CONFIG_LIMITS.listItems),
  z.array(z.record(z.string(), Scalar)).max(CONFIG_LIMITS.tableRows),
]);
export type ConfigValue = number | boolean | string | ScalarValue[] | Record<string, ScalarValue>[];
export type ConfigValues = Record<string, ConfigValue>;

const OptionZ = z.object({ value: z.union([z.string().max(64), z.number()]), label: line(60).optional() }).strict();
const SafeZ = z.object({ min: z.number().optional(), max: z.number().optional(), note: line(200).optional() }).strict();
const VisualZ = z.object({
  channel: z.enum(VISUAL_CHANNELS),
  /** clipRate / fireRate: the clip the stat drives ("walk", "attack", "fire", "reload"). */
  clip: z.string().regex(/^[a-z][a-z0-9_]{0,31}$/).optional(),
  /** The value at which the clip plays at 1x (or the model is scale 1). */
  ref: z.number().positive().optional(),
  /** true: the rate goes DOWN as the value goes up (reload time: longer reload = slower clip). */
  inverse: z.boolean().optional(),
}).strict();

/** A list item / table column: a scalar param without groups, presets or visuals. */
const CellZ = z.object({
  type: z.enum(["number", "int", "bool", "enum", "text", "color", "sound-ref", "asset-ref"]),
  min: z.number().optional(), max: z.number().optional(), step: z.number().positive().optional(),
  unit: z.string().regex(UNIT_RE).optional(),
  options: z.array(OptionZ).min(1).max(CONFIG_LIMITS.options).optional(),
  maxLength: z.number().int().min(1).max(CONFIG_LIMITS.textChars).optional(),
}).strict();
const ColumnZ = CellZ.extend({ key: z.string().regex(KEY_SEGMENT_RE), label: line(40), default: Scalar.optional() }).strict();

export const ConfigParamZ = z.object({
  key: z.string().refine(isConfigKey, "keys are dotted paths of letters, digits, _ and - (max 10 levels, 160 chars)"),
  group: z.string().regex(ID_RE),
  type: z.enum(PARAM_TYPES),
  label: line(60),
  help: line(200).optional(),
  default: ConfigValueZ,
  unit: z.string().regex(UNIT_RE).optional(),
  /** HARD limits: the generated loader clamps to them and the editor refuses values outside them. */
  min: z.number().optional(),
  max: z.number().optional(),
  step: z.number().positive().optional(),
  /** The BALANCE range: outside it the editor warns but saves. */
  safe: SafeZ.optional(),
  durationUnit: z.enum(DURATION_UNITS).optional(),
  options: z.array(OptionZ).min(1).max(CONFIG_LIMITS.options).optional(),
  maxLength: z.number().int().min(1).max(CONFIG_LIMITS.textChars).optional(),
  assetKind: z.enum(ASSET_REF_KINDS).optional(),
  item: CellZ.optional(),
  maxItems: z.number().int().min(1).max(CONFIG_LIMITS.listItems).optional(),
  columns: z.array(ColumnZ).min(1).max(CONFIG_LIMITS.columns).optional(),
  maxRows: z.number().int().min(1).max(CONFIG_LIMITS.tableRows).optional(),
  applies: z.enum(APPLIES).default("restart"),
  visual: VisualZ.optional(),
  tags: z.array(z.string().regex(/^[a-z][a-z0-9_-]{0,23}$/)).max(8).default([]),
  advanced: z.boolean().optional(),
  readOnly: z.boolean().optional(),
}).strict();

const GroupZ = z.object({ id: z.string().regex(ID_RE), label: line(60), help: line(200).optional(), order: z.number().int().min(0).max(999).optional() }).strict();
const PresetZ = z.object({ id: z.string().regex(ID_RE), label: line(40), help: line(200).optional(), values: z.record(z.string(), ConfigValueZ) }).strict();

export const ConfigSpecV1Schema = z.object({
  schemaVersion: z.literal(1),
  /** Where the values live, relative to the mod's data folder (Paper: plugins/<plugin>/config.yml). */
  file: z.string().regex(FILE_RE).default("config.yml"),
  format: z.enum(["yaml", "json", "toml", "properties"]).default("yaml"),
  /** The category template this spec started from (./templates.ts), if any. */
  category: z.string().regex(ID_RE).optional(),
  /** Inferred from an existing config file (imported mod): no balance claims, type checks only. */
  inferred: z.boolean().optional(),
  /** How `applies: "reload"` is done: the mod's own reload command (console). */
  reload: z.object({ command: z.string().regex(RELOAD_COMMAND_RE) }).strict().optional(),
  groups: z.array(GroupZ).min(1).max(CONFIG_LIMITS.groups),
  params: z.array(ConfigParamZ).min(1).max(CONFIG_LIMITS.params),
  presets: z.array(PresetZ).max(CONFIG_LIMITS.presets).default([]),
}).strict();

export type ConfigSpec = z.output<typeof ConfigSpecV1Schema>;
export type ConfigSpecInput = z.input<typeof ConfigSpecV1Schema>;
export type ConfigParam = ConfigSpec["params"][number];
export type ConfigParamInput = z.input<typeof ConfigParamZ>;
export type ConfigGroup = ConfigSpec["groups"][number];
export type ConfigPreset = ConfigSpec["presets"][number];
export type CellSpec = z.output<typeof CellZ>;
export type ColumnSpec = z.output<typeof ColumnZ>;
export type ConfigIssue = { path: string; code: string; message: string };

/** JSON Schema (draft 2020-12) of what a producer (the AI, an exporter, a test) writes. */
export function configSpecJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(ConfigSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

// --------------------------------------------------------------------------------------------- cell / value rules

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const decimals = (x: number) => { const s = String(x); const i = s.indexOf("."); return i < 0 ? 0 : s.length - i - 1; };

/** Check one scalar against a cell spec (list items, table cells). Returns an error message or null. */
export function cellError(c: Pick<CellSpec, "type" | "min" | "max" | "options" | "maxLength">, v: unknown): string | null {
  switch (c.type) {
    case "number": case "int":
      if (!isNum(v)) return "needs a number";
      if (c.type === "int" && !Number.isInteger(v)) return "needs a whole number";
      if (c.min !== undefined && v < c.min) return `is below the minimum ${c.min}`;
      if (c.max !== undefined && v > c.max) return `is above the maximum ${c.max}`;
      return null;
    case "bool": return typeof v === "boolean" ? null : "needs true or false";
    case "enum": return c.options?.some((o) => o.value === v) ? null : `must be one of ${(c.options ?? []).map((o) => o.value).join(", ")}`;
    case "text": return typeof v !== "string" ? "needs text" : v.length > (c.maxLength ?? 256) ? `is longer than ${c.maxLength ?? 256} characters` : /[\u0000-\u0008\u000b-\u001f]/.test(v) ? "has control characters" : null;
    case "color": return typeof v === "string" && COLOR_RE.test(v) ? null : "needs a colour like #ff8800";
    case "sound-ref": return typeof v === "string" && (v === "" || SOUND_KEY_RE.test(v)) ? null : "needs a namespaced sound key (namespace:path)";
    case "asset-ref": return typeof v === "string" && /^[a-z0-9_.:/-]{0,160}$/.test(v) ? null : "needs an asset id";
  }
}

/** Is a value of the right SHAPE for a param (type only; limits are ./values.ts). */
export function shapeError(p: Pick<ConfigParam, "type" | "options" | "item" | "columns" | "maxLength" | "maxItems" | "maxRows">, v: unknown): string | null {
  switch (p.type) {
    case "number": case "duration": return isNum(v) ? null : "needs a number";
    case "int": return isNum(v) && Number.isInteger(v) ? null : "needs a whole number";
    case "range": return Array.isArray(v) && v.length === 2 && isNum(v[0]) && isNum(v[1]) ? (v[0] <= v[1] ? null : "the low end is above the high end") : "needs [low, high]";
    case "bool": case "enum": case "text": case "color": case "sound-ref": case "asset-ref":
      return cellError({ type: p.type, options: p.options, maxLength: p.maxLength }, v);
    case "list": {
      if (!Array.isArray(v)) return "needs a list";
      if (v.length > (p.maxItems ?? CONFIG_LIMITS.listItems)) return `has more than ${p.maxItems ?? CONFIG_LIMITS.listItems} items`;
      if (!p.item) return null;
      for (let i = 0; i < v.length; i++) { const e = cellError({ ...p.item, min: undefined, max: undefined }, v[i]); if (e) return `item ${i + 1} ${e}`; }
      return null;
    }
    case "table": {
      if (!Array.isArray(v)) return "needs rows";
      if (v.length > (p.maxRows ?? CONFIG_LIMITS.tableRows)) return `has more than ${p.maxRows ?? CONFIG_LIMITS.tableRows} rows`;
      for (let i = 0; i < v.length; i++) {
        const row = v[i];
        if (!row || typeof row !== "object" || Array.isArray(row)) return `row ${i + 1} is not a row`;
        for (const c of p.columns ?? []) {
          const cell = (row as Record<string, unknown>)[c.key];
          if (cell === undefined) { if (c.default === undefined) return `row ${i + 1} has no ${c.key}`; continue; }
          const e = cellError({ ...c, min: undefined, max: undefined }, cell);
          if (e) return `row ${i + 1} ${c.key} ${e}`;
        }
      }
      return null;
    }
  }
}

// --------------------------------------------------------------------------------------------- validation

export type ConfigValidateResult = { ok: true; spec: ConfigSpec; warnings: ConfigIssue[] } | { ok: false; errors: ConfigIssue[]; warnings: ConfigIssue[] };
const pathOf = (p: readonly PropertyKey[]) => p.map((k) => (typeof k === "number" ? `[${k}]` : `.${String(k)}`)).join("").replace(/^\./, "");

/** Untrusted JSON -> ConfigSpec, or every problem found (schema + cross-field rules). */
export function validateConfigSpec(raw: unknown): ConfigValidateResult {
  const parsed = ConfigSpecV1Schema.safeParse(raw);
  if (!parsed.success) return { ok: false, warnings: [], errors: parsed.error.issues.slice(0, 50).map((i) => ({ path: pathOf(i.path), code: i.code, message: i.message })) };
  const spec = parsed.data;
  const errors: ConfigIssue[] = [];
  const warnings: ConfigIssue[] = [];
  const err = (path: string, code: string, message: string) => errors.push({ path, code, message });

  const groups = new Set<string>();
  spec.groups.forEach((g, i) => { if (groups.has(g.id)) err(`groups[${i}].id`, "duplicate_group", `group ${g.id} is listed twice`); groups.add(g.id); });
  const keys = new Set<string>();
  spec.params.forEach((p, i) => { if (keys.has(p.key)) err(`params[${i}].key`, "duplicate_key", `${p.key} is listed twice`); keys.add(p.key); });
