  for (let i = 0; i + 1 < sorted.length; i++) if (sorted[i + 1].startsWith(sorted[i] + ".")) err("params", "key_prefix", `${sorted[i]} is a setting and also a section (${sorted[i + 1]})`);

  spec.params.forEach((p, i) => {
    const at = `params[${i}]`;
    if (!groups.has(p.group)) err(`${at}.group`, "unknown_group", `${p.key} is in group ${p.group}, which is not listed`);
    const numeric = (NUMERIC_TYPES as readonly string[]).includes(p.type);
    if (!numeric && (p.min !== undefined || p.max !== undefined || p.safe || p.step !== undefined)) err(at, "limits_on_non_number", `${p.key}: only number, int, duration and range settings have limits`);
    if (p.min !== undefined && p.max !== undefined && p.min > p.max) err(at, "min_above_max", `${p.key}: min ${p.min} is above max ${p.max}`);
    if (p.type === "int" && [p.min, p.max, p.step].some((x) => x !== undefined && !Number.isInteger(x))) err(at, "int_limits", `${p.key}: whole-number settings need whole-number limits`);
    if (p.safe) {
      const s = p.safe;
      if (s.min !== undefined && s.max !== undefined && s.min > s.max) err(`${at}.safe`, "safe_inverted", `${p.key}: the balanced range is inverted`);
      if ((p.min !== undefined && s.min !== undefined && s.min < p.min) || (p.max !== undefined && s.max !== undefined && s.max > p.max)) err(`${at}.safe`, "safe_outside_limits", `${p.key}: the balanced range must sit inside the hard limits`);
    }
    if (p.type === "duration" && !p.durationUnit) err(at, "duration_unit", `${p.key}: a duration needs durationUnit (ticks, s or ms)`);
    if (p.type !== "duration" && p.durationUnit) err(at, "duration_unit", `${p.key}: durationUnit is only for durations`);
    if (p.type === "enum") {
      if (!p.options) err(at, "enum_options", `${p.key}: an enum needs options`);
      else if (new Set(p.options.map((o) => String(o.value))).size !== p.options.length) err(`${at}.options`, "duplicate_option", `${p.key}: an option is listed twice`);
    } else if (p.options) err(at, "options_on_non_enum", `${p.key}: only enums have options`);
    if (p.type === "list" && !p.item) err(at, "list_item", `${p.key}: a list needs item (the type of each entry)`);
    if (p.type !== "list" && (p.item || p.maxItems)) err(at, "item_on_non_list", `${p.key}: item/maxItems are only for lists`);
    if (p.type === "table") {
      if (!p.columns) err(at, "table_columns", `${p.key}: a table needs columns`);
      else if (new Set(p.columns.map((c) => c.key)).size !== p.columns.length) err(`${at}.columns`, "duplicate_column", `${p.key}: a column is listed twice`);
    } else if (p.columns || p.maxRows) err(at, "columns_on_non_table", `${p.key}: columns/maxRows are only for tables`);
    if (p.type === "asset-ref" && !p.assetKind) err(at, "asset_kind", `${p.key}: an asset reference needs assetKind`);
    for (const c of [p.item, ...(p.columns ?? [])]) {
      if (!c) continue;
      if (c.type === "enum" && !c.options) err(at, "enum_options", `${p.key}: an enum cell needs options`);
      if (c.min !== undefined && c.max !== undefined && c.min > c.max) err(at, "min_above_max", `${p.key}: a cell's min is above its max`);
    }
    if (p.applies === "reload" && !spec.reload) err(`${at}.applies`, "reload_without_command", `${p.key} applies on reload, but the spec names no reload command`);
    if (p.visual) {
      if (!["number", "int", "duration", "color"].includes(p.type)) err(`${at}.visual`, "visual_type", `${p.key}: only numbers, durations and colours drive the viewport`);
      if (p.visual.channel === "tint" ? p.type !== "color" : p.type === "color") err(`${at}.visual`, "visual_channel", `${p.key}: tint is the colour channel`);
      if (p.visual.channel !== "tint" && p.visual.ref === undefined) err(`${at}.visual`, "visual_ref", `${p.key}: a ${p.visual.channel} link needs ref (the value at 1x)`);
      if ((p.visual.channel === "clipRate" || p.visual.channel === "fireRate") && !p.visual.clip) err(`${at}.visual`, "visual_clip", `${p.key}: name the clip it drives`);
    }
    // the default must be valid (shape + limits)
    const se = shapeError(p, p.default);
    if (se) err(`${at}.default`, "bad_default", `${p.key}: the default ${se}`);
    else {
      const lo = p.min, hi = p.max;
      const vals = p.type === "range" ? (p.default as number[]) : numeric ? [p.default as number] : [];
      if (vals.some((v) => (lo !== undefined && v < lo) || (hi !== undefined && v > hi))) err(`${at}.default`, "default_outside_limits", `${p.key}: the default is outside ${lo ?? "-inf"}-${hi ?? "inf"}`);
      if (p.safe && vals.some((v) => (p.safe!.min !== undefined && v < p.safe!.min) || (p.safe!.max !== undefined && v > p.safe!.max))) warnings.push({ path: `${at}.default`, code: "default_unbalanced", message: `${p.key}: the default is outside its own balanced range` });
