  });

  const byKey = new Map(spec.params.map((p) => [p.key, p]));
  const presetIds = new Set<string>();
  spec.presets.forEach((pr, i) => {
    if (presetIds.has(pr.id)) err(`presets[${i}].id`, "duplicate_preset", `preset ${pr.id} is listed twice`);
    presetIds.add(pr.id);
    for (const [k, v] of Object.entries(pr.values)) {
      const p = byKey.get(k);
      if (!p) { err(`presets[${i}].values.${k}`, "unknown_key", `preset ${pr.id} sets ${k}, which is not a setting`); continue; }
      if (p.readOnly) err(`presets[${i}].values.${k}`, "read_only", `preset ${pr.id} sets the read-only ${k}`);
