// Cyrus Config Studio: VALUE checking. Coercion from editor/YAML input, hard-limit checks (strict: refuse; clamp: what
// the generated runtime loader does), balance warnings (the `safe` range), defaults, display formatting. Pure.
import { CONFIG_LIMITS, cellError, numeric, paramByKey, shapeError, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues, type ScalarValue } from "./spec";

export type ValueMode = "strict" | "clamp";
export type ValueIssue = { key: string; code: string; message: string };
export type CheckedValue = { ok: true; value: ConfigValue; clamped: boolean; warnings: ValueIssue[] } | { ok: false; error: ValueIssue };

const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const round = (x: number, step?: number) => {
  if (!step) return Math.round(x * 1e6) / 1e6;
  const n = Math.round(x / step) * step;
  const d = (String(step).split(".")[1] ?? "").length;
  return Number(n.toFixed(Math.min(6, d)));
};

/** Text from a form field or a YAML scalar -> the param's value type (numbers from strings, "true"/"false"). */
export function coerce(p: Pick<ConfigParam, "type" | "item" | "columns" | "options">, raw: unknown): unknown {
  const num = (v: unknown) => (typeof v === "string" && /^\s*[-+]?(\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?\s*$/.test(v) ? Number(v) : v);
  const bool = (v: unknown) => (typeof v === "string" && /^(true|false|yes|no|on|off)$/i.test(v.trim()) ? /^(true|yes|on)$/i.test(v.trim()) : v);
  const cell = (type: string, v: unknown, options?: ConfigParam["options"]) => {
    if (type === "number" || type === "int") return num(v);
    if (type === "bool") return bool(v);
    if (type === "enum" && options?.some((o) => typeof o.value === "number")) return num(v);
    if (type === "enum" || type === "text" || type === "color" || type === "sound-ref" || type === "asset-ref") return typeof v === "number" || typeof v === "boolean" ? String(v) : v === null ? "" : v;
    return v;
  };
  switch (p.type) {
    case "number": case "int": case "duration": return num(raw);
    case "range": {
      if (typeof raw === "string") { const m = /^\s*(-?[\d.]+)\s*(?:-|to|\.\.)\s*(-?[\d.]+)\s*$/.exec(raw); if (m) return [Number(m[1]), Number(m[2])]; }
      return Array.isArray(raw) ? raw.map(num) : raw;
    }
    case "list": return Array.isArray(raw) ? raw.map((v) => cell(p.item?.type ?? "text", v, p.item?.options)) : raw;
    case "table": return Array.isArray(raw) ? raw.map((row) => (row && typeof row === "object" && !Array.isArray(row) ? Object.fromEntries(Object.entries(row as Record<string, unknown>).map(([k, v]) => { const c = p.columns?.find((x) => x.key === k); return [k, c ? cell(c.type, v, c.options) : v]; })) : row)) : raw;
    default: return cell(p.type, raw, p.options);
  }
}

/** Balance warnings: a value outside `safe` (never an error). */
export function balanceWarnings(p: ConfigParam, v: ConfigValue): ValueIssue[] {
  if (!p.safe || !numeric(p)) return [];
  const vals = p.type === "range" ? (v as number[]) : [v as number];
  const u = p.unit ? ` ${p.unit}` : "";
  const out: ValueIssue[] = [];
  const lo = p.safe.min, hi = p.safe.max;
  if (lo !== undefined && vals.some((x) => x < lo)) out.push({ key: p.key, code: "below_balanced", message: `${p.label} ${fmt(p, v)} is below the balanced range (${lo}${u} or more)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  if (hi !== undefined && vals.some((x) => x > hi)) out.push({ key: p.key, code: "above_balanced", message: `${p.label} ${fmt(p, v)} is above the balanced range (${hi}${u} or less)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  return out;
}

/** Check one value: coerce, shape, hard limits (strict refuses, clamp clamps), step rounding, balance warnings. */
export function checkValue(p: ConfigParam, raw: unknown, mode: ValueMode = "strict"): CheckedValue {
  const bad = (code: string, message: string): CheckedValue => ({ ok: false, error: { key: p.key, code, message: `${p.label}: ${message}` } });
  let v = coerce(p, raw);
  if (p.type === "int" && isNum(v) && !Number.isInteger(v) && mode === "clamp") v = Math.round(v);
  const se = shapeError(p, v);
  if (se) return bad("bad_type", se);
  let clamped = false;
  const lim = (x: number) => {
    let y = x;
    if (p.min !== undefined && y < p.min) y = p.min;
    if (p.max !== undefined && y > p.max) y = p.max;
    if (y !== x) clamped = true;
    return y;
  };
  if (numeric(p)) {
    const vals = p.type === "range" ? [...(v as number[])] : [v as number];
    const out = vals.map((x) => {
      if (mode === "strict" && ((p.min !== undefined && x < p.min) || (p.max !== undefined && x > p.max))) return NaN;
      return round(lim(x), p.type === "int" ? Math.max(1, p.step ?? 1) : p.step);
    });
    if (out.some((x) => Number.isNaN(x))) return bad("outside_limits", `${fmt(p, v as ConfigValue)} is outside the allowed ${p.min ?? "-inf"}-${p.max ?? "inf"}${p.unit ? ` ${p.unit}` : ""}`);
    v = p.type === "range" ? out : out[0];
    if (p.type === "range" && (v as number[])[0] > (v as number[])[1]) return bad("bad_type", "the low end is above the high end");
  }
  if (p.type === "list" && p.item && (p.item.min !== undefined || p.item.max !== undefined)) {
    const it = p.item;
    const arr = (v as ScalarValue[]).map((x) => {
      if (!isNum(x)) return x;
      if (mode === "clamp") { const y = Math.min(it.max ?? Infinity, Math.max(it.min ?? -Infinity, x)); if (y !== x) clamped = true; return y; }
      return x;
    });
    for (const x of arr) { const e = cellError(it, x); if (e) return bad("outside_limits", `an item ${e}`); }
    v = arr;
  }
  if (p.type === "table") {
    const rows = (v as Record<string, ScalarValue>[]).map((row) => {
      const r: Record<string, ScalarValue> = {};
      for (const c of p.columns ?? []) {
        let x = row[c.key] ?? c.default;
        if (x === undefined) continue;
        if (isNum(x) && mode === "clamp") { const y = Math.min(c.max ?? Infinity, Math.max(c.min ?? -Infinity, x)); if (y !== x) clamped = true; x = y; }
        r[c.key] = x;
      }
      for (const [k, x] of Object.entries(row)) if (!(k in r) && !(p.columns ?? []).some((c) => c.key === k)) r[k] = x; // unknown columns are kept
      return r;
    });
    for (let i = 0; i < rows.length; i++) for (const c of p.columns ?? []) { if (rows[i][c.key] === undefined) continue; const e = cellError(c, rows[i][c.key]); if (e) return bad("outside_limits", `row ${i + 1} ${c.label} ${e}`); }
    v = rows;
  }
  return { ok: true, value: v as ConfigValue, clamped, warnings: balanceWarnings(p, v as ConfigValue) };
}

export const defaultsOf = (spec: Pick<ConfigSpec, "params">): ConfigValues => Object.fromEntries(spec.params.map((p) => [p.key, structuredClone(p.default)]));

export type ValuesCheck = { ok: boolean; values: ConfigValues; errors: ValueIssue[]; warnings: ValueIssue[]; clamped: string[] };

/**
 * Check a full or partial value set against the spec. Missing keys take the default. Unknown keys are errors
 * (strict) or ignored with a warning (clamp: reading a file the server owner edited). Read-only keys may not change.
 */
export function checkValues(spec: ConfigSpec, values: Record<string, unknown>, mode: ValueMode = "strict", base: ConfigValues = defaultsOf(spec)): ValuesCheck {
  const byKey = paramByKey(spec);
  const errors: ValueIssue[] = [], warnings: ValueIssue[] = [], clamped: string[] = [];
  const out: ConfigValues = { ...base };
  const entries = Object.entries(values ?? {});
  if (entries.length > CONFIG_LIMITS.params) return { ok: false, values: out, errors: [{ key: "", code: "too_many", message: `at most ${CONFIG_LIMITS.params} settings` }], warnings, clamped };
  for (const [k, raw] of entries) {
    const p = byKey.get(k);
    if (!p) { (mode === "strict" ? errors : warnings).push({ key: k, code: "unknown_key", message: `${k} is not a setting of this mod` }); continue; }
    const r = checkValue(p, raw, mode);
    if (!r.ok) { errors.push(r.error); continue; }
    if (p.readOnly && !sameValue(r.value, base[k] ?? p.default)) { errors.push({ key: k, code: "read_only", message: `${p.label} cannot be changed here` }); continue; }
    out[k] = r.value;
    if (r.clamped) clamped.push(k);
    warnings.push(...r.warnings);
  }
  for (const p of spec.params) if (!entries.some(([k]) => k === p.key)) warnings.push(...balanceWarnings(p, out[p.key]));
  return { ok: errors.length === 0, values: out, errors, warnings, clamped };
}

export function sameValue(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b || a === null || b === null || typeof a !== "object") return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) return a.length === (b as unknown[]).length && a.every((x, i) => sameValue(x, (b as unknown[])[i]));
  const ka = Object.keys(a as object).sort(), kb = Object.keys(b as object).sort();
  return ka.length === kb.length && ka.every((k, i) => k === kb[i] && sameValue((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k]));
}

// --------------------------------------------------------------------------------------------- units + display

const TICKS_PER_S = 20;
/** Duration value (in its storage unit) -> seconds, for display and the viewport. */
export function toSeconds(p: Pick<ConfigParam, "durationUnit">, v: number): number {
  return p.durationUnit === "ticks" ? v / TICKS_PER_S : p.durationUnit === "ms" ? v / 1000 : v;
}
/** Seconds typed in the editor -> the storage unit (ticks are whole numbers). */
export function fromSeconds(p: Pick<ConfigParam, "durationUnit">, s: number): number {
  return p.durationUnit === "ticks" ? Math.round(s * TICKS_PER_S) : p.durationUnit === "ms" ? Math.round(s * 1000) : Math.round(s * 1e4) / 1e4;
}

const trim = (x: number) => String(Math.round(x * 1e4) / 1e4);
export function fmt(p: Pick<ConfigParam, "type" | "unit" | "durationUnit" | "options">, v: ConfigValue | undefined): string {
  if (v === undefined) return "-";
  const u = p.unit ? ` ${p.unit}` : "";
  switch (p.type) {
    case "duration": return `${trim(toSeconds(p, v as number))} s`;
    case "number": case "int": return `${trim(v as number)}${u}`;
    case "range": return `${trim((v as number[])[0])}-${trim((v as number[])[1])}${u}`;
    case "bool": return v ? "on" : "off";
    case "enum": return String(p.options?.find((o) => o.value === v)?.label ?? v);
    case "list": return `${(v as unknown[]).length} item${(v as unknown[]).length === 1 ? "" : "s"}`;
    case "table": return `${(v as unknown[]).length} row${(v as unknown[]).length === 1 ? "" : "s"}`;
    default: return String(v);
  }
}

