export type ValuesCheck = { ok: boolean; values: ConfigValues; errors: ValueIssue[]; warnings: ValueIssue[]; clamped: string[] };

/**
 * Check a full or partial value set against the spec. Missing keys take the default. Unknown keys are errors
 * (strict) or ignored with a warning (clamp: reading a file the server owner edited). Read-only keys may not change.
 */
export function checkValues(spec: ConfigSpec, values: Record<string, unknown>, mode: ValueMode = "strict", base: ConfigValues = defaultsOf(spec)): ValuesCheck {
  const byKey = paramByKey(spec);
  const errors: ValueIssue[] = [], warnings: ValueIssue[] = [], clamped: string[] = [];
  const out: ConfigValues = { ...base };
  const entries = Object.entries(values ?? {});
  if (entries.length > CONFIG_LIMITS.params) return { ok: false, values: out, errors: [{ key: "", code: "too_many", message: `at most ${CONFIG_LIMITS.params} settings` }], warnings, clamped };
  for (const [k, raw] of entries) {
    const p = byKey.get(k);
    if (!p) { (mode === "strict" ? errors : warnings).push({ key: k, code: "unknown_key", message: `${k} is not a setting of this mod` }); continue; }
    const r = checkValue(p, raw, mode);
    if (!r.ok) { errors.push(r.error); continue; }
    if (p.readOnly && !sameValue(r.value, base[k] ?? p.default)) { errors.push({ key: k, code: "read_only", message: `${p.label} cannot be changed here` }); continue; }
    out[k] = r.value;
    if (r.clamped) clamped.push(k);
    warnings.push(...r.warnings);
  }
  for (const p of spec.params) if (!entries.some(([k]) => k === p.key)) warnings.push(...balanceWarnings(p, out[p.key]));
  return { ok: errors.length === 0, values: out, errors, warnings, clamped };
}

export function sameValue(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b || a === null || b === null || typeof a !== "object") return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) return a.length === (b as unknown[]).length && a.every((x, i) => sameValue(x, (b as unknown[])[i]));
  const ka = Object.keys(a as object).sort(), kb = Object.keys(b as object).sort();
  return ka.length === kb.length && ka.every((k, i) => k === kb[i] && sameValue((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k]));
}

// --------------------------------------------------------------------------------------------- units + display

const TICKS_PER_S = 20;
/** Duration value (in its storage unit) -> seconds, for display and the viewport. */
export function toSeconds(p: Pick<ConfigParam, "durationUnit">, v: number): number {
  return p.durationUnit === "ticks" ? v / TICKS_PER_S : p.durationUnit === "ms" ? v / 1000 : v;
}
/** Seconds typed in the editor -> the storage unit (ticks are whole numbers). */
export function fromSeconds(p: Pick<ConfigParam, "durationUnit">, s: number): number {
  return p.durationUnit === "ticks" ? Math.round(s * TICKS_PER_S) : p.durationUnit === "ms" ? Math.round(s * 1000) : Math.round(s * 1e4) / 1e4;
}

const trim = (x: number) => String(Math.round(x * 1e4) / 1e4);
export function fmt(p: Pick<ConfigParam, "type" | "unit" | "durationUnit" | "options">, v: ConfigValue | undefined): string {
  if (v === undefined) return "-";
  const u = p.unit ? ` ${p.unit}` : "";
  switch (p.type) {
    case "duration": return `${trim(toSeconds(p, v as number))} s`;
    case "number": case "int": return `${trim(v as number)}${u}`;
    case "range": return `${trim((v as number[])[0])}-${trim((v as number[])[1])}${u}`;
    case "bool": return v ? "on" : "off";
    case "enum": return String(p.options?.find((o) => o.value === v)?.label ?? v);
    case "list": return `${(v as unknown[]).length} item${(v as unknown[]).length === 1 ? "" : "s"}`;
    case "table": return `${(v as unknown[]).length} row${(v as unknown[]).length === 1 ? "" : "s"}`;
    default: return String(v);
  }
}

