// Cyrus Config Studio: DIFF + PATCH of values, presets, reset and undo. A patch is a list of { key, from, to };
// applying one checks `from` (a stale editor is a conflict, never a silent overwrite); the inverse patch is the undo.
// Pure.
import { APPLIES_RANK, paramByKey, type Applies, type ConfigSpec, type ConfigValue, type ConfigValues } from "./spec";
import { checkValues, defaultsOf, sameValue, type ValueIssue } from "./values";

export type PatchOp = { key: string; from: ConfigValue | undefined; to: ConfigValue };
export type Patch = PatchOp[];

/** Keys whose value differs from a to b (spec order, so diffs read like the form). */
export function diffValues(spec: Pick<ConfigSpec, "params">, a: ConfigValues, b: ConfigValues): Patch {
  const out: Patch = [];
  for (const p of spec.params) if (p.key in b && !sameValue(a[p.key], b[p.key])) out.push({ key: p.key, from: a[p.key], to: structuredClone(b[p.key]) });
  return out;
}

export type PatchResult = { ok: true; values: ConfigValues; warnings: ValueIssue[]; clamped: string[] } | { ok: false; errors: ValueIssue[]; conflicts: string[] };

/** Apply a patch to `base`: every `from` must match (else conflict), every `to` is checked strictly. */
export function applyPatch(spec: ConfigSpec, base: ConfigValues, patch: Patch, opts: { checkFrom?: boolean } = {}): PatchResult {
  const conflicts = opts.checkFrom === false ? [] : patch.filter((op) => !sameValue(base[op.key], op.from)).map((op) => op.key);
  if (conflicts.length) return { ok: false, errors: conflicts.map((k) => ({ key: k, code: "conflict", message: `${k} was changed by someone else since you opened it` })), conflicts };
  const r = checkValues(spec, Object.fromEntries(patch.map((op) => [op.key, op.to])), "strict", base);
  return r.ok ? { ok: true, values: r.values, warnings: r.warnings, clamped: r.clamped } : { ok: false, errors: r.errors, conflicts: [] };
}

export const invertPatch = (patch: Patch): Patch => [...patch].reverse().filter((op) => op.from !== undefined).map((op) => ({ key: op.key, from: op.to, to: op.from as ConfigValue }));

/** Put keys back to their defaults (all keys when `keys` is omitted). */
export function resetKeys(spec: ConfigSpec, values: ConfigValues, keys?: string[]): ConfigValues {
  const d = defaultsOf(spec);
  const ks = new Set(keys ?? spec.params.map((p) => p.key));
  return Object.fromEntries(spec.params.map((p) => [p.key, ks.has(p.key) && !p.readOnly ? d[p.key] : structuredClone(values[p.key] ?? d[p.key])]));
}

/** Apply a preset: only the keys it names change (every other value is kept). */
export function applyPreset(spec: ConfigSpec, values: ConfigValues, presetId: string): PatchResult {
  const pr = spec.presets.find((x) => x.id === presetId);
  if (!pr) return { ok: false, errors: [{ key: "", code: "unknown_preset", message: `no preset ${presetId}` }], conflicts: [] };
  const r = checkValues(spec, pr.values, "strict", values);
  return r.ok ? { ok: true, values: r.values, warnings: r.warnings, clamped: r.clamped } : { ok: false, errors: r.errors, conflicts: [] };
}

/** Which preset the values match exactly (on the keys that preset names): its id, "default", or "custom". */
export function matchingPreset(spec: ConfigSpec, values: ConfigValues): string {
  for (const pr of spec.presets) if (Object.entries(pr.values).every(([k, v]) => sameValue(values[k], v))) return pr.id;
  const d = defaultsOf(spec);
  return spec.params.every((p) => sameValue(values[p.key], d[p.key])) ? "default" : "custom";
}

/** How the change takes effect: the strongest `applies` among the changed keys (restart > reload > live). */
export function appliesFor(spec: ConfigSpec, keys: readonly string[]): { applies: Applies | "none"; byKey: Record<string, Applies> } {
  const byKey = paramByKey(spec);
  let best: Applies | "none" = "none";
  const out: Record<string, Applies> = {};
  for (const k of keys) {
    const p = byKey.get(k);
    if (!p) continue;
    out[k] = p.applies;
    if (best === "none" || APPLIES_RANK[p.applies] > APPLIES_RANK[best]) best = p.applies;
  }
  return { applies: best, byKey: out };
}

/** Keys that differ from the defaults (the "changed" dots in the editor). */
export const changedFromDefaults = (spec: ConfigSpec, values: ConfigValues): string[] => { const d = defaultsOf(spec); return spec.params.filter((p) => !sameValue(values[p.key], d[p.key])).map((p) => p.key); };

