/** Index of the `:` that ends a mapping key (followed by space or end), outside quotes and flow brackets; -1 if none. */
function keyColon(s: string): number {
  let q: string | null = null, depth = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) { if (c === q) { if (q === "'" && s[i + 1] === "'") { i++; continue; } q = null; } else if (q === '"' && c === "\\") i++; continue; }
    if ((c === '"' || c === "'") && i === 0) { q = c; continue; }
    if (c === "[" || c === "{") { if (i === 0) return -1; depth++; }
    else if (c === "]" || c === "}") depth--;
    else if (c === ":" && depth <= 0 && (i + 1 === s.length || s[i + 1] === " " || s[i + 1] === "\t")) return i;
  }
  return -1;
}

const isSeqItem = (t: string) => t === "-" || t.startsWith("- ") || t.startsWith("-\t");

class Parser {
  i = 0;
  nodes = 0;
  issues: string[] = [];
  constructor(readonly lines: Line[]) {}

  issue(msg: string) { if (this.issues.length < 50) this.issues.push(msg); }
  count(): boolean { this.nodes++; if (this.nodes > YAML_LIMITS.maxNodes) { if (this.nodes === YAML_LIMITS.maxNodes + 1) this.issue("too many nodes; the rest was ignored"); return false; } return true; }

  block(minIndent: number, depth: number): YamlValue {
    const l = this.lines[this.i];
    if (!l || l.indent < minIndent) return null;
    if (depth > YAML_LIMITS.maxDepth) { this.issue(`nesting deeper than ${YAML_LIMITS.maxDepth} at line ${l.n}`); this.skipFrom(minIndent); return null; }
    return isSeqItem(l.text) ? this.seq(l.indent, depth) : this.map(l.indent, depth);
  }

  skipFrom(minIndent: number) { while (this.lines[this.i] && this.lines[this.i].indent >= minIndent) this.i++; }

  seq(ind: number, depth: number): YamlValue[] {
    const out: YamlValue[] = [];
    for (let l = this.lines[this.i]; l && l.indent === ind && isSeqItem(l.text); l = this.lines[this.i]) {
      this.i++;
      if (!this.count()) { this.skipFrom(ind + 1); continue; }
      const rest = l.text.slice(1).trimStart();
      if (!rest) { out.push(this.block(ind + 1, depth + 1)); continue; }
      const childIndent = ind + (l.text.length - rest.length);
      if (isSeqItem(rest) || keyColon(rest) > 0) {
        this.i--; this.lines[this.i] = { n: l.n, indent: childIndent, text: rest, raw: l.raw };
        out.push(this.block(childIndent, depth + 1));
        continue;
      }
      out.push(this.valueText(rest, ind, depth, l));
    }
    this.strays(ind);
    return out;
  }

  map(ind: number, depth: number): { [k: string]: YamlValue } {
    const out: { [k: string]: YamlValue } = {};
    for (let l = this.lines[this.i]; l && l.indent === ind && !isSeqItem(l.text); l = this.lines[this.i]) {
      this.i++;
      if (!this.count()) { this.skipFrom(ind + 1); continue; }
      const c = keyColon(l.text);
      if (c <= 0) { this.issue(`line ${l.n}: not a 'key: value' line`); this.skipFrom(ind + 1); continue; }
      let key = l.text.slice(0, c).trim();
      if (/^(['"]).*\1$/.test(key)) key = this.quoted(key, l.n) ?? key;
      if (key.startsWith("<<") || key.startsWith("&") || key.startsWith("*")) { this.issue(`line ${l.n}: anchors, aliases and merge keys are not supported`); this.skipFrom(ind + 1); continue; }
      const rest = l.text.slice(c + 1).trim();
      let v: YamlValue;
      if (!rest) {
        const nx = this.lines[this.i];
        if (nx && nx.indent > ind) v = this.block(ind + 1, depth + 1);
        else if (nx && nx.indent === ind && isSeqItem(nx.text)) v = this.seq(ind, depth + 1);
        else v = null;
      } else v = this.valueText(rest, ind, depth, l);
      if (BAD_KEYS.has(key)) { this.issue(`line ${l.n}: key '${key}' ignored`); continue; }
      if (Object.prototype.hasOwnProperty.call(out, key)) this.issue(`line ${l.n}: duplicate key '${key}' (last one wins)`);
      out[key] = v;
    }
    this.strays(ind);
    return out;
  }

  /** Lines indented deeper than a finished block that nothing consumed. */
  strays(ind: number) {
    while (this.lines[this.i] && this.lines[this.i].indent > ind) { this.issue(`line ${this.lines[this.i].n}: unexpected indentation (ignored)`); this.i++; }
  }

  valueText(rest: string, ind: number, depth: number, l: Line): YamlValue {
    let s = rest;
    if (s.startsWith("!")) s = s.replace(/^!\S*\s*/, ""); // tags: stripped
    if (s.startsWith("&") || s.startsWith("*")) { this.issue(`line ${l.n}: anchors and aliases are not supported`); return null; }
    if (/^[|>][+-]?[0-9]?[+-]?$/.test(s)) return this.blockScalar(ind, s[0] === ">");
    if (s.startsWith("[") || s.startsWith("{")) {
      const f = new Flow(s, this, l.n, depth);
      const v = f.value();
      f.ws();
      if (f.pos < s.length) this.issue(`line ${l.n}: trailing text after a flow collection`);
      return v;
    }
    if (s.startsWith('"') || s.startsWith("'")) {
      const q = this.quoted(s, l.n);
      return q;
    }
    return plain(s);
  }

  quoted(s: string, n: number): string | null {
    const q = s[0];
    if (s.length < 2 || s[s.length - 1] !== q) { this.issue(`line ${n}: unterminated or multi-line quoted scalar`); return s.slice(1); }
    const body = s.slice(1, -1);
    if (q === "'") return body.replace(/''/g, "'");
    return body.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|.)/g, (_m, e: string) => {
      if (e[0] === "u" || e[0] === "x") return String.fromCharCode(parseInt(e.slice(1), 16));
      return ({ n: "\n", t: "\t", r: "\r", "0": "\0", '"': '"', "\\": "\\", "/": "/", " ": " " } as Record<string, string>)[e] ?? e;
    });
  }

  blockScalar(ind: number, folded: boolean): string {
    const parts: string[] = [];
    let minInd = -1;
    while (this.lines[this.i] && this.lines[this.i].indent > ind) {
      const l = this.lines[this.i++];
      if (minInd < 0) minInd = l.indent;
      parts.push(l.raw.slice(Math.min(minInd, l.indent)));
    }
    return parts.join(folded ? " " : "\n");
  }
}

function plain(s: string): string | null {
  const t = s.trim();
  if (t === "" || t === "~" || t === "null" || t === "Null" || t === "NULL") return null;
  return t;
}

class Flow {
  pos = 0;
  constructor(readonly s: string, readonly p: Parser, readonly n: number, readonly depth: number) {}
  ws() { while (this.pos < this.s.length && /\s/.test(this.s[this.pos])) this.pos++; }
  value(d = this.depth): YamlValue {
    this.ws();
    if (d > YAML_LIMITS.maxDepth) { this.p.issue(`line ${this.n}: flow nesting too deep`); this.pos = this.s.length; return null; }
    if (!this.p.count()) { this.pos = this.s.length; return null; }
    const c = this.s[this.pos];
    if (c === "[") {
      this.pos++;
      const out: YamlValue[] = [];
      for (;;) {
        this.ws();
        if (this.s[this.pos] === "]") { this.pos++; return out; }
        if (this.pos >= this.s.length) { this.p.issue(`line ${this.n}: unterminated [ ]`); return out; }
        out.push(this.value(d + 1));
        this.ws();
        if (this.s[this.pos] === ",") this.pos++;
        else if (this.s[this.pos] !== "]") { this.p.issue(`line ${this.n}: bad flow sequence`); this.pos = this.s.length; return out; }
      }
    }
    if (c === "{") {
      this.pos++;
      const out: { [k: string]: YamlValue } = {};
      for (;;) {
        this.ws();
        if (this.s[this.pos] === "}") { this.pos++; return out; }
        if (this.pos >= this.s.length) { this.p.issue(`line ${this.n}: unterminated { }`); return out; }
        const k = this.scalar(true);
        this.ws();
        let v: YamlValue = null;
        if (this.s[this.pos] === ":") { this.pos++; v = this.value(d + 1); }
        if (k != null && !BAD_KEYS.has(k)) out[k] = v;
        this.ws();
        if (this.s[this.pos] === ",") this.pos++;
        else if (this.s[this.pos] !== "}") { this.p.issue(`line ${this.n}: bad flow mapping`); this.pos = this.s.length; return out; }
      }
    }
    return this.scalar(false);
  }
  scalar(isKey: boolean): string | null {
    this.ws();
    const c = this.s[this.pos];
    if (c === '"' || c === "'") {
      let j = this.pos + 1;
      for (; j < this.s.length; j++) {
        if (this.s[j] === c) { if (c === "'" && this.s[j + 1] === "'") { j++; continue; } break; }
        if (c === '"' && this.s[j] === "\\") j++;
      }
      const tok = this.s.slice(this.pos, j + 1);
      this.pos = j + 1;
      return this.p.quoted(tok, this.n);
    }
    const start = this.pos;
    while (this.pos < this.s.length && !",]}".includes(this.s[this.pos]) && !(isKey && this.s[this.pos] === ":" && /[\s,}]|$/.test(this.s[this.pos + 1] ?? ""))) {
      this.pos++;
    }
    return plain(this.s.slice(start, this.pos));
  }
}

export function parseYaml(text: string): YamlResult {
  if (typeof text !== "string") return { value: null, issues: ["not text"] };
  if (Buffer.byteLength(text) > YAML_LIMITS.maxBytes) return { value: null, issues: [`larger than ${YAML_LIMITS.maxBytes} bytes`] };
  const lines: Line[] = [];
  const all = text.replace(/^﻿/, "").split(/\r?\n/);
  if (all.length > YAML_LIMITS.maxLines) return { value: null, issues: [`more than ${YAML_LIMITS.maxLines} lines`] };
  const pre: string[] = [];
  all.forEach((raw, idx) => {
    if (/^(---|\.\.\.)\s*$/.test(raw)) return;
    const tabLead = /^\s*\t/.test(raw);
    const expanded = raw.replace(/^[ \t]+/, (m) => m.replace(/\t/g, "  "));
    const t = stripComment(expanded);
    if (!t.trim()) return; // blank lines are dropped (inside a block scalar too: descriptions only)
    if (tabLead) pre.push(`line ${idx + 1}: tab indentation (read as 2 spaces)`);
    lines.push({ n: idx + 1, indent: t.length - t.trimStart().length, text: t.trim(), raw: expanded });
  });
  if (!lines.length) return { value: null, issues: pre };
  const p = new Parser(lines);
  p.issues.push(...pre);
  const first = p.lines[0];
  let value: YamlValue;
  if (!isSeqItem(first.text) && keyColon(first.text) <= 0 && p.lines.length === 1) value = p.valueText(first.text, -1, 0, first);
  else value = p.block(first.indent, 0);
