// aliases, multi-line flow collections, keys that are sections when a value is written. Reading values goes through the
// bounded reader in lib/cyrus/inventory/yaml.ts. Pure, never throws on bad input (returns issues).
import { parseYaml, type YamlValue } from "../inventory/yaml";

export type YamlScalar = string | number | boolean | null;
export type YamlOut = YamlScalar | YamlScalar[] | Record<string, YamlScalar>[];
export type EntryKind = "scalar" | "empty" | "flow" | "section" | "sequence" | "blockScalar" | "opaque";
export type YamlEntry = {
  path: string; line: number; indent: number; kind: EntryKind;
  /** value span on `line` (columns), for scalar / empty / flow */
  start: number; end: number;
  /** last line of the entry (its block, when it has one) */
  last: number;
  /** sequence: the indent of its "-" items */
  itemIndent?: number;
  /** the raw value text (scalar / flow) */
  raw?: string;
  /** comment lines directly above the key (no blank line in between) and the comment on the key line */
  commentAbove: string[]; commentInline: string | null;
};
export type YamlDoc = { lines: string[]; eol: "\n" | "\r\n"; finalNewline: boolean; entries: Map<string, YamlEntry>; order: string[]; indentUnit: number; issues: string[] };

const MAX_BYTES = 512 * 1024;
const MAX_LINES = 20_000;

/** [code, commentStartColumn | -1]: a `#` starts a comment at line start or after whitespace, outside quotes. */
function splitComment(s: string): [string, number] {
  let q: string | null = null;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (q) { if (c === q) { if (q === "'" && s[i + 1] === "'") { i++; continue; } q = null; } else if (q === '"' && c === "\\") i++; continue; }
    if ((c === '"' || c === "'") && (i === 0 || /[\s[{,:-]/.test(s[i - 1]))) { q = c; continue; }
