  const out: string[] = [];
  for (let k = depth; k < segs.length - 1; k++) out.push(`${" ".repeat(baseIndent + (k - depth) * doc.indentUnit)}${segs[k]}:`);
  const leafIndent = baseIndent + (segs.length - 1 - depth) * doc.indentUnit;
  const pad = " ".repeat(leafIndent);
