  if (lines.some((l) => /^\t/.test(l) || /^ *\t/.test(l))) issues.push("tab indentation: lines indented with tabs are not edited");
  const steps = new Map<number, number>();
  const stack: { indent: number; path: string }[] = [];
  /** the line index where the block of a key at `indent` (opened at `from`) ends: last content line before a line at <= indent */
  const blockEnd = (from: number, indent: number, seqAtSame: boolean) => {
    let last = from;
    for (let j = from + 1; j < lines.length; j++) {
      if (!isContent(lines[j])) continue;
      const ind = indentOf(lines[j]);
      const t = splitComment(lines[j])[0].trim();
      if (ind > indent || (seqAtSame && ind === indent && isItem(t))) { last = j; continue; }
      break;
    }
    return last;
  };
  let i = 0;
  while (i < lines.length) {
    const raw = lines[i];
    if (!isContent(raw) || /^ *\t/.test(raw)) { i++; continue; }
    const ind = indentOf(raw);
    const [code, cpos] = splitComment(raw);
    const t = code.trim();
    while (stack.length && stack[stack.length - 1].indent >= ind) stack.pop();
    if (isItem(t)) { i = blockEnd(i, ind, true) + 1; continue; } // a stray sequence (top-level list): not addressable
    const c = keyColon(code.slice(ind));
    if (c <= 0) { issues.push(`line ${i + 1}: not a 'key: value' line`); i++; continue; }
    const keyRaw = code.slice(ind, ind + c).trim();
    const key = unquoteKey(keyRaw);
    const parent = stack.length ? stack[stack.length - 1].path : "";
    if (stack.length) { const d = ind - stack[stack.length - 1].indent; steps.set(d, (steps.get(d) ?? 0) + 1); }
    const path = parent ? `${parent}.${key}` : key;
    const above: string[] = [];
    for (let j = i - 1; j >= 0; j--) { const tt = lines[j].trim(); if (tt.startsWith("#")) above.unshift(tt.replace(/^#+\s?/, "")); else break; }
    const inline = cpos >= 0 ? raw.slice(cpos).replace(/^#+\s?/, "").trim() : null;
    const vStartRaw = ind + c + 1;
    const rest = code.slice(vStartRaw);
    const lead = rest.length - rest.trimStart().length;
    const start = vStartRaw + lead;
    const value = rest.trim();
    const end = start + value.length;
    const addressable = !key.includes(".") && !/^[&*!<]/.test(keyRaw);
    if (!addressable) issues.push(`line ${i + 1}: key ${keyRaw} cannot be edited by path`);
    const put = (e: Omit<YamlEntry, "path" | "line" | "indent" | "commentAbove" | "commentInline">) => {
      if (!addressable) return;
      if (entries.has(path)) issues.push(`line ${i + 1}: duplicate key ${path} (the first one is edited)`);
      else { entries.set(path, { path, line: i, indent: ind, commentAbove: above, commentInline: inline, ...e }); order.push(path); }
    };
    if (value === "") {
      // section, sequence (indented or at the same indent) or an empty value
      let nx = i + 1;
      while (nx < lines.length && !isContent(lines[nx])) nx++;
      const nInd = nx < lines.length ? indentOf(lines[nx]) : -1;
      const nT = nx < lines.length ? splitComment(lines[nx])[0].trim() : "";
      if (nx < lines.length && (nInd > ind || (nInd === ind && isItem(nT)))) {
        if (isItem(nT)) { const last = blockEnd(i, ind, nInd === ind); put({ kind: "sequence", start, end, last, itemIndent: nInd }); i = last + 1; continue; }
        const last = blockEnd(i, ind, false);
        put({ kind: "section", start, end, last });
        stack.push({ indent: ind, path });
        i++;
        continue;
      }
      put({ kind: "empty", start: code.trimEnd().length, end: code.trimEnd().length, last: i });
      i++;
      continue;
    }
    if (/^[|>][+-]?\d?[+-]?$/.test(value)) { const last = blockEnd(i, ind, false); put({ kind: "blockScalar", start, end, last, raw: value }); i = last + 1; continue; }
    if (/^[&*!]/.test(value)) { const last = blockEnd(i, ind, false); put({ kind: "opaque", start, end, last, raw: value }); i = last + 1; continue; }
    if (value.startsWith("[") || value.startsWith("{")) {
      const closed = (value.startsWith("[") && value.endsWith("]")) || (value.startsWith("{") && value.endsWith("}"));
      const last = closed ? i : blockEnd(i, ind, false);
      put({ kind: closed ? "flow" : "opaque", start, end, last, raw: value });
      i = last + 1;
      continue;
    }
    if (/^["']/.test(value) && !(value.length > 1 && value.endsWith(value[0]))) { const last = blockEnd(i, ind, false); put({ kind: "opaque", start, end, last, raw: value }); i = last + 1; continue; }
    put({ kind: "scalar", start, end, last: i, raw: value });
    i++;
  }
  const best = [...steps.entries()].filter(([d]) => d > 0).sort((a, b) => b[1] - a[1] || a[0] - b[0])[0];
  doc.indentUnit = best ? Math.min(8, best[0]) : 2;
  return doc;
}

export function renderYamlDoc(doc: YamlDoc): string {
  return doc.lines.join(doc.eol) + (doc.finalNewline && doc.lines.length ? doc.eol : "");
}

// --------------------------------------------------------------------------------------------- values

const YAML_WORDS = /^(true|false|yes|no|on|off|y|n|null|~)$/i;
/** A scalar as YAML text. `quote` keeps the style the file used for this value; `float` keeps whole numbers as 2.0. */
export function yamlScalar(v: YamlScalar, opts: { quote?: '"' | "'" | null; float?: boolean } = {}): string {
  if (v === null) return "null";
  if (typeof v === "boolean") return v ? "true" : "false";
  if (typeof v === "number") return Number.isFinite(v) ? (opts.float && Number.isInteger(v) ? `${v}.0` : String(v)) : "0";
  const s = String(v);
  if (opts.quote === "'") return `'${s.replace(/'/g, "''")}'`;
  const plainOk = opts.quote !== '"' && s.length > 0 && s === s.trim() && !YAML_WORDS.test(s) && !/^[-+]?(\d|\.\d)/.test(s) && /^[A-Za-z_/][A-Za-z0-9_ .,/:()!?'+-]*$/.test(s) && !/: |:$| #/.test(s);
  if (plainOk) return s;
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\t/g, "\\t")}"`;
}
const quoteOf = (raw: string | undefined): '"' | "'" | null => (raw?.startsWith('"') ? '"' : raw?.startsWith("'") ? "'" : null);

export type SetOptions = { float?: boolean; comment?: string[]; quote?: '"' | "'" };
export type SetResult = { ok: true; text: string; changed: boolean } | { ok: false; error: string };

function blockLines(v: YamlScalar[] | Record<string, YamlScalar>[], itemIndent: number, unit: number, float: (k?: string) => boolean): string[] {
  const pad = " ".repeat(itemIndent);
  if (!v.length) return [];
  return v.flatMap((x) => {
    if (x && typeof x === "object") {
      const ks = Object.keys(x);
      if (!ks.length) return [`${pad}- {}`];
      return ks.map((k, j) => `${j === 0 ? `${pad}- ` : `${pad}${" ".repeat(Math.max(2, unit))}`}${yamlKey(k)}: ${yamlScalar((x as Record<string, YamlScalar>)[k], { float: float(k) })}`);
    }
    return [`${pad}- ${yamlScalar(x as YamlScalar, { float: float() })}`];
  });
}
const yamlKey = (k: string) => (/^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(k) ? k : `"${k.replace(/"/g, '\\"')}"`);
const flowList = (v: YamlScalar[], float: boolean) => `[${v.map((x) => yamlScalar(x, { float })).join(", ")}]`;

/**
 * Write one value at a dotted path. Scalars replace the value span in place (the inline comment and quote style stay),
 * lists stay in the style the file used (flow [a, b] or block "- a"), tables are block lists of maps. A missing key is
 * created (with its missing parent sections) at the end of the deepest existing section, preceded by `comment` lines.
 * `float` may be a per-column predicate for tables (column key -> keep 2.0).
 */
export function setYamlValue(text: string, path: string, value: YamlOut, opts: SetOptions & { floatCols?: (col?: string) => boolean } = {}): SetResult {
  const doc = parseYamlDoc(text);
  if (doc.issues.includes("file too large to edit")) return { ok: false, error: "the file is too large to edit" };
  const segs = path.split(".");
  if (!segs.every((s) => /^[A-Za-z0-9_][A-Za-z0-9_-]*$/.test(s))) return { ok: false, error: `${path} is not an editable key` };
  const floatCols = opts.floatCols ?? (() => !!opts.float);
  const e = doc.entries.get(path);
  const isList = Array.isArray(value);
  const isTable = isList && (value as unknown[]).some((x) => x !== null && typeof x === "object");
  const before = renderYamlDoc(doc);
  if (e) {
    if (e.kind === "section") return { ok: false, error: `${path} is a section in the file, not a value` };
    if (e.kind === "blockScalar" || e.kind === "opaque") return { ok: false, error: `${path} uses YAML the studio does not edit (block text, anchors or a multi-line list); change it in the file` };
    const line = doc.lines[e.line];
    if (!isList) {
      const quote = opts.quote ?? quoteOf(e.raw);
      const v = yamlScalar(value as YamlScalar, { quote: typeof value === "string" ? quote : null, float: opts.float });
      if (e.kind === "sequence") { doc.lines.splice(e.line, e.last - e.line + 1, `${line.slice(0, e.start).trimEnd()} ${v}${commentTail(line, e)}`); return done(doc, before); }
      doc.lines[e.line] = e.kind === "empty" ? `${line.slice(0, e.start)} ${v}${line.slice(e.end)}` : line.slice(0, e.start) + v + line.slice(e.end);
      return done(doc, before);
    }
    const list = value as YamlScalar[] | Record<string, YamlScalar>[];
    if (e.kind === "sequence" || isTable || (e.kind !== "flow" && list.length > 8)) {
      const itemIndent = e.itemIndent ?? e.indent + doc.indentUnit;
      const rows = blockLines(list, itemIndent, doc.indentUnit, floatCols);
      const head = `${line.slice(0, e.kind === "sequence" ? e.end : e.start).trimEnd()}${rows.length ? "" : " []"}${e.kind === "sequence" ? "" : commentTail(line, e)}`;
      const keepHead = e.kind === "sequence" ? line : head;
      doc.lines.splice(e.line, e.last - e.line + 1, rows.length ? keepHead : head, ...rows);
      return done(doc, before);
    }
    const v = flowList(list as YamlScalar[], !!opts.float);
    doc.lines[e.line] = e.kind === "empty" ? `${line.slice(0, e.start)} ${v}${line.slice(e.end)}` : line.slice(0, e.start) + v + line.slice(e.end);
    return done(doc, before);
  }
  // missing: find the deepest existing ancestor section
  let depth = segs.length - 1;
  let anc: YamlEntry | undefined;
  while (depth > 0) { anc = doc.entries.get(segs.slice(0, depth).join(".")); if (anc) break; depth--; }
  if (anc && anc.kind !== "section") return { ok: false, error: `${segs.slice(0, depth).join(".")} is a value in the file, so ${path} cannot be added under it` };
  const baseIndent = anc ? childIndent(doc, anc) : 0;
  const out: string[] = [];
  for (let k = depth; k < segs.length - 1; k++) out.push(`${" ".repeat(baseIndent + (k - depth) * doc.indentUnit)}${segs[k]}:`);
  const leafIndent = baseIndent + (segs.length - 1 - depth) * doc.indentUnit;
  const pad = " ".repeat(leafIndent);
  for (const c of opts.comment ?? []) out.push(`${pad}# ${c.replace(/[\r\n]+/g, " ").slice(0, 300)}`);
  const leaf = segs[segs.length - 1];
  if (isList && (isTable || (value as unknown[]).length > 8)) {
    const rows = blockLines(value as YamlScalar[], leafIndent + doc.indentUnit, doc.indentUnit, floatCols);
    out.push(rows.length ? `${pad}${leaf}:` : `${pad}${leaf}: []`, ...rows);
  } else out.push(`${pad}${leaf}: ${isList ? flowList(value as YamlScalar[], !!opts.float) : yamlScalar(value as YamlScalar, { float: opts.float, quote: opts.quote })}`);
  const at = anc ? anc.last + 1 : lastContentLine(doc) + 1;
  doc.lines.splice(at, 0, ...out);
  if (!anc && doc.lines.length === out.length) doc.finalNewline = true;
  return done(doc, before);
}

function commentTail(line: string, e: YamlEntry): string {
  const [, c] = splitComment(line);
  return c >= 0 && c > e.end - 1 ? ` ${line.slice(c)}` : "";
}
function childIndent(doc: YamlDoc, anc: YamlEntry): number {
  for (const p of doc.order) { const x = doc.entries.get(p)!; if (x.line > anc.line && x.line <= anc.last && p.startsWith(anc.path + ".") && !p.slice(anc.path.length + 1).includes(".")) return x.indent; }
  return anc.indent + doc.indentUnit;
}
function lastContentLine(doc: YamlDoc): number {
  for (let j = doc.lines.length - 1; j >= 0; j--) if (doc.lines[j].trim()) return j;
  return -1;
}
function done(doc: YamlDoc, before: string): SetResult {
  const text = renderYamlDoc(doc);
  return { ok: true, text, changed: text !== before };
}

/** The value at a dotted path, as the bounded reader sees it (strings / lists / maps; null when absent or empty). */
export function getYamlValue(text: string, path: string): { found: boolean; value: YamlValue } {
  const r = parseYaml(text);
  let cur: YamlValue = r.value;
  for (const s of path.split(".")) {
    if (!cur || typeof cur !== "object" || Array.isArray(cur) || !Object.prototype.hasOwnProperty.call(cur, s)) return { found: false, value: null };
    cur = (cur as Record<string, YamlValue>)[s];
  }
  return { found: true, value: cur };
}

