// Cyrus Config Studio: ConfigSpec <-> the mod's config file (YAML; the Paper exporter). Read the values a server's
// config.yml holds (clamped like the runtime loader), write changed values back WITHOUT touching anything else
// (comments, unknown keys, order, quoting: ./yamldoc.ts), and render a fresh, fully commented config.yml from a spec
// (every key with its label, unit, limits and help). Pure.
import type { YamlValue } from "../inventory/yaml";
import { parseYaml } from "../inventory/yaml";
import { numeric, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues } from "./spec";
import { checkValue, defaultsOf, sameValue, type ValueIssue } from "./values";
import { setYamlValue, type YamlOut, type YamlScalar } from "./yamldoc";

function at(root: YamlValue, key: string): { found: boolean; value: YamlValue } {
  let cur: YamlValue = root;
  for (const s of key.split(".")) {
    if (!cur || typeof cur !== "object" || Array.isArray(cur) || !Object.prototype.hasOwnProperty.call(cur, s)) return { found: false, value: null };
    cur = (cur as Record<string, YamlValue>)[s];
  }
  return { found: true, value: cur };
}

export type ReadResult = { values: ConfigValues; missing: string[]; clamped: string[]; errors: ValueIssue[]; issues: string[] };

/**
 * The values a config file holds for a spec. Missing keys take the default (listed in `missing`); an invalid value
 * takes the default (listed in `errors`); out-of-range numbers are clamped (listed in `clamped`), exactly what the
 * generated loader does on the server.
 */
export function readValues(spec: ConfigSpec, text: string): ReadResult {
  const r = parseYaml(text ?? "");
  const d = defaultsOf(spec);
  const out: ReadResult = { values: { ...d }, missing: [], clamped: [], errors: [], issues: r.issues };
  for (const p of spec.params) {
    const v = at(r.value, p.key);
    if (!v.found || v.value === null) { out.missing.push(p.key); continue; }
    const c = checkValue(p, v.value, "clamp");
    if (!c.ok) { out.errors.push(c.error); continue; }
    out.values[p.key] = c.value;
    if (c.clamped) out.clamped.push(p.key);
  }
  return out;
}

/** A value in the file's shape (durations stay in their storage unit). */
function toYaml(p: ConfigParam, v: ConfigValue): YamlOut {
  if (p.type === "range") return v as number[];
  return v as YamlOut;
}
const floatFor = (p: ConfigParam) => p.type === "number" || (p.type === "duration" && p.durationUnit === "s") || (p.type === "range" && !!p.step && !Number.isInteger(p.step));

/** The one-line comment Cyrus writes above a key it adds: label (unit, limits; balanced range). help */
export function keyComment(p: ConfigParam): string {
  const bits: string[] = [];
  if (p.type === "duration") bits.push(p.durationUnit === "ticks" ? "ticks, 20 = 1 s" : p.durationUnit === "ms" ? "milliseconds" : "seconds");
  else if (p.unit) bits.push(p.unit);
  if (numeric(p) && (p.min !== undefined || p.max !== undefined)) bits.push(`${p.min ?? "..."} to ${p.max ?? "..."}`);
  if (p.safe && (p.safe.min !== undefined || p.safe.max !== undefined)) bits.push(`balanced ${p.safe.min ?? "..."} to ${p.safe.max ?? "..."}`);
  if (p.type === "enum") bits.push(`one of: ${(p.options ?? []).map((o) => o.value).join(", ")}`);
  if (p.type === "bool") bits.push("true or false");
  if (p.applies === "restart") bits.push("needs a restart");
  return `${p.label}${bits.length ? ` (${bits.join("; ")})` : ""}.${p.help ? ` ${p.help}` : ""}`.slice(0, 300);
}

export type WriteResult = { ok: true; text: string; written: string[] } | { ok: false; errors: ValueIssue[] };

/** Write the values that differ from what the file holds now. Everything else in the file stays byte-identical. */
export function writeValues(spec: ConfigSpec, text: string, values: ConfigValues): WriteResult {
  const cur = readValues(spec, text);
  let t = text ?? "";
  const written: string[] = [];
  const errors: ValueIssue[] = [];
  for (const p of spec.params) {
    if (!(p.key in values)) continue;
    const c = checkValue(p, values[p.key], "strict");
    if (!c.ok) { errors.push(c.error); continue; }
    const present = !cur.missing.includes(p.key) && !cur.errors.some((e) => e.key === p.key) && !cur.clamped.includes(p.key);
    if (present && sameValue(cur.values[p.key], c.value)) continue;
    const r = setYamlValue(t, p.key, toYaml(p, c.value), {
      float: floatFor(p), comment: [keyComment(p)],
      floatCols: (col) => p.type === "table" ? p.columns?.find((x) => x.key === col)?.type === "number" : p.type === "list" ? p.item?.type === "number" : floatFor(p),
    });
    if (!r.ok) { errors.push({ key: p.key, code: "not_editable", message: r.error }); continue; }
    if (r.changed) written.push(p.key);
    t = r.text;
  }
  return errors.length ? { ok: false, errors } : { ok: true, text: t, written };
}

/**
 * A fresh config file for a spec: a header, then every key in spec order with its comment (the first key of each
 * group also carries the group's title). Built with the same editor, so the studio can always edit what it wrote.
 */
export function renderConfigYml(spec: ConfigSpec, values: ConfigValues = defaultsOf(spec), header: string[] = []): string {
  let t = header.map((h) => `# ${h}`.trimEnd()).join("\n") + (header.length ? "\n" : "");
  const seen = new Set<string>();
  const groups = new Map(spec.groups.map((g) => [g.id, g]));
  const ordered = [...spec.params].sort((a, b) => (groups.get(a.group)?.order ?? 0) - (groups.get(b.group)?.order ?? 0));
  for (const p of ordered) {
    const g = groups.get(p.group);
    const comment = [...(!seen.has(p.group) && g ? [`== ${g.label} ==${g.help ? ` ${g.help}` : ""}`] : []), keyComment(p)];
    seen.add(p.group);
    const v = (p.key in values ? values[p.key] : p.default) as ConfigValue;
    const r = setYamlValue(t, p.key, toYaml(p, v), {
      float: floatFor(p), comment,
      floatCols: (col) => p.type === "table" ? p.columns?.find((x) => x.key === col)?.type === "number" : p.type === "list" ? p.item?.type === "number" : floatFor(p),
    });
    if (r.ok) t = r.text;
  }
  return t.endsWith("\n") ? t : t + "\n";
}

export type { YamlScalar };

