  const opt = /(?:one of|options?|values?|can be|either)\s*[:=]?\s*([a-z0-9_\-|, ]+?(?:\s+or\s+[a-z0-9_-]+)?)(?:[.;)]|$)/i.exec(text) ?? /\(([a-z0-9_-]+(?:\s*\|\s*[a-z0-9_-]+)+)\)/i.exec(text);
  if (opt) {
    const list = opt[1].split(/\s*(?:\||,|\bor\b)\s*/i).map((x) => x.trim()).filter((x) => /^[A-Za-z0-9_-]{1,32}$/.test(x));
    if (list.length >= 2 && list.length <= CONFIG_LIMITS.options) h.options = [...new Set(list)];
  }
  if (/\bin ticks\b|\(ticks\b|\bticks\)|20 ticks|ticks?,/.test(t)) h.durationUnit = "ticks";
  else if (/\bin (milli ?seconds|ms)\b|\(ms\)/.test(t)) h.durationUnit = "ms";
  else if (/\bin seconds\b|\(seconds?\)|\bseconds?\)|\(s\)/.test(t)) h.durationUnit = "s";
  else if (/\bin minutes\b|\(minutes?\)/.test(t)) h.unit = "min";
  if (/percent|%/.test(t)) h.percent = true;
  if (/\bblocks?\b/.test(t) && !h.unit) h.unit = "blocks";
  return h;
}

const WORD_UNITS: [RegExp, string][] = [
  [/health|hp\b|damage|dmg|heal/i, "hp"], [/radius|range|distance|reach|spread_blocks/i, "blocks"], [/price|cost|reward_money|money|balance|coins?\b|bounty/i, "coins"],
  [/percent|pct/i, "%"], [/\bxp\b|experience|_xp|xp_/i, "xp"], [/players?\b/i, "players"],
];
const WORD_TAGS: [RegExp, string][] = [
  [/health|hp\b/i, "health"], [/damage|dmg/i, "damage"], [/speed|velocity/i, "speed"], [/cooldown|delay|interval/i, "cooldown"], [/price|cost|money|balance|coins?/i, "price"],
  [/chance|probability|odds/i, "chance"], [/message|msg|text|title|prefix|format/i, "message"], [/sound/i, "sound"], [/colou?r/i, "color"], [/enabled?|toggle|allow/i, "toggle"],
  [/spawn/i, "spawn"], [/drop|loot/i, "loot"], [/radius|range|distance/i, "range"], [/duration|time|ticks|seconds/i, "duration"],
];

function scalarKind(raw: string | undefined, v: string): "bool" | "int" | "number" | "text" {
  const quoted = !!raw && /^["']/.test(raw);
  if (quoted) return "text";
  if (BOOL_RE.test(v)) return "bool";
  if (INT_RE.test(v) && !/^[-+]?0\d/.test(v)) return "int";
  if (NUM_RE.test(v)) return "number";
  return "text";
}
const bool = (v: string) => /^(true|yes|on)$/i.test(v);

function cellOf(values: (string | null)[]): ConfigParamInput["item"] {
  const vs = values.filter((x): x is string => x !== null);
  if (vs.length && vs.every((x) => BOOL_RE.test(x))) return { type: "bool" };
  if (vs.length && vs.every((x) => INT_RE.test(x))) return { type: "int" };
  if (vs.length && vs.every((x) => NUM_RE.test(x))) return { type: "number" };
  return { type: "text", maxLength: 256 };
}
const cellValue = (type: string, v: string | null) => (v === null ? (type === "text" ? "" : type === "bool" ? false : 0) : type === "bool" ? bool(v) : type === "int" || type === "number" ? Number(v) : v);

/** plugin.yml -> the reload command, when a command's usage / description mentions reload. */
export function reloadCommandOf(pluginYml: string | undefined): string | null {
  if (!pluginYml) return null;
  const cmds = asMap(asMap(parseYaml(pluginYml).value)?.commands);
  if (!cmds) return null;
  for (const [name, def] of Object.entries(cmds)) {
    const d = asMap(def);
    const text = `${asStr(d?.usage) ?? ""} ${asStr(d?.description) ?? ""}`;
    if (/reload/i.test(text) && /^[a-z0-9_-]{1,32}$/i.test(name)) return `/${name.toLowerCase()} reload`;
  }
  return null;
}

/** Infer a ConfigSpec from an existing config file (+ plugin.yml for the reload command). */
export function inferSchema(text: string, opts: { pluginYml?: string; maxParams?: number } = {}): InferResult {
  const notes: string[] = [];
  const skipped: string[] = [];
  const parsed = parseYaml(text ?? "");
  const root = asMap(parsed.value);
  if (!root) return { ok: false, errors: ["the file has no settings (not a YAML mapping)"], notes: parsed.issues };
  const doc = parseYamlDoc(text);
  notes.push(...parsed.issues.slice(0, 10), ...doc.issues.slice(0, 10));
  const reload = reloadCommandOf(opts.pluginYml);
  const applies = reload ? "reload" : "restart";
  notes.push(reload ? `changes apply with ${reload} (from plugin.yml)` : "no reload command found in plugin.yml: changes apply on restart");
  const params: ConfigParamInput[] = [];
  const groups = new Map<string, string>();
  const max = Math.min(opts.maxParams ?? CONFIG_LIMITS.params, CONFIG_LIMITS.params);
  const groupFor = (key: string) => {
    const top = key.includes(".") ? key.split(".")[0] : "general";
    let id = slug(top);
    if (!groups.has(id) && groups.size >= CONFIG_LIMITS.groups - 1) id = "other";
    if (!groups.has(id)) groups.set(id, id === "other" ? "Other" : humanize(top));
    return id;
  };
  const visit = (v: YamlValue, key: string) => {
    if (params.length >= max) { skipped.push(key); return; }
    const m = asMap(v);
    if (m) { for (const [k, x] of Object.entries(m)) visit(x, key ? `${key}.${k}` : k); return; }
    if (!isConfigKey(key)) { skipped.push(key); notes.push(`${key}: the key cannot be edited by path (dots or symbols in its name)`); return; }
    const e: YamlEntry | undefined = doc.entries.get(key);
    if (!e || e.kind === "blockScalar" || e.kind === "opaque" || e.kind === "section") { skipped.push(key); notes.push(`${key}: ${e?.kind === "blockScalar" ? "multi-line text" : "YAML the studio does not edit"}; left as it is`); return; }
    const comment = [...e.commentAbove, ...(e.commentInline ? [e.commentInline] : [])].join(" ").replace(/\s+/g, " ").trim();
    const hints = commentHints(comment);
    const last = key.split(".").pop()!;
    const label = humanize(last);
    const help = comment ? comment.slice(0, 200) : undefined;
    const unit = WORD_UNITS.find(([re]) => re.test(last))?.[1];
    const tags = [...new Set(WORD_TAGS.filter(([re]) => re.test(key)).map(([, t]) => t))].slice(0, 8);
    const base = { key, group: groupFor(key), label, ...(help ? { help } : {}), applies, tags } as const;
    if (Array.isArray(v)) {
      if (v.every((x) => x === null || typeof x === "string")) {
        const item = cellOf(v as (string | null)[]);
        params.push({ ...base, type: "list", item, default: (v as (string | null)[]).map((x) => cellValue(item!.type, x)) as (string | number | boolean)[], maxItems: CONFIG_LIMITS.listItems });
        return;
      }
      const rows = v.map(asMap);
      if (rows.every((r) => r && Object.values(r).every((x) => x === null || typeof x === "string"))) {
        const cols = [...new Set(rows.flatMap((r) => Object.keys(r!)))].filter((c) => /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/.test(c));
        if (cols.length && cols.length <= CONFIG_LIMITS.columns) {
          const columns = cols.map((c) => ({ key: c, label: humanize(c).slice(0, 40), ...cellOf(rows.map((r) => (r![c] as string | null) ?? null))! }));
          const def = rows.map((r) => Object.fromEntries(columns.filter((c) => r![c.key] !== undefined).map((c) => [c.key, cellValue(c.type, r![c.key] as string | null)])));
          params.push({ ...base, type: "table", columns, default: def as Record<string, string | number | boolean>[], maxRows: CONFIG_LIMITS.tableRows });
          return;
        }
      }
      skipped.push(key); notes.push(`${key}: a nested list; left as it is`);
      return;
    }
    const s = v === null ? "" : String(v);
    const kind = scalarKind(e.raw, s);
    if (kind === "bool") { params.push({ ...base, type: "bool", default: bool(s) }); return; }
    if (kind === "text") {
      if (COLOR_RE.test(s)) { params.push({ ...base, type: "color", default: s }); return; }
      if (/sound/i.test(key) && SOUND_KEY_RE.test(s)) { params.push({ ...base, type: "sound-ref", default: s }); return; }
      if (hints.options && hints.options.some((o) => o.toLowerCase() === s.toLowerCase())) {
        const opts2 = hints.options.map((o) => (o.toLowerCase() === s.toLowerCase() ? s : o));
        params.push({ ...base, type: "enum", options: [...new Set(opts2)].map((o) => ({ value: o })), default: s });
        return;
      }
      params.push({ ...base, type: "text", default: s, maxLength: Math.max(256, Math.min(CONFIG_LIMITS.textChars, s.length * 2)) });
      return;
    }
    const num = Number(s);
    const isTicks = /(_|-)?ticks$/i.test(last) || /Ticks$/.test(last) || hints.durationUnit === "ticks";
    const isSecs = /(_|-)(seconds|secs|sec|s)$/i.test(last) || /Seconds$/.test(last) || hints.durationUnit === "s";
    const isMs = /(_|-)?(ms|millis)$/i.test(last) || /Millis$/.test(last) || hints.durationUnit === "ms";
    let lo = hints.min, hi = hints.max;
    if (/chance|probability/i.test(last) && lo === undefined && hi === undefined) { if (num <= 1 && !hints.percent) { lo = 0; hi = 1; } else { lo = 0; hi = 100; } }
    if ((lo !== undefined && num < lo) || (hi !== undefined && num > hi)) { notes.push(`${key}: the comment's range ${lo}-${hi} does not contain the current value ${num}; range not used`); lo = undefined; hi = undefined; }
    const lim = { ...(lo !== undefined ? { min: lo } : {}), ...(hi !== undefined ? { max: hi } : {}) };
    if ((isTicks || isSecs || isMs) && (kind === "int" || isSecs)) {
      const du = isTicks ? "ticks" : isMs ? "ms" : "s";
      params.push({ ...base, type: "duration", durationUnit: du, default: num, ...(lo === undefined ? { min: 0 } : {}), ...lim, ...(num < 0 ? { min: num } : {}) });
      return;
    }
    const isInt = kind === "int" && !/speed|multiplier|chance|factor|scale|modifier/i.test(last);
    params.push({ ...base, type: isInt ? "int" : "number", default: num, ...(hints.unit ? { unit: hints.unit } : unit ? { unit } : hints.percent ? { unit: "%" } : {}), ...lim });
  };
  for (const [k, v] of Object.entries(root)) {
    if (/^(config[-_]?version|version|schema[-_]?version)$/i.test(k) && typeof v === "string") {
      if (isConfigKey(k)) params.push({ key: k, group: groupFor(k), label: humanize(k), type: INT_RE.test(v) ? "int" : "text", default: INT_RE.test(v) ? Number(v) : v, applies, readOnly: true, advanced: true, tags: [], help: "Managed by the mod (file format version)" });
      continue;
    }
    visit(v, k);
  }
  if (!params.length) return { ok: false, errors: ["no editable settings found"], notes };
  if (skipped.length) notes.push(`${skipped.length} value${skipped.length === 1 ? "" : "s"} left out of the editor (kept in the file)`);
  const input: ConfigSpecInput = {
    schemaVersion: 1, file: "config.yml", format: "yaml", inferred: true, ...(reload ? { reload: { command: reload } } : {}),
    groups: [...groups.entries()].map(([id, label], i) => ({ id, label, order: i })), params,
  };
  const v = validateConfigSpec(input);
  if (!v.ok) return { ok: false, errors: v.errors.slice(0, 10).map((e) => `${e.path}: ${e.message}`), notes };
  return { ok: true, spec: v.spec, notes, skipped };
}

