      num("stats", "follow_range", "Follow range", 35, { unit: "blocks", min: 1, max: 128, step: 1, safe: safe(8, 64), tags: ["range"] }),
      num("stats", "knockback_resistance", "Knockback resistance", 0, { min: 0, max: 1, step: 0.05, help: "0 = normal knockback, 1 = none." }),
