      num("combat", "attack_speed", "Attack speed", 1.6, { unit: "hits/s", min: 0.1, max: 10, step: 0.1, safe: safe(0.5, 4, "sword 1.6, axe 0.8-1"), visual: { channel: "attackRate", clip: "swing", ref: 1.6 }, tags: ["speed"] }),
      num("combat", "reach", "Reach", 3, { unit: "blocks", min: 1, max: 8, step: 0.1, safe: safe(2.5, 4.5) }),
      num("combat", "knockback", "Knockback", 0.4, { min: 0, max: 5, step: 0.1, safe: safe(0, 2) }),
      num("combat", "crit_multiplier", "Critical hit multiplier", 1.5, { unit: "x", min: 1, max: 5, step: 0.1, safe: safe(1, 2.5) }),
      bool("combat", "sweep", "Sweeping attack", true),
      num("special", "chance", "Special hit chance", 0.1, { min: 0, max: 1, step: 0.01, safe: safe(0, 0.35), tags: ["chance"] }),
      num("special", "bonus_damage", "Special hit bonus damage", 4, { unit: "hp", min: 0, max: 100, step: 0.5, safe: safe(0, 12), tags: ["damage"] }),
      snd("special", "sound", "Special hit sound", "minecraft:entity.player.attack.crit"),
