    groups: [{ id: "damage", label: "Damage" }, { id: "firing", label: "Firing" }, { id: "ammo", label: "Ammo" }, { id: "handling", label: "Handling" }, { id: "sounds", label: "Sounds" }],
    params: [
      num("damage", "damage", "Damage per hit", 6, { unit: "hp", min: 0, max: 100, step: 0.5, safe: safe(2, 20), tags: ["damage"] }),
      num("damage", "headshot_multiplier", "Headshot multiplier", 2, { unit: "x", min: 1, max: 10, step: 0.1, safe: safe(1, 3) }),
      num("damage", "range", "Range", 64, { unit: "blocks", min: 1, max: 512, step: 1, safe: safe(16, 160), tags: ["range"] }),
