export const TEMPLATE_BY_ID: ReadonlyMap<TemplateId, ConfigTemplate> = new Map(TEMPLATES.map((t) => [t.id, t]));

/** Templates for a universal category (first = the main one). */
export function templateIdsForCategory(c: string): TemplateId[] {
  return TEMPLATES.filter((t) => t.categories.includes(c as CyrusCategoryId)).map((t) => t.id);
}

/** Zero-token template suggestions from a prompt / mod summary: keyword hits, best first (ties keep table order). */
export function suggestTemplates(text: string, max = 3): TemplateId[] {
  const t = ` ${String(text ?? "").toLowerCase().replace(/[^a-z0-9 ]+/g, " ")} `;
  const scored = TEMPLATES.map((tp, i) => ({ id: tp.id, i, s: tp.keywords.reduce((n, k) => n + (t.includes(` ${k} `) || t.includes(` ${k}s `) ? (k.includes(" ") ? 2 : 1) : 0), 0) }));
  return scored.filter((x) => x.s > 0).sort((a, b) => b.s - a.s || a.i - b.i).slice(0, max).map((x) => x.id);
}

export type InstantiateOptions = {
  /** Section the template's keys go under, e.g. "mobs.frost_zombie" (default: none). */
  prefix?: string;
  /** The mod's reload command; without one, "reload" settings fall back to "restart". */
  reloadCommand?: string;
  /** Only these relative keys (default: all). */
  include?: string[];
  /** Group ids get this prefix so several templates can share one spec (e.g. "frost_zombie"). */
  groupPrefix?: string;
};

/** A template -> a full, validated ConfigSpec. Throws only on a programming error (a template that does not validate). */
export function instantiateTemplate(id: TemplateId, o: InstantiateOptions = {}): ConfigSpec {
  const r = validateConfigSpec(templateSpecInput(id, o));
  if (!r.ok) throw new Error(`template ${id} does not validate: ${r.errors.map((e) => `${e.path}: ${e.message}`).join("; ")}`);
  return r.spec;
}

export function templateSpecInput(id: TemplateId, o: InstantiateOptions = {}): ConfigSpecInput {
  const t = TEMPLATE_BY_ID.get(id);
  if (!t) throw new Error(`no template ${id}`);
  const k = (rel: string) => (o.prefix ? `${o.prefix}.${rel}` : rel);
  const g = (gid: string) => (o.groupPrefix ? `${o.groupPrefix}_${gid}`.slice(0, 32) : gid);
  const keep = (rel: string) => !o.include || o.include.includes(rel);
  const params = t.params.filter((p) => keep(p.key)).map((p) => ({ ...p, key: k(p.key), group: g(p.group), applies: p.applies === "restart" ? "restart" as const : o.reloadCommand ? "reload" as const : "restart" as const }));
  const used = new Set(params.map((p) => p.group));
  return {
    schemaVersion: 1, file: "config.yml", format: "yaml", category: t.id,
    ...(o.reloadCommand ? { reload: { command: o.reloadCommand } } : {}),
    groups: t.groups.map((x, i) => ({ id: g(x.id), label: x.label, order: i, ...(x.help ? { help: x.help } : {}) })).filter((x) => used.has(x.id)),
    params,
    presets: t.presets.map((pr) => ({ id: pr.id, label: pr.label, values: Object.fromEntries(Object.entries(pr.values).filter(([rel]) => keep(rel)).map(([rel, v]) => [k(rel), v])) as Record<string, never> })).filter((pr) => Object.keys(pr.values).length),
  };
}

/** Merge several specs (e.g. two mobs + a boss) into one; keys and group ids must not collide. */
export function mergeSpecs(specs: ConfigSpec[], reloadCommand?: string): ConfigSpecInput {
  const presets = new Map<string, { id: string; label: string; values: Record<string, unknown> }>();
  for (const s of specs) for (const p of s.presets) { const cur = presets.get(p.id) ?? { id: p.id, label: p.label, values: {} }; Object.assign(cur.values, p.values); presets.set(p.id, cur); }
  return {
    schemaVersion: 1, file: specs[0]?.file ?? "config.yml", format: "yaml",
    ...(reloadCommand ? { reload: { command: reloadCommand } } : specs.find((s) => s.reload) ? { reload: specs.find((s) => s.reload)!.reload } : {}),
    groups: specs.flatMap((s) => s.groups).filter((g, i, a) => a.findIndex((x) => x.id === g.id) === i).map((g, i) => ({ ...g, order: i })),
    params: specs.flatMap((s) => s.params),
    presets: [...presets.values()] as ConfigSpecInput["presets"],
  };
}

