export const TEMPLATE_IDS = ["mob", "melee", "gun", "armor", "ability", "boss", "shop", "quest", "minigame", "world", "item", "utility"] as const;
export type TemplateId = (typeof TEMPLATE_IDS)[number];

type P = Omit<ConfigParamInput, "applies"> & { applies?: ConfigParamInput["applies"] };
export type ConfigTemplate = {
  id: TemplateId; label: string; summary: string;
  /** universal categories (lib/cyrus/categories.ts) this template serves */
  categories: CyrusCategoryId[];
  /** zero-token routing words (./templates.ts suggestTemplates) */
  keywords: string[];
  groups: { id: string; label: string; help?: string }[];
  params: P[];
  presets: { id: string; label: string; values: Record<string, unknown> }[];
};

// ---- compact builders (relative keys; applies defaults to "reload") --------------------------------------------
type O = Partial<Omit<P, "key" | "label" | "default" | "type" | "group">> & { safe?: P["safe"] };
const mk = (type: P["type"]) => (group: string, key: string, label: string, def: P["default"], o: O = {}): P => ({ key, group, type, label, default: def, ...o });
const num = mk("number"), int = mk("int"), bool = mk("bool"), text = mk("text"), color = mk("color"), snd = mk("sound-ref"), range = mk("range"), list = mk("list"), table = mk("table");
const ticks = (group: string, key: string, label: string, def: number, o: O = {}) => mk("duration")(group, key, label, def, { durationUnit: "ticks", min: 0, ...o });
const secs = (group: string, key: string, label: string, def: number, o: O = {}) => mk("duration")(group, key, label, def, { durationUnit: "s", min: 0, ...o });
const en = (group: string, key: string, label: string, def: string, values: string[], o: O = {}) => mk("enum")(group, key, label, def, { options: values.map((v) => ({ value: v })), ...o });
const asset = (group: string, key: string, label: string, kind: "texture" | "model" | "sound" | "item", o: O = {}) => mk("asset-ref")(group, key, label, "", { assetKind: kind, ...o });
const safe = (min?: number, max?: number, note?: string) => ({ ...(min !== undefined ? { min } : {}), ...(max !== undefined ? { max } : {}), ...(note ? { note } : {}) });
const LOOT_COLUMNS = [
  { key: "item", label: "Item", type: "text" as const, maxLength: 96 },
  { key: "chance", label: "Chance", type: "number" as const, min: 0, max: 1, step: 0.01 },
  { key: "min", label: "Min", type: "int" as const, min: 0, max: 64 },
  { key: "max", label: "Max", type: "int" as const, min: 0, max: 64 },
];
const EFFECTS = ["none", "speed", "strength", "resistance", "regeneration", "jump_boost", "night_vision", "fire_resistance", "slowness", "weakness", "poison", "glowing"];

