// Cyrus Config Studio: STAT -> VIEWPORT links. A param with `visual` drives the studio preview: walk speed plays the
// walk clip faster, attack speed / interval the attack clip, scale the model size, fire rate the fire clip cadence,
// a colour the tint. Pure: `visualEffects` turns values into rates; `applyToClock` drives ANY clock with a
// `setSpeed(x)` (Model Studio's PlaybackClock today, the Motion core's createClock when merged) without importing it.
import type { ConfigSpec, ConfigValues, VisualChannel } from "./spec";

export const RATE_MIN = 0.05;
export const RATE_MAX = 8;
export type VisualSource = { key: string; channel: VisualChannel; clip?: string; rate: number };
export type VisualEffects = {
  /** clip name -> playback rate (1 = as authored) */
  clipRates: Record<string, number>;
  /** uniform model scale (1 = as authored) */
  scale: number;
  tint: string | null;
  /** seconds between shots, for fireRate stats in rounds per minute */
  fireIntervalS: number | null;
  sources: VisualSource[];
};

const clampRate = (x: number) => Math.round(Math.min(RATE_MAX, Math.max(RATE_MIN, x)) * 1e4) / 1e4;

export function visualEffects(spec: Pick<ConfigSpec, "params">, values: ConfigValues): VisualEffects {
  const fx: VisualEffects = { clipRates: {}, scale: 1, tint: null, fireIntervalS: null, sources: [] };
  for (const p of spec.params) {
    if (!p.visual) continue;
    const v = values[p.key] ?? p.default;
    const { channel, clip, ref, inverse } = p.visual;
    if (channel === "tint") { if (typeof v === "string") { fx.tint = v; fx.sources.push({ key: p.key, channel, rate: 1 }); } continue; }
    if (typeof v !== "number" || !ref) continue;
    const raw = inverse ? (v > 0 ? ref / v : RATE_MAX) : v / ref;
    const rate = clampRate(raw);
    if (channel === "scale") { fx.scale = Math.round(fx.scale * Math.min(16, Math.max(0.05, raw)) * 1e4) / 1e4; fx.sources.push({ key: p.key, channel, rate: fx.scale }); continue; }
    const name = clip ?? (channel === "attackRate" ? "attack" : channel === "fireRate" ? "fire" : "walk");
    fx.clipRates[name] = clampRate((fx.clipRates[name] ?? 1) * rate);
    if (channel === "fireRate" && v > 0) fx.fireIntervalS = Math.round((60 / v) * 1e4) / 1e4;
    fx.sources.push({ key: p.key, channel, clip: name, rate });
  }
  return fx;
}

/** Keys whose change should refresh the preview. */
export const visualKeys = (spec: Pick<ConfigSpec, "params">) => spec.params.filter((p) => p.visual).map((p) => p.key);

/** Anything that plays at a speed (PlaybackClock.setSpeed, MotionClock.setSpeed, an AnimationAction.timeScale setter). */
export type SpeedTarget = { setSpeed(x: number): void };

/** Play `clip` at the rate the values give it (1 when no stat drives it). Returns the rate used. */
export function applyToClock(target: SpeedTarget, fx: VisualEffects, clip: string): number {
  const r = fx.clipRates[clip] ?? 1;
  target.setSpeed(r);
  return r;
}

