      case "int": out.push({ ...base, type: "int", default: Math.round(Number(p.value)), min: Math.ceil(p.min), max: Math.floor(p.max) }); break;
      case "ticks": out.push({ ...base, type: "duration", durationUnit: "ticks", default: Math.round(Number(p.value)), min: p.min, max: p.max }); break;
      case "text": out.push({ ...base, type: "text", default: String(p.value), maxLength: Math.max(1, Math.min(CONFIG_LIMITS.textChars, p.max)) }); break;
      case "sound": if (SOUND_KEY_RE.test(String(p.value))) out.push({ ...base, type: "sound-ref", default: String(p.value) }); else skipped.push(p.path); break;
    }
  }
  if (!out.length) return { ok: false, errors: ["the designs have no settings"] };
  const input: ConfigSpecInput = {
    schemaVersion: 1, file: "config.yml", format: "yaml", category: "designer", reload: { command: `/${o.command} reload` },
    groups: [...groups.entries()].map(([id, label], i) => ({ id, label, order: i })), params: out,
  };
  const v = validateConfigSpec(input);
  return v.ok ? { ok: true, spec: v.spec, skipped } : { ok: false, errors: v.errors.slice(0, 10).map((e) => `${e.path}: ${e.message}`) };
}

/** A studio patch -> designer ParamEdits (same paths; values as the designers expect them). */
export function toDesignerEdits(patch: Patch): { path: string; value: number | string }[] {
  return patch.filter((op) => typeof op.to === "number" || typeof op.to === "string").map((op) => ({ path: op.key, value: op.to as number | string }));
}

