// Cyrus Config and Stats Studio: the pure core (ConfigSpec, templates, values, diff/patch, comment-preserving YAML,
// schema inference, designer mapping, viewport links). Deterministic, no I/O beyond fixtures.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import {
  applyPatch, applyPreset, applyToClock, appliesFor, changedFromDefaults, checkValue, checkValues, configSpecJsonSchema, defaultsOf, diffValues,
  fromDesignerParams, inferSchema, instantiateTemplate, invertPatch, matchingPreset, mergeSpecs, paramByKey, parseYamlDoc, readValues, reloadCommandOf,
  renderConfigYml, renderYamlDoc, resetKeys, setYamlValue, suggestTemplates, templateIdsForCategory, TEMPLATES, TEMPLATE_IDS, validateConfigSpec,
  visualEffects, writeValues, fmt, toSeconds, fromSeconds, commentHints, type ConfigSpec, type ConfigSpecInput,
} from "../lib/cyrus/config";
import { compileDesigns, designParams } from "../lib/cyrus/designer/compile";
import { PlaybackClock } from "../lib/cyrus/modelstudio/clock";

const FX = path.join(import.meta.dirname, "fixtures", "cyrus-config");
const fx = (n: string) => readFileSync(path.join(FX, n), "utf8");
const ok = (r: ReturnType<typeof validateConfigSpec>) => { if (!r.ok) assert.fail(JSON.stringify(r.errors)); return r.spec; };
const lineDiff = (a: string, b: string) => { const x = a.split("\n"), y = b.split("\n"); const out: string[] = []; for (let i = 0; i < Math.max(x.length, y.length); i++) if (x[i] !== y[i]) out.push(`${i + 1}: ${x[i] ?? "<none>"} => ${y[i] ?? "<none>"}`); return out; };

const BASE: ConfigSpecInput = {
  schemaVersion: 1, reload: { command: "/frost reload" },
  groups: [{ id: "stats", label: "Stats" }],
  params: [
    { key: "mob.health", group: "stats", type: "number", label: "Health", default: 20, unit: "hp", min: 1, max: 1024, safe: { min: 4, max: 200 }, applies: "reload" },
    { key: "mob.speed", group: "stats", type: "number", label: "Speed", default: 0.23, min: 0, max: 1, applies: "reload", visual: { channel: "clipRate", clip: "walk", ref: 0.23 } },
    { key: "mob.count", group: "stats", type: "int", label: "Count", default: 3, min: 1, max: 10, applies: "restart" },
    { key: "mob.mode", group: "stats", type: "enum", label: "Mode", default: "auto", options: [{ value: "semi" }, { value: "auto" }], applies: "reload" },
    { key: "mob.cd", group: "stats", type: "duration", durationUnit: "ticks", label: "Cooldown", default: 40, min: 0, max: 1200, applies: "live" },
    { key: "mob.size", group: "stats", type: "range", label: "Group", default: [1, 4], min: 1, max: 16, applies: "reload" },
    { key: "mob.tint", group: "stats", type: "color", label: "Tint", default: "#ff8800", applies: "reload" },
    { key: "mob.biomes", group: "stats", type: "list", label: "Biomes", default: ["plains"], item: { type: "text" }, applies: "reload" },
    { key: "mob.drops", group: "stats", type: "table", label: "Drops", default: [{ item: "bone", chance: 0.5 }], columns: [{ key: "item", label: "Item", type: "text" }, { key: "chance", label: "Chance", type: "number", min: 0, max: 1 }], applies: "reload" },
    { key: "mob.ver", group: "stats", type: "int", label: "Version", default: 1, readOnly: true, applies: "restart" },
  ],
  presets: [{ id: "hard", label: "Hard", values: { "mob.health": 60, "mob.speed": 0.3 } }],
};

describe("ConfigSpec v1", () => {
  it("the committed JSON Schema matches the Zod source", () => {
    const file = JSON.parse(readFileSync(path.join(import.meta.dirname, "..", "lib/cyrus/config/config.v1.schema.json"), "utf8"));
    assert.deepEqual(file, JSON.parse(JSON.stringify(configSpecJsonSchema())));
  });
  it("accepts a full spec with every param type", () => {
    const s = ok(validateConfigSpec(BASE));
    assert.equal(s.params.length, 10);
    assert.equal(s.file, "config.yml");
  });
  it("refuses structural mistakes with structured issues", () => {
    const bad = (mut: (s: ConfigSpecInput) => void, code: string) => {
      const s = structuredClone(BASE); mut(s);
      const r = validateConfigSpec(s);
      assert.equal(r.ok, false, code);
      if (!r.ok) assert.ok(r.errors.some((e) => e.code === code), `${code}: ${JSON.stringify(r.errors)}`);
    };
    bad((s) => s.params.push({ ...s.params[0] }), "duplicate_key");
    bad((s) => s.params.push({ ...s.params[0], key: "mob.health.max" }), "key_prefix");
    bad((s) => { s.params[0].default = 2000; }, "default_outside_limits");
    bad((s) => { s.params[0].safe = { min: 0, max: 200 }; }, "safe_outside_limits");
    bad((s) => { delete s.reload; }, "reload_without_command");
    bad((s) => { delete s.params[3].options; }, "enum_options");
    bad((s) => { s.params[3].default = "burst"; }, "bad_default");
    bad((s) => { delete s.params[1].visual!.ref; }, "visual_ref");
    bad((s) => { s.params[6].visual = { channel: "scale", ref: 1 }; }, "visual_channel");
    bad((s) => { delete s.params[4].durationUnit; }, "duration_unit");
    bad((s) => { s.params[0].group = "nope"; }, "unknown_group");
    bad((s) => { s.presets![0].values["mob.nope"] = 1; }, "unknown_key");
    bad((s) => { s.presets![0].values["mob.health"] = 5000; }, "outside_limits");
    bad((s) => { s.presets![0].values["mob.ver"] = 2; }, "read_only");
    bad((s) => { s.params[2].min = 0.5; }, "int_limits");
    bad((s) => { s.params[6].min = 0; }, "limits_on_non_number");
    assert.equal(validateConfigSpec({ ...BASE, params: [{ ...BASE.params[0], key: "a..b" }] }).ok, false);
    assert.equal(validateConfigSpec({ ...BASE, params: [{ ...BASE.params[0], key: "__proto__.x" }] }).ok, false);
    assert.equal(validateConfigSpec({ ...BASE, file: "../escape.yml" }).ok, false);
  });
});

describe("category templates", () => {
  it("every template instantiates, validates, has presets that validate and defaults inside the balanced range", () => {
    assert.equal(TEMPLATES.length, 12);
    assert.deepEqual(TEMPLATES.map((t) => t.id), [...TEMPLATE_IDS]);
    for (const id of TEMPLATE_IDS) {
      for (const opts of [{}, { reloadCommand: "/mymod reload" }, { prefix: "mods.x_1", reloadCommand: "/m reload", groupPrefix: "x" }]) {
        const s = instantiateTemplate(id, opts);
        const r = validateConfigSpec(s);
        assert.ok(r.ok, id);
        if (r.ok) assert.deepEqual(r.warnings, [], `${id} warnings ${JSON.stringify(r.warnings)}`);
        assert.ok(s.params.length >= 7, `${id} offers ${s.params.length}`);
        if (!("reloadCommand" in opts)) assert.ok(s.params.every((p) => p.applies !== "reload"), `${id}: no reload command -> no reload settings`);
        for (const p of s.params) assert.ok(p.label && (p.type !== "number" || p.min !== undefined), `${id} ${p.key} has hard limits`);
      }
    }
  });
  it("offers the stats the owner asked for, with viewport links where there is a visual", () => {
    const keys = (id: (typeof TEMPLATE_IDS)[number]) => new Set(instantiateTemplate(id).params.map((p) => p.key));
    for (const k of ["max_health", "move_speed", "attack_damage", "attack_interval", "knockback", "drops", "spawn_weight", "group_size", "biomes", "scale"]) assert.ok(keys("mob").has(k), `mob ${k}`);
    for (const k of ["damage", "fire_rate", "reload_time", "magazine_size", "spread", "recoil", "fire_mode"]) assert.ok(keys("gun").has(k), `gun ${k}`);
    for (const k of ["cooldown", "range", "strength"]) assert.ok(keys("ability").has(k), `ability ${k}`);
    for (const k of ["items", "sell_multiplier"]) assert.ok(keys("shop").has(k), `shop ${k}`);
    const vis = (id: (typeof TEMPLATE_IDS)[number]) => Object.fromEntries(instantiateTemplate(id).params.filter((p) => p.visual).map((p) => [p.key, p.visual!.channel]));
    assert.deepEqual(vis("mob"), { move_speed: "clipRate", scale: "scale", attack_interval: "attackRate", glow_color: "tint" });
    assert.deepEqual(vis("gun"), { fire_rate: "fireRate", reload_time: "clipRate" });
    assert.equal(vis("melee").attack_speed, "attackRate");
  });
  it("routes prompts and categories to templates with zero tokens", () => {
    assert.equal(suggestTemplates("a frost zombie mob that drops ice and is faster at night")[0], "mob");
    assert.equal(suggestTemplates("an AK-47 rifle with ammo and a reload animation")[0], "gun");
    assert.equal(suggestTemplates("a shop where players buy diamonds with coins")[0], "shop");
    assert.equal(suggestTemplates("a fire staff spell with a cooldown")[0], "ability");
    assert.deepEqual(suggestTemplates("hello there"), []);
    assert.deepEqual(templateIdsForCategory("creatures"), ["mob", "boss"]);
    assert.deepEqual(templateIdsForCategory("economy"), ["shop"]);
  });
  it("merges several templates into one spec (two mobs + a boss)", () => {
    const a = instantiateTemplate("mob", { prefix: "mobs.frost", groupPrefix: "frost", reloadCommand: "/f reload" });
    const b = instantiateTemplate("mob", { prefix: "mobs.ash", groupPrefix: "ash", reloadCommand: "/f reload" });
    const c = instantiateTemplate("boss", { prefix: "boss", groupPrefix: "boss", reloadCommand: "/f reload" });
    const m = ok(validateConfigSpec(mergeSpecs([a, b, c])));
    assert.equal(m.params.length, a.params.length + b.params.length + c.params.length);
    assert.equal(m.presets.find((p) => p.id === "hard")!.values["mobs.ash.max_health"], 32);
  });
});

describe("values", () => {
  const s = ok(validateConfigSpec(BASE));
  const P = paramByKey(s);
  it("coerces editor/YAML text, refuses (strict) or clamps (clamp) out-of-range numbers", () => {
    assert.deepEqual(checkValue(P.get("mob.health")!, "35"), { ok: true, value: 35, clamped: false, warnings: [] });
    const r = checkValue(P.get("mob.health")!, 5000);
    assert.equal(r.ok, false);
    if (!r.ok) assert.equal(r.error.code, "outside_limits");
    const c = checkValue(P.get("mob.health")!, 5000, "clamp");
    assert.ok(c.ok && c.value === 1024 && c.clamped);
    const n = checkValue(P.get("mob.health")!, "lots");
    assert.ok(!n.ok && n.error.code === "bad_type");
    assert.ok(checkValue(P.get("mob.count")!, 2.6, "clamp").ok && (checkValue(P.get("mob.count")!, 2.6, "clamp") as { value: number }).value === 3);
    assert.equal(checkValue(P.get("mob.count")!, 2.6).ok, false);
    assert.deepEqual((checkValue(P.get("mob.size")!, "2-5") as { value: unknown }).value, [2, 5]);
    assert.equal(checkValue(P.get("mob.size")!, [5, 2]).ok, false);
    assert.equal(checkValue(P.get("mob.tint")!, "orange").ok, false);
    assert.equal(checkValue(P.get("mob.mode")!, "burst").ok, false);
    assert.ok(checkValue(P.get("mob.drops")!, [{ item: "x", chance: "0.25" }]).ok);
    assert.equal(checkValue(P.get("mob.drops")!, [{ item: "x", chance: 3 }]).ok, false);
    assert.deepEqual((checkValue(P.get("mob.drops")!, [{ item: "x", chance: 3 }], "clamp") as { value: unknown }).value, [{ item: "x", chance: 1 }]);
  });
  it("balance warnings outside the safe range, never errors", () => {
    const r = checkValue(P.get("mob.health")!, 500);
    assert.ok(r.ok);
    if (r.ok) { assert.equal(r.warnings.length, 1); assert.equal(r.warnings[0].code, "above_balanced"); assert.match(r.warnings[0].message, /200 hp or less/); }
  });
  it("checkValues fills defaults, refuses unknown and read-only keys", () => {
    const r = checkValues(s, { "mob.health": 30 });
    assert.ok(r.ok);
    assert.equal(r.values["mob.health"], 30);
    assert.equal(r.values["mob.speed"], 0.23);
    assert.equal(checkValues(s, { "mob.nope": 1 }).ok, false);
    assert.equal(checkValues(s, { "mob.nope": 1 }, "clamp").ok, true);
    assert.equal(checkValues(s, { "mob.ver": 2 }).errors[0].code, "read_only");
  });
  it("durations display in seconds", () => {
    assert.equal(toSeconds(P.get("mob.cd")!, 40), 2);
    assert.equal(fromSeconds(P.get("mob.cd")!, 2.5), 50);
    assert.equal(fmt(P.get("mob.cd")!, 40), "2 s");
    assert.equal(fmt(P.get("mob.health")!, 20), "20 hp");
    assert.equal(fmt(P.get("mob.size")!, [1, 4]), "1-4");
  });
});

describe("diff, patch, presets, reset, undo", () => {
  const s = ok(validateConfigSpec(BASE));
  const d = defaultsOf(s);
  it("diff -> patch -> apply -> invert is a round trip; a stale from is a conflict", () => {
    const next = { ...d, "mob.health": 50, "mob.biomes": ["plains", "taiga"] };
    const patch = diffValues(s, d, next);
    assert.deepEqual(patch.map((p) => p.key), ["mob.health", "mob.biomes"]);
    const a = applyPatch(s, d, patch);
    assert.ok(a.ok);
    if (!a.ok) return;
    assert.equal(a.values["mob.health"], 50);
    const undo = applyPatch(s, a.values, invertPatch(patch));
    assert.ok(undo.ok && diffValues(s, d, undo.values).length === 0);
    const stale = applyPatch(s, { ...d, "mob.health": 99 }, patch);
    assert.ok(!stale.ok && stale.conflicts[0] === "mob.health");
    const bad = applyPatch(s, d, [{ key: "mob.health", from: 20, to: 99999 }]);
    assert.ok(!bad.ok && bad.errors[0].code === "outside_limits");
  });
  it("presets touch only their keys; matchingPreset, reset, appliesFor", () => {
    const p = applyPreset(s, { ...d, "mob.count": 7 }, "hard");
    assert.ok(p.ok);
    if (!p.ok) return;
    assert.equal(p.values["mob.health"], 60);
    assert.equal(p.values["mob.count"], 7);
    assert.equal(matchingPreset(s, p.values), "hard");
    assert.equal(matchingPreset(s, d), "default");
    assert.equal(matchingPreset(s, { ...d, "mob.health": 21 }), "custom");
    assert.deepEqual(changedFromDefaults(s, p.values), ["mob.health", "mob.speed", "mob.count"]);
    const r = resetKeys(s, p.values, ["mob.health"]);
    assert.equal(r["mob.health"], 20);
    assert.equal(r["mob.speed"], 0.3);
    assert.deepEqual(resetKeys(s, p.values), d);
    assert.equal(appliesFor(s, ["mob.cd"]).applies, "live");
    assert.equal(appliesFor(s, ["mob.cd", "mob.health"]).applies, "reload");
    assert.equal(appliesFor(s, ["mob.health", "mob.count"]).applies, "restart");
    assert.equal(appliesFor(s, []).applies, "none");
  });
});

describe("comment-preserving config.yml editor", () => {
  const ALL = ["mobs.yml", "guns.yml", "shop.yml", "arena.yml", "utility.yml", "crlf.yml"];
  it("parse + render is byte-identical for every fixture", () => {
    for (const f of ALL) assert.equal(renderYamlDoc(parseYamlDoc(fx(f))), fx(f), f);
  });
  it("a scalar edit changes one value span: comments, quotes and spacing stay", () => {
    const t = fx("mobs.yml");
    const r = setYamlValue(t, "mobs.frost_zombie.damage", 6, { float: true });
    assert.ok(r.ok);
    if (!r.ok) return;
    assert.deepEqual(lineDiff(t, r.text), ["17:     damage: 4.5   # per hit =>     damage: 6.0   # per hit"]);
    const back = setYamlValue(r.text, "mobs.frost_zombie.damage", 4.5, { float: true });
    assert.ok(back.ok && back.text === t, "set back = original bytes");
    const q = setYamlValue(t, "mobs.frost_zombie.display-name", "&3Ice Zombie");
    assert.ok(q.ok && q.text.includes('display-name: "&3Ice Zombie"'));
    const g = setYamlValue(fx("guns.yml"), "weapons.pistol.name", "Old Pistol");
    assert.ok(g.ok && g.text.includes("name: 'Old Pistol'"), "single quotes kept");
  });
  it("lists keep their style; tables are block lists of maps", () => {
    const t = fx("mobs.yml");
    const flow = setYamlValue(t, "mobs.ice_spider.biomes", ["FROZEN_PEAKS"]);
    assert.ok(flow.ok && flow.text.includes("biomes: [FROZEN_PEAKS]"));
    const block = setYamlValue(t, "mobs.frost_zombie.biomes", ["SNOWY_PLAINS", "GROVE", "ICE_SPIKES"]);
    assert.ok(block.ok);
    if (block.ok) assert.deepEqual(lineDiff(t, block.text).slice(0, 2), ["22:       - ICE_SPIKES =>       - GROVE", "23:     drops: =>       - ICE_SPIKES"]);
    const tbl = setYamlValue(t, "mobs.frost_zombie.drops", [{ item: "PACKED_ICE", chance: 0.75, amount: 2 }], { floatCols: (c) => c === "chance" });
    assert.ok(tbl.ok);
    if (tbl.ok) {
      assert.match(tbl.text, /    drops:\n      - item: PACKED_ICE\n        chance: 0.75\n        amount: 2\n  ice_spider:/);
      assert.equal(readValues(inferOk(fx("mobs.yml")), tbl.text).values["mobs.frost_zombie.drops"].toString(), [{ item: "PACKED_ICE", chance: 0.75, amount: 2 }].toString());
    }
  });
  it("missing keys are inserted at the end of their section with a comment; new sections at the end", () => {
    const t = fx("arena.yml");
    const r = setYamlValue(t, "game.sudden-death", true, { comment: ["Sudden death (true or false)."] });
    assert.ok(r.ok);
    if (!r.ok) return;
    assert.match(r.text, /  kits: \[warrior, archer, healer\]\n  # Sudden death \(true or false\)\.\n  sudden-death: true\n\nscoring:/);
    const n = setYamlValue(t, "bossbar.style.color", "purple");
    assert.ok(n.ok && n.text.endsWith("  streak-multiplier: 1.5\nbossbar:\n  style:\n    color: purple\n"));
    const e = setYamlValue("", "a.b", 1);
    assert.ok(e.ok && e.text === "a:\n  b: 1\n");
  });
  it("keeps CRLF line endings", () => {
    const r = setYamlValue(fx("crlf.yml"), "settings.party-size", 6);
    assert.ok(r.ok && r.text === fx("crlf.yml").replace("party-size: 4", "party-size: 6"));
  });
  it("refuses what it cannot edit safely (block text, anchors, sections, values under a scalar)", () => {
    const t = fx("utility.yml");
    for (const k of ["motd", "aliases"]) { const r = setYamlValue(t, k, "x"); assert.equal(r.ok, false, k); }
    assert.equal(setYamlValue(t, "teleport", 5).ok, false);
    assert.equal(setYamlValue(t, "prefix.sub", 5).ok, false);
    assert.equal(setYamlValue(t, "legacy.flow-map", 5).ok, true, "a one-line flow map is replaced as a whole");
  });
});

function inferOk(text: string, pluginYml?: string): ConfigSpec {
  const r = inferSchema(text, { pluginYml });
  if (!r.ok) assert.fail(r.errors.join("; "));
  return r.spec;
}

describe("schema inference from an existing config.yml", () => {
  const PY = "name: FrostMobs\nmain: a.B\nversion: 1\ncommands:\n  frostmobs:\n    description: Frost mobs admin\n    usage: /frostmobs <reload|spawn>\n";
  it("mob plugin: types, ranges from comments, durations from key suffixes, lists and drop tables", () => {
    const s = inferOk(fx("mobs.yml"), PY);
    const P = paramByKey(s);
    assert.equal(s.inferred, true);
    assert.deepEqual(s.reload, { command: "/frostmobs reload" });
    assert.equal(P.get("settings.debug")!.type, "bool");
    assert.deepEqual([P.get("settings.spawn-task-ticks")!.type, P.get("settings.spawn-task-ticks")!.durationUnit], ["duration", "ticks"]);
    const hp = P.get("mobs.frost_zombie.health")!;
    assert.deepEqual([hp.type, hp.min, hp.max, hp.unit, hp.default, hp.applies], ["int", 1, 1024, "hp", 40, "reload"]);
    assert.equal(hp.help, "Health in half-hearts (1-1024)");
    assert.equal(P.get("mobs.frost_zombie.speed")!.type, "number");
    assert.equal(P.get("mobs.frost_zombie.damage")!.help, "per hit");
    assert.deepEqual([P.get("mobs.frost_zombie.slow-chance")!.min, P.get("mobs.frost_zombie.slow-chance")!.max], [0, 1]);
    assert.deepEqual([P.get("mobs.frost_zombie.slow-seconds")!.type, P.get("mobs.frost_zombie.slow-seconds")!.durationUnit], ["duration", "s"]);
    assert.deepEqual(P.get("mobs.frost_zombie.biomes")!.default, ["SNOWY_PLAINS", "ICE_SPIKES"]);
    assert.deepEqual(P.get("mobs.ice_spider.biomes")!.default, ["FROZEN_PEAKS", "SNOWY_SLOPES"]);
    const drops = P.get("mobs.frost_zombie.drops")!;
    assert.equal(drops.type, "table");
    assert.deepEqual(drops.columns!.map((c) => [c.key, c.type]), [["item", "text"], ["chance", "number"], ["amount", "int"]]);
    assert.deepEqual(s.groups.map((g) => g.id), ["settings", "mobs"]);
    assert.ok(s.params.every((p) => !p.safe), "no balance claims");
  });
  it("gun plugin: enum from 'one of', ranges, sounds, read-only version", () => {
    const s = inferOk(fx("guns.yml"));
    const P = paramByKey(s);
    assert.deepEqual(s.reload, undefined);
    assert.ok(s.params.every((p) => p.applies === "restart"), "no reload command known: restart");
    assert.deepEqual(P.get("weapons.ak47.fire-mode")!.options!.map((o) => o.value), ["semi", "burst", "auto"]);
    assert.deepEqual([P.get("weapons.ak47.fire-rate")!.min, P.get("weapons.ak47.fire-rate")!.max], [1, 1200]);
    assert.deepEqual([P.get("weapons.ak47.spread")!.min, P.get("weapons.ak47.spread")!.max], [0, 45]);
    assert.equal(P.get("weapons.ak47.sounds.shoot")!.type, "sound-ref");
    assert.equal(P.get("weapons.ak47.reload-ticks")!.type, "duration");
    assert.equal(P.get("config-version")!.readOnly, true);
    assert.equal(P.get("weapons.pistol.name")!.type, "text");
  });
  it("shop plugin: tables of prices, money units, max from a comment, messages as text", () => {
    const s = inferOk(fx("shop.yml"));
    const P = paramByKey(s);
    assert.equal(P.get("currency.starting-balance")!.unit, "coins");
    assert.equal(P.get("sell-multiplier")!.max, 1);
    assert.equal(P.get("currency.symbol")!.type, "text");
    assert.equal(P.get("shop.items")!.type, "table");
    assert.equal(P.get("messages.not-enough-money")!.type, "text");
    assert.ok(P.get("messages.prefix")!.tags.includes("message"));
  });
  it("arena plugin: second durations, colours, flow lists, a range in a comment", () => {
    const s = inferOk(fx("arena.yml"));
    const P = paramByKey(s);
    assert.equal(P.get("lobby.countdown-seconds")!.durationUnit, "s");
    assert.equal(P.get("game.winner-color")!.type, "color");
    assert.deepEqual(P.get("game.kits")!.default, ["warrior", "archer", "healer"]);
    assert.deepEqual([P.get("scoring.streak-multiplier")!.min, P.get("scoring.streak-multiplier")!.max], [1, 3]);
    assert.equal(P.get("game.pvp")!.type, "bool");
  });
  it("utility plugin: inline comments, enums, minutes; block text, anchors, dotted keys and flow maps left out", () => {
    const r = inferSchema(fx("utility.yml"));
    assert.ok(r.ok);
    if (!r.ok) return;
    const P = paramByKey(r.spec);
    assert.equal(P.get("max-homes")!.help, "per player; staff have a permission for more");
    assert.deepEqual(P.get("log-level")!.options!.map((o) => o.value), ["error", "warn", "info", "debug"]);
    assert.equal(P.get("broadcast.interval-minutes")!.unit, "min");
    assert.equal(P.get("teleport.sound")!.type, "sound-ref");
    assert.equal(P.get("prefix")!.default, "&8[&bHomes&8]&r ");
    for (const k of ["motd", "aliases", "legacy.flow-map.a"]) assert.ok(!P.has(k), k);
    assert.ok(r.skipped.includes("motd") && r.skipped.includes("aliases"));
  });
  it("CRLF file and plugin.yml reload detection", () => {
    const s = inferOk(fx("crlf.yml"));
    assert.deepEqual([paramByKey(s).get("settings.party-size")!.min, paramByKey(s).get("settings.party-size")!.max], [1, 10]);
    assert.equal(reloadCommandOf("commands:\n  homes:\n    usage: /homes reload\n"), "/homes reload");
    assert.equal(reloadCommandOf("commands:\n  homes:\n    usage: /homes <name>\n"), null);
    assert.deepEqual(commentHints("between 2 and 9 blocks"), { min: 2, max: 9, unit: "blocks" });
  });
  it("read -> write of an inferred spec only touches the changed values (every fixture)", () => {
    for (const f of ["mobs.yml", "guns.yml", "shop.yml", "arena.yml", "utility.yml"]) {
      const t = fx(f);
      const s = inferOk(t);
      const cur = readValues(s, t);
      assert.deepEqual(cur.missing, [], f);
      assert.deepEqual(cur.errors, [], f);
      const same = writeValues(s, t, cur.values);
      assert.ok(same.ok && same.text === t && same.written.length === 0, `${f}: writing the same values changes nothing`);
      const num = s.params.find((p) => p.type === "int" && !p.readOnly && p.max === undefined)!;
      const w = writeValues(s, t, { ...cur.values, [num.key]: (cur.values[num.key] as number) + 1 });
      assert.ok(w.ok, f);
      if (w.ok) { assert.equal(lineDiff(t, w.text).length, 1, `${f}: one line changed (${num.key})`); assert.equal(readValues(s, w.text).values[num.key], (cur.values[num.key] as number) + 1); }
    }
  });
});

describe("rendered config.yml and the designers' params (one param model)", () => {
  it("a template renders a commented config.yml that reads back to its defaults and infers back to the same keys", () => {
    const s = instantiateTemplate("mob", { prefix: "mobs.frost_zombie", reloadCommand: "/frost reload" });
    const y = renderConfigYml(s, defaultsOf(s), ["FrostMobs configuration (generated by Cyrus)"]);
    assert.match(y, /^# FrostMobs configuration \(generated by Cyrus\)\nmobs:\n  frost_zombie:\n    # == Stats ==\n    # Max health \(hp; 1 to 1024; balanced 4 to 200\)\.\n    max_health: 20\.0\n/);
    const r = readValues(s, y);
    assert.deepEqual(r.missing, []);
    assert.deepEqual(r.values, defaultsOf(s));
    const inf = inferOk(y);
    assert.deepEqual(inf.params.map((p) => p.key).sort(), s.params.map((p) => p.key).sort());
    const T = paramByKey(inf);
    for (const p of s.params) {
      const want = p.type === "duration" ? "duration" : p.type === "sound-ref" ? "sound-ref" : p.type === "asset-ref" || p.type === "enum" ? T.get(p.key)!.type : p.type === "range" ? "list" : p.type;
      assert.equal(T.get(p.key)!.type === "int" && p.type === "number" ? "number" : T.get(p.key)!.type, want, p.key);
    }
  });
  const designs = () => ["void_reaper", "storm_staff", "vigor_tonic"].map((n) => JSON.parse(readFileSync(path.join(import.meta.dirname, "fixtures/cyrus-designer", `${n}.json`), "utf8")));
  it("designer params map into a valid ConfigSpec that reads the designer's own config.yml exactly", () => {
    const c = compileDesigns(designs(), { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(c.ok);
    if (!c.ok) return;
    const r = fromDesignerParams(c.params, { command: c.command });
    assert.ok(r.ok);
    if (!r.ok) return;
    assert.equal(r.spec.params.length + r.skipped.length, c.params.length);
    assert.deepEqual(r.spec.params.map((p) => p.key), c.params.filter((p) => !r.skipped.includes(p.path)).map((p) => p.path));
    assert.equal(r.spec.reload!.command, `/${c.command} reload`);
    const yml = c.files.find((f) => f.path.endsWith("config.yml"))!.content;
    assert.equal(renderYamlDoc(parseYamlDoc(yml)), yml);
    const vals = readValues(r.spec, yml);
    assert.deepEqual([vals.missing, vals.errors, vals.clamped], [[], [], []]);
    for (const p of c.params) if (!r.skipped.includes(p.path)) assert.equal(vals.values[p.path], p.kind === "text" || p.kind === "sound" ? p.value : Number(p.value), p.path);
    // a studio change to a designer value rewrites one line of config.yml (no Java, no recompile)
    const cd = "items.void_reaper.abilities.void_pull.cooldown_ticks";
    const w = writeValues(r.spec, yml, { ...vals.values, [cd]: 100 });
    assert.ok(w.ok);
    if (w.ok) { assert.deepEqual(w.written, [cd]); assert.equal(lineDiff(yml, w.text).length, 1); }
    assert.ok(designParams(c.designs).length === c.params.length);
  });
});

describe("viewport links", () => {
  it("stats drive clip rates, scale and fire cadence; any setSpeed clock follows", () => {
    const mob = instantiateTemplate("mob");
    const fx0 = visualEffects(mob, defaultsOf(mob));
    assert.deepEqual([fx0.clipRates.walk, fx0.clipRates.attack, fx0.scale], [1, 1, 1]);
    const fx1 = visualEffects(mob, { ...defaultsOf(mob), move_speed: 0.46, attack_interval: 10, scale: 2 });
    assert.deepEqual([fx1.clipRates.walk, fx1.clipRates.attack, fx1.scale], [2, 2, 2]);
    const gun = instantiateTemplate("gun");
    const g = visualEffects(gun, { ...defaultsOf(gun), fire_rate: 1200, reload_time: 100 });
    assert.deepEqual([g.clipRates.fire, g.clipRates.reload, g.fireIntervalS], [2, 0.5, 0.05]);
    const clock = new PlaybackClock({ end: 1 });
    assert.equal(applyToClock(clock, fx1, "walk"), 2);
    assert.equal(clock.state.speed, 2);
    clock.play(); clock.tick(0.25);
    assert.equal(clock.time, 0.5, "the walk clip advances twice as fast");
    assert.equal(applyToClock(clock, fx1, "idle"), 1);
    const extreme = visualEffects(mob, { ...defaultsOf(mob), move_speed: 1, scale: 8 });
    assert.ok(extreme.clipRates.walk <= 8 && extreme.scale === 8);
  });
});

