// Keep the model inside its lane: only src/main/** and modbuilder.json survive,
// Gradle files always come from the pinned template.
// Texture specs (assets/textures/<name>.json) survive only when the request allows textures; otherwise the ones the
// base build already had are KEPT byte for byte (keeping is never gated) and anything new or changed is removed.
function sanitizeWorkspace(ws, rec) {
  const texturesOn = texOn(rec), soundsOn = sndOn(rec), datapackOn = dpOn(rec), creaturesOn = creOn(rec), designsOn = dsOn(rec), itemModelsOn = imOn(rec);
  const kept = keptSpecs.get(rec.id) || new Map();
  SND.dropCatalog(ws); // the read-only library catalog never survives into the source
  for (const f of listFiles(ws)) {
    const spec = TX.TEXTURE_FILE_RE.test(f.rel);
    const sound = SND.SOUND_FILE_RE.test(f.rel);
    const dpack = DPK.DATAPACK_FILE_RE.test(f.rel);
    const creature = CR.CREATURE_FILE_RE.test(f.rel);
    const design = DZS.DESIGN_FILE_RE.test(f.rel);
    const itemmodel = IMS.ITEMMODEL_FILE_RE.test(f.rel);
    const keep = ((spec && !texturesOn) || (sound && !soundsOn) || (dpack && !datapackOn) || (creature && !creaturesOn) || (design && !designsOn) || (itemmodel && !itemModelsOn)) && kept.has(f.rel) && fs.readFileSync(f.abs).equals(kept.get(f.rel));
    const ok = (f.rel.startsWith("src/main/java/") || f.rel.startsWith("src/main/resources/") || f.rel === "modbuilder.json"
      || f.rel === "build.gradle.kts" || f.rel === "settings.gradle.kts" || (spec && texturesOn) || (sound && soundsOn) || (dpack && datapackOn) || (creature && creaturesOn) || (design && designsOn) || (itemmodel && itemModelsOn) || keep)
      // Cyrus import: an imported workspace keeps a narrower allow-list (Java sources + data resources only)
      && (!rec.imported || IMP.importPathAllowed(f.rel) || (spec && texturesOn) || (sound && soundsOn) || (dpack && datapackOn) || (creature && creaturesOn) || (design && designsOn) || (itemmodel && itemModelsOn) || keep);
    if (!ok) {
      fs.rmSync(f.abs, { force: true });
      event(rec, rec.status, `${rec.imported ? "Rejected a change outside the files Cyrus may edit" : "Removed unexpected file"} ${f.rel}`);
      if (rec.imported) rec.rejectedPaths = [...(rec.rejectedPaths || []), f.rel.slice(0, 200)].slice(-40);
    }
  }
  {
    // kept only ever holds specs of a kind this build may not edit: put back anything that was changed or removed
    for (const [rel, bytes] of kept) {
      const abs = path.join(ws, rel);
      if (!fs.existsSync(abs)) { fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, bytes); }
    }
  }
  for (const g of ["build.gradle.kts", "settings.gradle.kts"]) fs.copyFileSync(path.join(TEMPLATE, g), path.join(ws, g));
}

// Cyrus R3: one DESIGN round (designer route only), before validate(). HARD design problems go back to the model (shared
// MAX_ASSET_REPAIRS + the overall cap); afterwards failing designs are DROPPED (customer-visible), the rest re-checked
