    service: { texture, sound, namespace: project.namespace, ...(sound ? { library: (deps.soundLibraryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))() } : {}), ...(plan?.allowed.creature ? { creature: true as const } : {}), ...(dp.route ? { datapack: true as const } : {}), ...(dz.route ? { design: true as const } : {}), ...(dz.route && dz.gameplay ? { gameplay: true as const } : {}), ...(dp.route && dp.worldgen ? { worldgen: true as const } : {}), ...(im.route ? { itemmodel: true as const } : {}) },
    meta: { ...meta, projectId: project.id, namespace: project.namespace, ...(im.route ? { itemStates: { route: true, matched: im.matched } } : {}) },
  };
}

/** Asset kinds a stored build result already carries (ModBuild.result.assets, written by lib/cyrus/assets/sync.ts). */
export function existingAssetKinds(result: unknown): BuildAssetKind[] {
  const a = (result as { assets?: { textures?: unknown[]; sounds?: unknown[]; creatures?: unknown[] } } | null)?.assets;
  return [
    ...(Array.isArray(a?.textures) && a!.textures!.length ? (["texture"] as const) : []),
    ...(Array.isArray(a?.sounds) && a!.sounds!.length ? (["sound"] as const) : []),
    ...(Array.isArray(a?.creatures) && a!.creatures!.length ? (["creature"] as const) : []),
