// Cyrus R3 gameplay designers: does a BUILD get the designer route? Pure + deterministic (no AI call; server side).
// Item-with-abilities requests (a weapon/staff/tonic/... plus an ability word: cooldown, right-click, charge, mark,
// pull, projectile, buff...) are built from a typed ItemDesign instead of free-form Java; menu / quest requests (a shop,
// a GUI, a dialogue, quests, missions, daily tasks; not auctions, player trading, banks, claims or minigames) are built
// from typed MenuDesign / QuestDesign files (./gameplay). OFF unless CYRUS_DESIGNER=1
// (fail closed): off, nothing is decided, nothing is recorded and the build request stays byte-identical. Designers are
// NOT plan-gated (owner decision); any texture / sound / model the design references still goes through the asset gates
// (the texture and sound routes decide those, not this one).
import { designFeatures } from "./spec";

export const DESIGNER_FLAG = "CYRUS_DESIGNER";
export const designerOn = (env: Record<string, string | undefined> = process.env) => env[DESIGNER_FLAG] === "1";

/** The thing the request is about (an item). */
export const ITEM_WORDS = /\b(swords?|blades?|katanas?|staffs?|staves|wands?|scythes?|daggers?|axes?|hammers?|maces?|spears?|halberds?|weapons?|relics?|amulets?|talismans?|tonics?|potions?|elixirs?|rods?|orbs?|gauntlets?|tridents?|bows?|crossbows?|shields?|charms?|custom items?|magic items?|artifacts?|gun|rifle|pistol|launcher)\b/i;
/** What it does (an ability the graph can express). */
export const ABILITY_WORDS = /\b(abilit(?:y|ies)|cooldowns?|right[- ]?clicks?|left[- ]?clicks?|sneak(?:ing)?|shift[- ]?(?:right[- ]?)?click|charges?|charged|charging|marks?|marked|pulls?|pulled|dash(?:es)?|blinks?|teleports?|launch(?:es)?|shoots?|fires?|projectiles?|bolts?|buffs?|heals?|healing|on hit|on kill|when (?:you )?(?:hit|kill|eat|drink|join|die)|passive|knockback|lifesteal|special attack|slows?|stuns?)\b/i;

/** R3 menus: an inventory GUI the menu designer can build (shops, selectors, kit menus, dialogues). */
export const MENU_WORDS = /\b(gui|guis|menus?|inventory (?:menu|gui|screen)|chest (?:menu|gui)|shops?|shop keepers?|shopkeepers?|selectors?|kit menu|warp menu|npc dialogues?|dialogues?|dialogs?)\b/i;
/** R3 quests: quest chains, objectives, daily tasks. */
export const QUEST_WORDS = /\b(quest ?chains?|quest givers?|quest objectives?|questlines?|quests?|missions?|daily (?:tasks?|challenges?|quests?)|weekly (?:tasks?|challenges?|quests?)|bounty|bounties)\b/i;
/** Requests the menu/quest IR cannot express honestly (player-to-player trading, auctions, banks, claims, minigames): no gameplay route. */
export const GAMEPLAY_EXCLUDE = /\b(auction(?: house)?s?|player[- ]to[- ]player|trade with (?:other )?players|player shops?|chest shops?|sign shops?|bank(?:s|ing)?|loans?|land claims?|claims?|minigames?|bed ?wars|sky ?wars|parkour|leaderboards?|databases?|mysql|web ?hooks?|discord)\b/i;

export type DesignerRouteInput = { text: string; explicit?: unknown; existing?: boolean; /** R3: the base build already ships menu / quest designs (keeps the MENUS AND QUESTS prompt part on change builds). */ existingGameplay?: boolean; mcVersion: string; on: boolean };
export type DesignerRouteDecision = { route: boolean; matched: string[]; notices: string[]; limits: string[]; /** R3: menu / quest words matched (present only then): the prompt gets the MENUS AND QUESTS part. */ gameplay?: { menus: boolean; quests: boolean } };

/** Menu / quest words (and no excluded feature): the gameplay part of the designer route. */
export function matchGameplayWords(text: string): { menus: boolean; quests: boolean; matched: string[] } {
  const t = text ?? "";
  if (GAMEPLAY_EXCLUDE.test(t)) return { menus: false, quests: false, matched: [] };
  const m = MENU_WORDS.exec(t), q = QUEST_WORDS.exec(t);
  return { menus: !!m, quests: !!q, matched: [...(m ? [`menu:${m[0].toLowerCase()}`] : []), ...(q ? [`quest:${q[0].toLowerCase()}`] : [])] };
}

const explicitDesign = (raw: unknown) => (Array.isArray(raw) ? raw.includes("design") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).design === true);

export function matchDesignerWords(text: string): string[] {
  const i = ITEM_WORDS.exec(text ?? ""), a = ABILITY_WORDS.exec(text ?? "");
  return i && a ? [`item:${i[0].toLowerCase()}`, `ability:${a[0].toLowerCase()}`] : [];
}

export function decideDesignerRoute(i: DesignerRouteInput): DesignerRouteDecision {
  const none: DesignerRouteDecision = { route: false, matched: [], notices: [], limits: [] };
  if (!i.on) return none;
  const itemWords = matchDesignerWords(i.text);
  const gp = matchGameplayWords(i.text);
  const matched = [...itemWords, ...gp.matched];
  if (!matched.length && !explicitDesign(i.explicit) && !i.existing && !i.existingGameplay) return none;
  const gameplay = gp.menus || gp.quests || i.existingGameplay ? { gameplay: { menus: gp.menus || !!i.existingGameplay, quests: gp.quests || !!i.existingGameplay } } : {};
  const fe = designFeatures(i.mcVersion);
  if (!fe.ok) return { route: false, matched, notices: [`The item designer isn't available for Minecraft ${i.mcVersion} yet (${fe.error}), so Cyrus writes this mod as plain code.`], limits: [] };
  const limits = [
    "Custom items with abilities are built from a typed design: cooldowns, ranges, strengths, sounds and messages stay editable in config.yml without rebuilding.",
    ...(fe.features.itemModel ? [] : [`Custom item models need Minecraft 1.21.4 or newer; on ${i.mcVersion} the items keep their base look.`]),
    ...(gp.menus || i.existingGameplay ? ["Menus are built from a typed design: buttons, paginated shop lists, item / XP / Vault money prices, permissions and dialogues; prices and texts stay editable in config.yml. No player-to-player trading or auctions."] : []),
    ...(gp.quests || i.existingGameplay ? ["Quests are built from a typed design: steps with kill / collect / craft / visit / break / talk / survive objectives, branches, chains, daily or weekly repeats and rewards; progress is stored on each player."] : []),
  ];
  return { route: true, matched, notices: [], limits, ...gameplay };
}

/** Does a stored build result carry designs (ModBuild.result.assets.designs, written by the asset sync)? */
export function hasDesigns(result: unknown): boolean {
  const a = (result as { assets?: { designs?: unknown[] } } | null)?.assets;
  return Array.isArray(a?.designs) && a!.designs!.length > 0;
}

/** Does a stored build result carry menu or quest designs (rows with kind menu / quest)? */
export function hasGameplayDesigns(result: unknown): boolean {
  const a = (result as { assets?: { designs?: { kind?: unknown }[] } } | null)?.assets;
  return Array.isArray(a?.designs) && a!.designs!.some((d) => d && (d.kind === "menu" || d.kind === "quest"));
}

// Cyrus studios (R1b): the REAL dependencies of the studio API. SERVER ONLY. This is the one file that reaches Nxeon:
// through the existing small seams only (the Cyrus access rule modBuilderUser + the preview list, the settings
// table for the flag, tokens tierOf for the plan, the ModBuild chain the studio already lives on, the rate limiter).
// Everything it writes goes to Cyrus tables through lib/cyrus/engine-core/store.ts.
import type { User } from "@prisma/client";
import { modBuilderUser } from "../../modbuilder/access";
import { getHost } from "../host";
import { MANAGED_REAL_FLAG } from "../managed/installer";
import { selectPackStore } from "../packhost/config";
import { publishPack } from "../packhost/publish";
import { SoundLibraryProvider, TextureLibraryProvider } from "../library/providers";
import { userAssetProviders } from "../library/user-assets";
import { prismaUserAssetStore } from "../library/user-store";
import { tierOf } from "../tokens/access";
import { studiosOpen } from "./access";
import { changeBuildCandidates } from "./candidates";
import { chainOf, prismaStudioStore } from "./store-prisma";
export { chainOf, prismaStudioStore };
import { fakeCandidates, type CandidateBackend, type StudioServiceDeps } from "./service";
import type { StudioApiDeps, StudioViewer, UploadStore } from "./http";
import { localUploadStore } from "./uploads";
import { selectRenderHost, soundLibraryCleared, type RenderHostSelection } from "../sound/host";
import { fakeRenderHost, fakeSoundCandidates, type SoundCandidateBackend } from "./sound-service";
import { changeBuildSoundCandidates } from "./sound-candidates";

export const CYRUS_STUDIOS_FLAG = "cyrus_studios_enabled";

/** The studios setting. Fails CLOSED: a settings/DB error never opens them. */
export async function studiosFlagOn(): Promise<boolean> {
  try { return await getHost().settings.getBool(CYRUS_STUDIOS_FLAG, false); } catch { return false; }
}

/** Who may see the studios now: a Cyrus user (preview or public launch) AND (preview OR the setting is on). */
export async function studioViewer(): Promise<(StudioViewer & { user: User }) | null> {
  const user = await modBuilderUser().catch(() => null);
  if (!user) return null;
  const [previewUser, flagOn] = await Promise.all([getHost().access.isPreviewUser(user, "modbuilder").catch(() => false), studiosFlagOn()]);
  return studiosOpen({ cyrusUser: true, previewUser, flagOn }) ? { userId: user.id, user, preview: previewUser } : null;
}

/**
 * The plan lookup (host seam: tokens tierOf). Non-production only: CYRUS_STUDIO_TEST_PLAN_UNKNOWN=<userId,...> makes
 * the lookup fail for those accounts, so the fail-closed "plan unknown" state can be exercised on devhost.
 */
export function studioPlanOf(env: Record<string, string | undefined> = process.env) {
  const faulty = env.NODE_ENV !== "production" ? new Set((env.CYRUS_STUDIO_TEST_PLAN_UNKNOWN ?? "").split(",").filter(Boolean)) : new Set<string>();
  return async (userId: string): Promise<unknown> => { if (faulty.has(userId)) throw new Error("plan lookup failed (test fault)"); return tierOf(userId); };
}

export function serviceDeps(env: Record<string, string | undefined> = process.env): StudioServiceDeps {
  return {
    store: prismaStudioStore,
    planOf: studioPlanOf(env),
    chain: chainOf,
    deliveryOn: () => env[MANAGED_REAL_FLAG] === "1",
    publish: async (zip) => {
      const sel = selectPackStore(env);
      if (!sel.ok) return { ok: false, reason: sel.reason };
      const r = await publishPack(sel.store, zip, { maxBytes: sel.maxBytes });
      return r.ok ? { ok: true, url: r.url, sha1: r.sha1 } : { ok: false, reason: r.error };
    },
  };
}

/** CYRUS_STUDIO_CANDIDATES=fake (devhost / tests only) swaps the change-build backend for the deterministic fake. */
// one fake per process (globalThis: each Next route bundle has its own module instance)
const G = globalThis as { __cyrusFakeCandidates?: CandidateBackend };
export function candidateBackend(env: Record<string, string | undefined> = process.env): CandidateBackend {
  if (env.CYRUS_STUDIO_CANDIDATES === "fake" && env.NODE_ENV !== "production") return (G.__cyrusFakeCandidates ??= fakeCandidates({ readyAfter: 1 }));
  return changeBuildCandidates(prismaStudioStore);
}

/**
 * The Sound Studio's render host: the real one (CYRUS_SOUND_RENDER=ssh, node-2) or, on devhost / in tests only,
 * CYRUS_STUDIO_SOUND_RENDER=fake = the in-process fake (real DSP, stand-in library audio, WAV instead of Ogg).
 */
const GF = globalThis as { __cyrusFakeRender?: ReturnType<typeof fakeRenderHost>; __cyrusFakeSoundCands?: SoundCandidateBackend };
export function studioRenderHost(env: Record<string, string | undefined> = process.env): RenderHostSelection {
  if (env.CYRUS_STUDIO_SOUND_RENDER === "fake" && env.NODE_ENV !== "production") return { ok: true, host: (GF.__cyrusFakeRender ??= fakeRenderHost()) };
  return selectRenderHost(env);
// The Cyrus HOST SEAM: everything Cyrus needs from the platform it runs inside, as small interfaces.
// Inside Nxeon the implementation is lib/cyrus/host/nxeon.ts (the ONLY file under lib/cyrus allowed to import Nxeon
// internals, enforced by test/cyrus-host-seam.test.ts). Standalone Cyrus supplies its own implementation of this
// interface (or an adapter that calls the Nxeon API). Add a method here when Cyrus needs a new platform service,
// never import the platform directly. Pure types: client-safe, no imports.

export type HostRateLimit = { ok: boolean; retryAfterSec: number; remaining: number };

/** The signed-in person as Cyrus sees them. The platform's own user record is a superset of this. */
export type HostUser = { id: string; email: string | null; role: string; name?: string | null };
/** A permission area of the host's admin ("billing", "support"...). Opaque to Cyrus; each host defines its own. */
export type HostArea = string;
/** Private-preview feature keys Cyrus may ask about. */
export type HostPreviewFeature = "modbuilder";

export interface CyrusHost {
  /** Who is signed in. Sessions, cookies and impersonation stay entirely the host's business. */
  auth: {
    /** The acting user (impersonation applied), or null when signed out. */
    currentUser(): Promise<HostUser | null>;
    /** The really signed-in user, ignoring impersonation, or null. */
    realUser(): Promise<HostUser | null>;
    /** Page guard for an admin area: returns the real staff user, or ends the request (redirect/404) by the host's rule. */
    requireArea(area: HostArea): Promise<HostUser>;
  };
  /** Permission checks. Fail CLOSED: unknown role/area/feature is false. */
  access: {
    canAccess(role: string, area: HostArea): boolean;
    isPreviewUser(user: { email?: string | null } | null | undefined, feature: HostPreviewFeature): Promise<boolean>;
  };
  /** Key/value settings and feature flags (Nxeon: the Setting table). Values are strings; missing keys use the fallback. */
  settings: {
    get(key: string, fallback?: string): Promise<string>;
    getBool(key: string, fallback?: boolean): Promise<boolean>;
    getInt(key: string, fallback?: number): Promise<number>;
    getAll(): Promise<Record<string, string>>;
    set(key: string, value: string): Promise<void>;
  };
  /** Fixed-window rate limiter keyed by an opaque string. Synchronous, in-process. */
  rateLimit: {
    check(key: string, opts: { max: number; windowMs: number }): HostRateLimit;
  };
  /** Append-only audit trail; attribution to the acting admin is the host's job. */
  audit: {
    record(userId: string | null, action: string, detail?: string): Promise<void>;
  };
}

/** Settings stored as "true"/"on"/"1" are true. Same rule as the platform's own coercion. */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}
// The Nxeon implementation of the Cyrus host seam. SERVER ONLY. This is the single file under lib/cyrus/host that
// reaches Nxeon: every method delegates to the existing platform function unchanged, so behaviour inside Nxeon is
// identical to calling them directly. Moving Cyrus out means replacing this file, nothing else.
import { getSetting, getSettingBool, getSettingInt, getAllSettings, setSetting } from "../../settings";
import { checkRateLimit } from "../../rate-limit";
import { recordAudit } from "../../audit";
import { currentUser, realUser } from "../../auth";
import { canAccess, requireArea, type Area } from "../../rbac";
import { isPreviewUser } from "../../preview-access";
import type { CyrusHost } from "./types";

export const nxeonHost: CyrusHost = {
  auth: {
    currentUser: () => currentUser(),
    realUser: () => realUser(),
    requireArea: (area) => requireArea(area as Area),
  },
  access: {
    // Role is the platform's role enum; an unknown role/area is simply not in the platform's table, so this stays closed.
    canAccess: (role, area) => canAccess(role as Parameters<typeof canAccess>[0], area as Area),
    isPreviewUser: (user, feature) => isPreviewUser(user, feature),
  },
  settings: {
    get: (key, fallback) => getSetting(key, fallback),
    getBool: (key, fallback) => getSettingBool(key, fallback),
    getInt: (key, fallback) => getSettingInt(key, fallback),
    getAll: () => getAllSettings(),
    set: (key, value) => setSetting(key, value),
  },
  rateLimit: { check: (key, opts) => checkRateLimit(key, opts) },
  audit: { record: (userId, action, detail) => recordAudit(userId, action, detail) },
};

