    if (spec.format !== "yaml") return { ok: false, errors: [`the Paper exporter writes YAML, not ${spec.format}`] };
    if (!PLUGIN_RE.test(ctx.pluginName)) return { ok: false, errors: ["bad plugin name"] };
    const path = `plugins/${ctx.pluginName}/${spec.file}`;
    if (ctx.previousText) {
      const w = writeValues(spec, ctx.previousText, values);
      return w.ok ? { ok: true, path, text: w.text, written: w.written } : { ok: false, errors: w.errors.map((e) => e.message) };
