    case "bool": return { decl: "boolean", init: String(p.default), load: `bool(c, ${k}, ${p.default}, notes)` };
    case "range": { const [a, b] = p.default as number[]; return { decl: "double[]", init: `{ ${jnum(a)}, ${jnum(b)} }`, load: `range(c, ${k}, ${jnum(a)}, ${jnum(b)}, ${dlo}, ${dhi}, notes)` }; }
    case "enum": return { decl: "String", init: jstr(String(p.default)), load: `oneOf(c, ${k}, ${jstr(String(p.default))}, new String[] { ${(p.options ?? []).map((o) => jstr(String(o.value))).join(", ")} }, notes)` };
    case "text": case "asset-ref": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, ${p.maxLength ?? 256}, null, notes)` };
    case "color": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, 7, "^#[0-9a-fA-F]{6}$", notes)` };
    case "sound-ref": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, 200, "^([a-z0-9_.-]+:[a-z0-9_./-]+)?$", notes)` };
    case "list": return { decl: "java.util.List<?>", init: "java.util.List.of()", load: `list(c, ${k}, ${p.maxItems ?? 256}, notes)` };
