  lines.push(`public final class ${cls} {`, `    private ${cls}() {}`, ``);
  for (const p of spec.params) { const t = jtype(p)!; lines.push(`    /** ${p.label.replace(/\*\//g, "")} (${p.key}) */`, `    public static ${t.decl} ${fields[p.key]} = ${t.decl === "double[]" ? `new double[] ${t.init}` : t.init};`); }
  lines.push(``, `    /** Read every setting. Returns notes about clamped or refused values (empty when all were fine). */`, `    public static List<String> load(ConfigurationSection c) {`, `        List<String> notes = new ArrayList<>();`);
  for (const p of spec.params) lines.push(`        ${fields[p.key]} = ${jtype(p)!.load};`);
  lines.push(`        return notes;`, `    }`, ``);
  lines.push(
    `    private static double num(ConfigurationSection c, String k, double d, double lo, double hi, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        double v;`,
    `        if (raw instanceof Number n) v = n.doubleValue();`,
    `        else { try { v = Double.parseDouble(String.valueOf(raw).trim()); } catch (NumberFormatException e) { notes.add(k + " is not a number; using " + d); return d; } }`,
    `        if (Double.isNaN(v) || Double.isInfinite(v)) { notes.add(k + " is not a finite number; using " + d); return d; }`,
    `        double r = Math.max(lo, Math.min(hi, v));`,
    `        if (r != v) notes.add("clamped " + k + " " + v + " -> " + r);`,
    `        return r;`,
    `    }`,
    `    private static boolean bool(ConfigurationSection c, String k, boolean d, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        if (raw instanceof Boolean b) return b;`,
    `        String s = String.valueOf(raw).trim().toLowerCase(java.util.Locale.ROOT);`,
    `        if (s.equals("true") || s.equals("yes") || s.equals("on")) return true;`,
    `        if (s.equals("false") || s.equals("no") || s.equals("off")) return false;`,
    `        notes.add(k + " is not true or false; using " + d);`,
    `        return d;`,
    `    }`,
    `    private static String text(ConfigurationSection c, String k, String d, int max, String pattern, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        String s = String.valueOf(raw);`,
    `        if (s.length() > max) { notes.add(k + " is longer than " + max + " characters; cut"); s = s.substring(0, max); }`,
    `        if (pattern != null && !s.matches(pattern)) { notes.add(k + " has a bad value; using " + d); return d; }`,
    `        return s;`,
    `    }`,
    `    private static String oneOf(ConfigurationSection c, String k, String d, String[] options, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        String s = String.valueOf(raw);`,
    `        for (String o : options) if (o.equalsIgnoreCase(s)) return o;`,
    `        notes.add(k + " must be one of " + String.join(", ", options) + "; using " + d);`,
    `        return d;`,
    `    }`,
    `    private static double[] range(ConfigurationSection c, String k, double a, double b, double lo, double hi, List<String> notes) {`,
    `        List<?> l = c.getList(k);`,
    `        if (l == null || l.size() != 2 || !(l.get(0) instanceof Number) || !(l.get(1) instanceof Number)) { if (c.get(k) != null) notes.add(k + " needs [low, high]; using defaults"); return new double[] { a, b }; }`,
    `        double x = Math.max(lo, Math.min(hi, ((Number) l.get(0)).doubleValue())), y = Math.max(lo, Math.min(hi, ((Number) l.get(1)).doubleValue()));`,
    `        if (x > y) { notes.add(k + " low end is above the high end; using defaults"); return new double[] { a, b }; }`,
    `        return new double[] { x, y };`,
    `    }`,
    `    private static List<?> list(ConfigurationSection c, String k, int max, List<String> notes) {`,
    `        List<?> l = c.getList(k);`,
    `        if (l == null) return List.of();`,
    `        if (l.size() > max) { notes.add(k + " has more than " + max + " entries; cut"); return List.copyOf(l.subList(0, max)); }`,
    `        return List.copyOf(l);`,
    `    }`,
    `    private static List<java.util.Map<?, ?>> table(ConfigurationSection c, String k, int max, List<String> notes) {`,
    `        List<java.util.Map<?, ?>> l = c.getMapList(k);`,
    `        if (l.size() > max) { notes.add(k + " has more than " + max + " rows; cut"); return List.copyOf(l.subList(0, max)); }`,
    `        return List.copyOf(l);`,
    `    }`,
    `}`, ``,
  );
  return { path: `src/main/java/${o.pkg.replace(/\./g, "/")}/${cls}.java`, source: lines.join("\n"), fields };
}

