// Cyrus Config Studio: the BUILD ROUTE (server side, pure). With CYRUS_CONFIG_STUDIO=1 a plain AI plugin build (not
// the designers: they derive their settings from the design) is told to declare its tunables in
// assets/config/schema.json, starting from the category templates that fit the request (zero-token keyword routing).
// OFF (the default, fail closed): nothing is decided, nothing is recorded, the build request stays byte-identical.
// Editing values is NOT asset creation: not plan-gated (owner decision pending, proposed ungated).
import { suggestTemplates, templateIdsForCategory, TEMPLATE_BY_ID, type TemplateId } from "./templates";

export const CONFIG_STUDIO_FLAG = "CYRUS_CONFIG_STUDIO";
export const configStudioOn = (env: Record<string, string | undefined> = process.env) => env[CONFIG_STUDIO_FLAG] === "1";

export type ConfigRouteInput = { text: string; category?: string | null; on: boolean; designRoute: boolean; existing?: boolean };
export type ConfigRouteDecision = { route: boolean; templates: TemplateId[] };

export function decideConfigRoute(i: ConfigRouteInput): ConfigRouteDecision {
  if (!i.on || i.designRoute) return { route: false, templates: [] };
  const fromText = suggestTemplates(i.text, 3);
  const fromCat = i.category ? templateIdsForCategory(i.category).slice(0, 1) : [];
  const templates = [...new Set([...fromText, ...fromCat])].slice(0, 3) as TemplateId[];
  return { route: true, templates: templates.length ? templates : ["utility"] };
}

/** The template keys the model is shown for a build (compact: key, type, default, unit, limits; one line each). */
export function templateBrief(ids: readonly string[]): string {
  const out: string[] = [];
  for (const id of ids) {
    const t = TEMPLATE_BY_ID.get(id as TemplateId);
    if (!t) continue;
    out.push(`${t.label} (template "${t.id}"):`);
    for (const p of t.params) {
      const lim = p.min !== undefined || p.max !== undefined ? ` ${p.min ?? ""}..${p.max ?? ""}` : "";
      out.push(`  ${p.key}: ${p.type}${p.type === "duration" ? `(${p.durationUnit})` : ""} = ${JSON.stringify(p.default)}${p.unit ? ` ${p.unit}` : ""}${lim}${p.visual ? ` [drives ${p.visual.channel}${p.visual.clip ? ` ${p.visual.clip}` : ""}]` : ""}`);
    }
  }
  return out.join("\n");
}

