// Cyrus Config Studio: the deterministic "JUST TWEAK A SETTING" recogniser (no AI). Mirrors the designers'
// planDesignEdit grammar, against a ConfigSpec instead of designs:
//   [set|change|make|...] [the] <subject> (to|=) <value> [unit]   (clauses split by "and", ",", ";")
// Every clause must resolve to exactly ONE setting (all subject words found in its label / key / group / tags /
// synonyms) and a value that passes the strict check; anything else goes to the model. Durations take seconds by
// default, "%" on a 0-1 setting divides by 100, hearts double on hp settings. Pure. NOT wired into the build path
// (owner decision: skipping the model changes billing); the studio uses it for its command box.
import { paramByKey, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues } from "./spec";
import { checkValue, fmt } from "./values";
import { humanize } from "./infer";

export type ConfigEditPlan =
  | { kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] }
  | { kind: "model"; reason: string; candidates?: string[] };

const SYN: Record<string, string[]> = {
  hp: ["health"], health: ["hp"], dmg: ["damage"], damage: ["dmg", "attack"], cd: ["cooldown"], cooldown: ["cd", "recharge"],
  speed: ["movement", "move", "velocity"], movement: ["speed", "move"], walk: ["move", "movement", "speed"], mag: ["magazine"], magazine: ["mag", "clip"], clip: ["magazine"],
  price: ["cost", "buy"], cost: ["price"], rpm: ["fire", "rate"], firerate: ["fire", "rate"], size: ["scale"], scale: ["size"], range: ["reach", "radius", "distance"],
  reach: ["range"], radius: ["range", "area"], ammo: ["reserve", "magazine"], xp: ["experience"], experience: ["xp"], chance: ["probability", "odds"],
};
const STOP = new Set(["the", "a", "an", "of", "on", "for", "its", "my", "their", "his", "her", "please", "value", "setting", "stat"]);
const norm = (s: string) => s.toLowerCase().replace(/[_.\-]/g, " ").replace(/[^a-z0-9% ]+/g, " ").replace(/\s+/g, " ").trim();

function haystack(p: ConfigParam, groupLabel: string): Set<string> {
  const words = new Set<string>();
  const add = (s: string) => { for (const w of norm(s).split(" ")) if (w) { words.add(w); for (const x of SYN[w] ?? []) words.add(x); if (w.endsWith("s")) words.add(w.slice(0, -1)); } };
  add(p.label); add(p.key.split(".").map(humanize).join(" ")); add(groupLabel); p.tags.forEach(add);
  if (p.unit) add(p.unit);
  return words;
}

function parseValue(p: ConfigParam, raw: string): { ok: true; value: unknown } | { ok: false; reason: string } {
  const t = raw.trim().replace(/[.!?]+$/, "");
  switch (p.type) {
    case "bool": {
      if (/^(on|true|yes|enabled?)$/i.test(t)) return { ok: true, value: true };
      if (/^(off|false|no|disabled?)$/i.test(t)) return { ok: true, value: false };
      return { ok: false, reason: `"${t}" is not on or off` };
    }
    case "enum": { const o = p.options?.find((x) => String(x.value).toLowerCase() === t.toLowerCase() || String(x.label ?? "").toLowerCase() === t.toLowerCase()); return o ? { ok: true, value: o.value } : { ok: false, reason: `"${t}" is not one of ${(p.options ?? []).map((x) => x.value).join(", ")}` }; }
    case "text": return { ok: true, value: t.replace(/^["']|["']$/g, "") };
    case "color": return { ok: true, value: t };
    case "sound-ref": return { ok: true, value: t.replace(/\s+/g, "").toLowerCase() };
    case "number": case "int": case "duration": {
      const m = /^(-?\d+(?:\.\d+)?)\s*(s|sec|secs|seconds?|ticks?|ms|milliseconds?|min|minutes?|%|percent|hearts?|hp|blocks?|x|rpm|rounds?|coins?)?$/i.exec(t);
      if (!m) return { ok: false, reason: `"${t}" is not a number` };
      let x = Number(m[1]);
      const u = (m[2] ?? "").toLowerCase();
      if (p.type === "duration") {
        const secs = /^tick/.test(u) ? x / 20 : /^(ms|milli)/.test(u) ? x / 1000 : /^min/.test(u) ? x * 60 : x;
        x = p.durationUnit === "ticks" ? Math.round(secs * 20) : p.durationUnit === "ms" ? Math.round(secs * 1000) : secs;
      } else if (/^(%|percent)$/.test(u) && p.unit !== "%" && p.max !== undefined && p.max <= 1) x = x / 100;
      else if (/^heart/.test(u) && p.unit === "hp") x = x * 2;
      return { ok: true, value: x };
    }
    default: return { ok: false, reason: `${p.label} is a ${p.type}: edit it in the studio` };
  }
}

export function planConfigEdit(text: string, spec: ConfigSpec, values?: ConfigValues): ConfigEditPlan {
  if (!text || text.length > 400) return { kind: "model", reason: "empty or long request" };
  if (/\b(add|new|remove|delete|instead|also|another|when|if|whenever|make it (shoot|fire|summon|spawn)|texture|model|recipe|craft|rename|command)\b/i.test(text)) return { kind: "model", reason: "structural change" };
  const clauses = text.split(/\s*(?:\band\b|,|;)\s*/i).map((c) => c.trim()).filter(Boolean);
  if (!clauses.length || clauses.length > 8) return { kind: "model", reason: "no clauses" };
  const groups = new Map(spec.groups.map((g) => [g.id, g.label]));
  const editable = spec.params.filter((p) => !p.readOnly);
  const hays = new Map(editable.map((p) => [p.key, haystack(p, groups.get(p.group) ?? "")]));
  const byKey = paramByKey(spec);
  const edits: { key: string; value: ConfigValue }[] = [];
  const summary: string[] = [];
  let lastScope: string[] = [];
  for (const raw of clauses) {
    const m = /^(?:(?:please )?(?:set|change|make|increase|decrease|lower|raise|reduce|put|adjust|bump)\s+)?(?:the\s+)?(.+?)\s+(?:to|=|at)\s+(.+)$/i.exec(raw.trim());
    if (!m) return { kind: "model", reason: `could not read "${raw}"` };
    const words = norm(m[1].replace(/'s\b/g, "")).split(" ").filter((w) => w && !STOP.has(w));
    if (!words.length) return { kind: "model", reason: `"${raw}" names no setting` };
