"use strict";
// Config and Stats Studio in the build service. When the portal routes a plain plugin build with `assets.config`
// (CYRUS_CONFIG_STUDIO=1; never for designer builds, which derive their settings from the design), the model declares
// every tunable in assets/config/schema.json (a ConfigSpec). This module checks it like code with the validator
// GENERATED from lib/cyrus/config (./config-spec.js): the schema validates; every declared key is READ by the Java
// sources (an unread key is a repair, then dropped); keys read but not declared and numbers hard-coded into stat
// calls are warnings. Then config.yml is written FROM the schema (comments with label, unit, limits; an existing
// config.yml keeps its comments and extra keys). No schema after the repair = a schema is inferred from config.yml.
// The portal re-validates the result (the service is not trusted). Plain Node.
const fs = require("fs");
const path = require("path");
const CF = require("./config-spec");

const CONFIG_FILE = "assets/config/schema.json";
const CONFIG_FILE_RE = /^assets\/config\/schema\.json$/;
const CONFIG_YML = "src/main/resources/config.yml";
const MAX_SCHEMA_BYTES = 256 * 1024;

function snapshotConfigSchema(ws) {
  const out = new Map();
  try { out.set(CONFIG_FILE, fs.readFileSync(path.join(ws, CONFIG_FILE))); } catch { /* none */ }
  return out;
}
function javaFiles(ws) {
  const out = [];
  const walk = (d) => {
    let es = [];
    try { es = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
    for (const e of es) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.name.endsWith(".java") && out.length < 400) out.push({ rel: path.relative(ws, p).split(path.sep).join("/"), content: fs.readFileSync(p, "utf8") });
    }
  };
  walk(path.join(ws, "src/main/java"));
  return out;
}
const readText = (abs) => { try { return fs.readFileSync(abs, "utf8"); } catch { return null; } };

/** plugin.yml command names (lowercase), read with a tiny line scan (the service's YAML parse happens in validate()). */
function commandNames(ws) {
  const t = readText(path.join(ws, "src/main/resources/plugin.yml")) || "";
  const m = /^commands:\s*\n((?:[ \t]+.*\n?|\s*\n)*)/m.exec(t);
  if (!m) return [];
  const ind = (/^([ \t]+)\S/m.exec(m[1]) || [, "  "])[1].length;
  return m[1].split("\n").filter((l) => l.length - l.trimStart().length === ind && /^\s*[A-Za-z0-9_-]+:/.test(l)).map((l) => l.trim().split(":")[0].toLowerCase());
}

/** Bring a declared spec in line with the plugin: a reload command that is not in plugin.yml turns "reload" into "restart". */
function alignReload(raw, ws, warnings) {
  if (!raw || typeof raw !== "object" || !raw.reload || typeof raw.reload.command !== "string") return raw;
  const name = raw.reload.command.replace(/^\//, "").split(" ")[0].toLowerCase();
  if (commandNames(ws).includes(name)) return raw;
  warnings.push(`the settings name /${name} as their reload command, but plugin.yml has no ${name} command: changes apply on restart`);
  const out = { ...raw, params: Array.isArray(raw.params) ? raw.params.map((p) => (p && p.applies === "reload" ? { ...p, applies: "restart" } : p)) : raw.params };
  delete out.reload;
  return out;
}

function inferFallback(ws, rec, why) {
  const yml = readText(path.join(ws, CONFIG_YML));
  if (!yml) { rec.configResult = { source: "none", reason: why, spec: null, warnings: [why] }; return null; }
  const r = CF.inferSchema(yml, { pluginYml: readText(path.join(ws, "src/main/resources/plugin.yml")) || undefined });
  rec.configResult = r.ok
    ? { source: "inferred", spec: r.spec, warnings: [why, ...r.notes.slice(0, 8)], skipped: r.skipped.slice(0, 40) }
    : { source: "none", reason: why, spec: null, warnings: [why, ...r.errors.slice(0, 4)] };
  return null;
}

/**
 * One settings round (after validate(), with the asset round). Returns a repair problem for the model or null; on null
 * config.yml is written from the schema and rec.configResult says what ships.
 */
function configRound(ws, rec, st, canRepair) {
  const abs = path.join(ws, CONFIG_FILE);
  const ask = (lines, say) => {
    if (!canRepair || st.configRepairs >= 1) return false;
    st.configRepairs = (st.configRepairs || 0) + 1;
    return { kind: "asset", count: lines.length, text: lines.map((l) => `- ${l}`).join("\n"), say };
  };
  let size = -1;
  try { size = fs.statSync(abs).size; } catch { /* missing */ }
  if (size < 0) return ask([`No settings schema was written. Declare every tunable value at ${CONFIG_FILE} (see SETTINGS) and read each key in the code with getConfig().`], "No settings schema found") || inferFallback(ws, rec, "Cyrus inferred the settings from config.yml (the build declared none)");
  if (size > MAX_SCHEMA_BYTES) { fs.rmSync(abs, { force: true }); return inferFallback(ws, rec, `the settings schema was larger than ${MAX_SCHEMA_BYTES / 1024} KB and was left out`); }
  let raw;
  try { raw = JSON.parse(fs.readFileSync(abs, "utf8")); } catch (e) {
    return ask([`${CONFIG_FILE} is not valid JSON: ${String(e.message).slice(0, 200)}`], "The settings schema is not valid JSON") || (fs.rmSync(abs, { force: true }), inferFallback(ws, rec, "the settings schema was not valid JSON, so Cyrus inferred the settings from config.yml"));
  }
  const warnings = [];
  raw = alignReload(raw, ws, warnings);
  let v = CF.validateConfigSpec(raw);
  if (!v.ok) {
    const lines = v.errors.slice(0, 12).map((e) => `${CONFIG_FILE} ${e.path}: ${e.message}`);
    return ask(lines, `Settings check found ${v.errors.length} problem${v.errors.length > 1 ? "s" : ""}`) || (fs.rmSync(abs, { force: true }), inferFallback(ws, rec, `the settings schema did not pass Cyrus's checks (${v.errors[0].message}), so Cyrus inferred the settings from config.yml`));
  }
  const java = javaFiles(ws);
  let rep = CF.verifyTunables(v.spec, java, { accessorClass: "CyrusSettings" });
  if (rep.unread.length) {
    const lines = rep.unread.slice(0, 16).map((k) => `Setting ${k} is declared in ${CONFIG_FILE} but the code never reads it: read it with getConfig().get...("${k}") where the value is used, or remove it from the schema.`);
    const p = ask(lines, `${rep.unread.length} declared setting${rep.unread.length > 1 ? "s are" : " is"} never read`);
    if (p) return p;
    // after the repair: unread settings are dropped (a setting that does nothing is worse than none)
    const keep = v.spec.params.filter((x) => !rep.unread.includes(x.key));
    warnings.push(`${rep.unread.length} declared setting${rep.unread.length > 1 ? "s were" : " was"} left out of the editor because the code never reads ${rep.unread.length > 1 ? "them" : "it"}: ${rep.unread.slice(0, 6).join(", ")}`);
    if (!keep.length) { fs.rmSync(abs, { force: true }); return inferFallback(ws, rec, "none of the declared settings is read by the code, so Cyrus inferred the settings from config.yml"); }
    const groups = new Set(keep.map((x) => x.group));
    const keys = new Set(keep.map((x) => x.key));
    v = CF.validateConfigSpec({ ...v.spec, groups: v.spec.groups.filter((g) => groups.has(g.id)), params: keep, presets: v.spec.presets.map((pr) => ({ ...pr, values: Object.fromEntries(Object.entries(pr.values).filter(([k]) => keys.has(k))) })).filter((pr) => Object.keys(pr.values).length) });
    if (!v.ok) return inferFallback(ws, rec, "the settings schema could not be repaired, so Cyrus inferred the settings from config.yml");
    rep = CF.verifyTunables(v.spec, java, { accessorClass: "CyrusSettings" });
  }
  if (rep.undeclared.length) warnings.push(`the code reads ${rep.undeclared.length} config key${rep.undeclared.length > 1 ? "s" : ""} the schema does not declare: ${rep.undeclared.slice(0, 6).join(", ")}`);
  if (rep.magic.length) warnings.push(`${rep.magic.length} number${rep.magic.length > 1 ? "s are" : " is"} hard-coded into stat calls (first: ${rep.magic[0].where}); they cannot be changed in the Config Studio`);
  // config.yml FROM the schema (an existing one keeps its comments and extra keys; declared defaults win)
  const ymlAbs = path.join(ws, CONFIG_YML);
  const cur = readText(ymlAbs);
  let text;
  if (cur) {
    const w = CF.writeValues(v.spec, cur, CF.defaultsOf(v.spec));
    if (!w.ok) { warnings.push(`config.yml could not be merged (${w.errors[0].message}); it was rewritten from the schema`); text = CF.renderConfigYml(v.spec, CF.defaultsOf(v.spec), [`${rec.pluginName || "Plugin"} configuration (generated by Cyrus from the settings schema).`]); }
    else text = w.text;
  } else text = CF.renderConfigYml(v.spec, CF.defaultsOf(v.spec), [`Configuration (generated by Cyrus from the settings schema).`, `Change values here and run the plugin's reload command, or use the Cyrus Config Studio.`]);
  fs.mkdirSync(path.dirname(ymlAbs), { recursive: true });
  fs.writeFileSync(ymlAbs, text);
  fs.writeFileSync(abs, JSON.stringify(v.spec, null, 1) + "\n"); // the normalised schema ships (defaults filled in)
  rec.configResult = {
    source: "declared", spec: v.spec, warnings: [...warnings, ...v.warnings.map((x) => x.message)].slice(0, 12),
    verify: { read: rep.read.length, undeclared: rep.undeclared.slice(0, 30), magic: rep.magic.slice(0, 20) },
  };
  return null;
}

module.exports = { CONFIG_FILE, CONFIG_FILE_RE, CONFIG_YML, snapshotConfigSchema, configRound, commandNames, alignReload };

