"use strict";
// Prompts for the Nxeon Mod Builder. Kept in one file so they can be reviewed
// and versioned. The orchestrator (server.js), not the model, enforces every
// rule below; the prompt only makes the model's first attempt more likely to pass.

const fs = require("fs");
const path = require("path");
const { RULES, rulesFor } = require("./precheck");
const { MAX_TEXTURES } = require("./textures");
const SS = require("./sound-spec");
const CS = require("./creature-spec");

const PROMPT_VERSION = "mb-2026-10-09.1";

// Version cheat sheets (sheets/<ver>.md, every claim checked with javap against
// the Paper API jar of that version) and the reviewed failure rules. Only the
// sheet for the requested version is injected. MB_SHEETS=off / MB_RULES=off
// disable them (used by the eval to measure their effect).
const SHEETS_ON = process.env.MB_SHEETS !== "off";
const RULES_ON = process.env.MB_RULES !== "off";
const SHEETS = {};
function sheetFor(v) {
  if (!SHEETS_ON) return "";
  if (!(v in SHEETS)) {
    try { SHEETS[v] = fs.readFileSync(path.join(__dirname, "sheets", `${v}.md`), "utf8").trim(); } catch { SHEETS[v] = ""; }
  }
  return SHEETS[v];
}
function knowledgeVersion() {
  return `${SHEETS_ON ? "sheets" : "nosheets"}+${RULES_ON ? RULES.version : "norules"}`;
// (CYRUS_DESIGNER on + an item-with-abilities request). Fixed text (the compiler handles versions), so it caches per
// version; the namespace is in the user turn. Without it the system prompt is byte-identical to before.
const DESIGN_MAX_FILES = 6; // = DESIGN_LIMITS.maxItems in lib/cyrus/designer/spec.ts (test/cyrus-designer.test.ts checks)
let DESIGN_EXAMPLE = "";
try { DESIGN_EXAMPLE = JSON.stringify(JSON.parse(fs.readFileSync(path.join(__dirname, "designer-example.json"), "utf8"))); } catch { DESIGN_EXAMPLE = ""; }
const DESIGN_SECTION = `

ITEM DESIGNER (this build uses it). This request is a custom item with abilities, so you DESIGN it as data instead of writing the plugin: write one ItemDesign file per item at assets/designs/<id>.json (nowhere else under assets/). Nxeon validates each design and compiles it with its verified component library into the whole plugin (main class, listeners, cooldowns, charges, marks, config.yml with every number as an editable setting, plugin.yml with /<plugin name lowercase> give|list|params|reload). So rules 3, 4 and 6 change: do NOT write plugin.yml, config.yml or any Java except for what a design cannot express (then only classes in package dev.nxeon.plugins.<lowercase plugin name>.custom, entry class CustomHooks with public static void enable(org.bukkit.plugin.java.JavaPlugin plugin) and public static void disable(); every other Java file is replaced by the generated code). Still write modbuilder.json (its "name" is the plugin name).
