s=s.replace('${opts.itemmodel ? ITEMMODEL_SECTION : ""}`;\n}','${opts.itemmodel ? ITEMMODEL_SECTION : ""}${opts.config ? CONFIG_SECTION : ""}`;\n}',1)
old='''function assetsBlock(assets) {
  if (!assets || (!assets.texture && !assets.sound && !assets.datapack && !assets.design && !assets.creature)) return "";'''
new='''function configBlock(assets) {
  if (!assets || !assets.config) return "";
  let brief = "";
  try { brief = require("./config-spec").templateBrief(assets.configTemplates || []); } catch { brief = ""; }
  return brief ? `\\nSettings to offer (category templates; key: type = default unit min..max):\\n${brief}\\n` : `\\nDeclare this mod's settings in assets/config/schema.json (see SETTINGS).\\n`;
}
function assetsBlock(assets) {
  if (assets && assets.config && !assets.texture && !assets.sound && !assets.datapack && !assets.design && !assets.creature) return `\\nThis mod's reserved namespace is ${assets.namespace}.\\n${configBlock(assets)}`;
  if (!assets || (!assets.texture && !assets.sound && !assets.datapack && !assets.design && !assets.creature)) return "";'''
assert old in s; s=s.replace(old,new)
old='''  return `\\nThis mod's reserved namespace is ${assets.namespace}.${tex}${ims}${snd}${dp}${dz}${cre_}\\n`;'''
new='''  return `\\nThis mod's reserved namespace is ${assets.namespace}.${tex}${ims}${snd}${dp}${dz}${cre_}\\n${configBlock(assets)}`;'''
assert old in s, "ret"
s=s.replace(old,new)
s=s.replace("module.exports = { PROMPT_VERSION,","module.exports = { CONFIG_SECTION, PROMPT_VERSION,")
open(p,'w').write(s)
EOF
