// Cyrus Config Studio: the portal's check of the settings schema a build returned (services/modbuilder/configs.js ->
// assetResult.config). The service is not trusted: the schema is validated again here and only then stored on the
// build (ModBuild.result.cyrusConfig), where the Config Studio reads it. Pure.
import { canonical, validateConfigSpec, type ConfigSpec } from "./spec";
import { createHash } from "node:crypto";

export type StoredBuildConfig = { source: "declared" | "inferred"; spec: ConfigSpec; specSha256: string; warnings: string[]; verify?: { read: number; undeclared: string[]; magic: { where: string; evidence: string }[] } };

export function checkReturnedConfig(raw: unknown): StoredBuildConfig | null {
  if (!raw || typeof raw !== "object") return null;
  const r = raw as { source?: unknown; spec?: unknown; warnings?: unknown; verify?: unknown };
  if (r.source !== "declared" && r.source !== "inferred") return null;
  const v = validateConfigSpec(r.spec);
  if (!v.ok) return null;
  const warnings = Array.isArray(r.warnings) ? r.warnings.filter((w): w is string => typeof w === "string").map((w) => w.slice(0, 300)).slice(0, 12) : [];
  const vf = r.verify as { read?: unknown; undeclared?: unknown; magic?: unknown } | undefined;
  const verify = vf && typeof vf === "object" ? {
    read: typeof vf.read === "number" ? vf.read : 0,
    undeclared: Array.isArray(vf.undeclared) ? vf.undeclared.filter((x): x is string => typeof x === "string").slice(0, 30) : [],
    magic: Array.isArray(vf.magic) ? vf.magic.filter((m): m is { where: string; evidence: string } => !!m && typeof m === "object" && typeof (m as { where?: unknown }).where === "string" && typeof (m as { evidence?: unknown }).evidence === "string").slice(0, 20).map((m) => ({ where: m.where.slice(0, 200), evidence: m.evidence.slice(0, 200) })) : [],
  } : undefined;
  return { source: r.source, spec: v.spec, specSha256: createHash("sha256").update(canonical(v.spec)).digest("hex"), warnings, ...(verify ? { verify } : {}) };
}
EOF
