const mobSpec = (): ConfigSpec => instantiateTemplate("mob", { prefix: "mobs.frost_zombie", reloadCommand: "/frost reload" });

describe("build check: declared tunables are read", () => {
  const spec = validateConfigSpec({ schemaVersion: 1, reload: { command: "/frost reload" }, groups: [{ id: "s", label: "S" }], params: [
    { key: "mobs.frost.health", group: "s", type: "number", label: "Health", default: 20, min: 1, max: 100, applies: "reload" },
    { key: "mobs.frost.speed", group: "s", type: "number", label: "Speed", default: 0.2, min: 0, max: 1, applies: "reload" },
    { key: "drops.enabled", group: "s", type: "bool", label: "Drops", default: true, applies: "reload" },
  ] });
  assert.ok(spec.ok);
  if (!spec.ok) return;
  it("exact keys, section iteration, undeclared keys and magic numbers", () => {
    const java = [{ rel: "src/main/java/a/Main.java", content: `
      double hp = getConfig().getDouble("mobs.frost.health");
      ConfigurationSection s = getConfig().getConfigurationSection("mobs");
      for (String id : s.getKeys(false)) { double sp = s.getConfigurationSection(id).getDouble("speed"); }
      boolean x = getConfig().getBoolean("debug-mode");
      zombie.getAttribute(Attribute.MAX_HEALTH).setBaseValue(40.0);
      // getConfig().getBoolean("drops.enabled") in a comment does not count
    ` }];
    const r = verifyTunables(spec.spec, java);
    assert.deepEqual(r.unread, ["drops.enabled"]);
    assert.deepEqual(r.read.sort(), ["mobs.frost.health", "mobs.frost.speed"]);
    assert.deepEqual(r.undeclared, ["debug-mode"]);
    assert.equal(r.magic.length, 1);
    assert.match(r.magic[0].where, /Main\.java:6/);
    assert.equal(verifyTunables(spec.spec, [{ rel: "x/CyrusSettings.java", content: javaSettingsClass(spec.spec, { pkg: "dev.x" }).source }], { accessorClass: "CyrusSettings" }).ok, true);
  });
  it("the Paper settings class reads and clamps every key", () => {
    const j = javaSettingsClass(mobSpec(), { pkg: "dev.nxeon.plugins.frost" });
    assert.equal(j.path, "src/main/java/dev/nxeon/plugins/frost/CyrusSettings.java");
    assert.equal(j.fields["mobs.frost_zombie.max_health"], "MOBS_FROST_ZOMBIE_MAX_HEALTH");
    assert.match(j.source, /public static double MOBS_FROST_ZOMBIE_MAX_HEALTH = 20\.0;/);
    assert.match(j.source, /MOBS_FROST_ZOMBIE_MAX_HEALTH = num\(c, "mobs\.frost_zombie\.max_health", 20\.0, 1\.0, 1024\.0, notes\);/);
    assert.match(j.source, /public static long MOBS_FROST_ZOMBIE_ATTACK_INTERVAL = 20L;/);
    assert.match(j.source, /public static double\[\] MOBS_FROST_ZOMBIE_GROUP_SIZE = new double\[\] \{ 1\.0, 4\.0 \};/);
    assert.ok(!/Runtime|ProcessBuilder|reflect|java\.net/.test(j.source));
    assert.equal(exporterFor("minecraft"), paperExporter);
    assert.equal(exporterFor("hytale")!.maturity, "planned");
    const r = paperExporter.render(mobSpec(), { "mobs.frost_zombie.max_health": 40 }, { pluginName: "FrostMobs" });
    assert.ok(r.ok && r.path === "plugins/FrostMobs/config.yml" && /max_health: 40\.0/.test(r.text));
  });
});

describe("build service: the SETTINGS round (configs.js + generated bundle)", () => {
  it("the bundle is current", async () => {
    const { configArtifacts } = await import("../scripts/cyrus/build-config-artifacts");
    for (const [rel, text] of Object.entries(await configArtifacts())) assert.equal(readFileSync(path.join(ROOT, rel), "utf8"), text, `${rel} is stale: run scripts/cyrus/build-config-artifacts.ts`);
  });
  const CFG = req(path.join(ROOT, "services/modbuilder/configs.js"));
  const ws = () => {
    const d = mkdtempSync(path.join(tmpdir(), "cyrus-cfg-"));
    const w = (rel: string, t: string) => { mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); writeFileSync(path.join(d, rel), t); };
    w("src/main/resources/plugin.yml", "name: FrostMobs\nversion: 1.0.0\nmain: dev.nxeon.plugins.frostmobs.FrostMobs\napi-version: '1.21.11'\ncommands:\n  frost:\n    description: Frost mobs\n    usage: /frost <spawn|reload>\n");
    w("src/main/java/dev/nxeon/plugins/frostmobs/FrostMobs.java", `package dev.nxeon.plugins.frostmobs;\npublic class FrostMobs { void a() { double h = getConfig().getDouble("mobs.frost.health"); double s = getConfig().getDouble("mobs.frost.speed"); } }\n`);
    return { d, w };
  };
  const schema = { schemaVersion: 1, reload: { command: "/frost reload" }, groups: [{ id: "stats", label: "Stats" }], params: [
    { key: "mobs.frost.health", group: "stats", type: "number", label: "Health", default: 40, unit: "hp", min: 1, max: 1024, applies: "reload" },
    { key: "mobs.frost.speed", group: "stats", type: "number", label: "Speed", default: 0.25, min: 0, max: 1, applies: "reload", visual: { channel: "clipRate", clip: "walk", ref: 0.23 } },
  ] };
  it("missing schema -> one repair, then inference from config.yml", () => {
    const { d, w } = ws();
    const st: Record<string, number> = {};
    const rec: Record<string, unknown> = { pluginName: "FrostMobs" };
    const p = CFG.configRound(d, rec, st, true);
    assert.equal(p.kind, "asset");
    assert.match(p.text, /assets\/config\/schema\.json/);
    w("src/main/resources/config.yml", "mobs:\n  frost:\n    # Health (1-500)\n    health: 30\n");
    assert.equal(CFG.configRound(d, rec, st, true), null);
    assert.equal((rec.configResult as { source: string }).source, "inferred");
    rmSync(d, { recursive: true, force: true });
  });
  it("declared schema: config.yml written from it with comments; an existing file keeps its comments and extra keys", () => {
    const { d, w } = ws();
    w("assets/config/schema.json", JSON.stringify(schema));
    w("src/main/resources/config.yml", "# my notes\nextra: 5\nmobs:\n  frost:\n    health: 10\n");
    const rec: Record<string, unknown> = { pluginName: "FrostMobs" };
    assert.equal(CFG.configRound(d, rec, {}, true), null);
    const yml = readFileSync(path.join(d, "src/main/resources/config.yml"), "utf8");
    assert.equal(yml, "# my notes\nextra: 5\nmobs:\n  frost:\n    health: 40.0\n    # Speed (0 to 1).\n    speed: 0.25\n");
    const r = rec.configResult as { source: string; spec: ConfigSpec; verify: { read: number } };
    assert.equal(r.source, "declared");
    assert.equal(r.verify.read, 2);
    assert.ok(checkReturnedConfig(rec.configResult), "the portal accepts what the service returns");
    rmSync(d, { recursive: true, force: true });
  });
  it("an unread key is a repair, then dropped with a warning; a reload command missing from plugin.yml becomes restart", () => {
    const { d, w } = ws();
    w("assets/config/schema.json", JSON.stringify({ ...schema, reload: { command: "/frostmobs reload" }, params: [...schema.params, { key: "mobs.frost.armor", group: "stats", type: "int", label: "Armor", default: 2, min: 0, max: 30, applies: "reload" }] }));
    const st: Record<string, number> = {};
    const rec: Record<string, unknown> = {};
    const p = CFG.configRound(d, rec, st, true);
    assert.match(p.text, /mobs\.frost\.armor is declared .* never reads it/);
    assert.equal(CFG.configRound(d, rec, st, true), null);
    const r = rec.configResult as { spec: ConfigSpec; warnings: string[] };
    assert.deepEqual(r.spec.params.map((x) => x.key), ["mobs.frost.health", "mobs.frost.speed"]);
    assert.ok(r.spec.params.every((x) => x.applies === "restart"));
    assert.equal(r.spec.reload, undefined);
    assert.ok(r.warnings.some((x) => /no frostmobs command/.test(x)));
    assert.ok(r.warnings.some((x) => /never reads/.test(x)));
    rmSync(d, { recursive: true, force: true });
  });
  it("prompt: the SETTINGS section and template keys only when routed (else byte-identical)", () => {
    const P = req(path.join(ROOT, "services/modbuilder/prompts.js"));
    const off = P.systemPrompt("1.21.11");
    assert.ok(!off.includes("SETTINGS (this build uses them)"));
    assert.ok(P.systemPrompt("1.21.11", { config: true }).endsWith(P.CONFIG_SECTION));
    assert.equal(P.assetsBlock({ texture: true, sound: false, namespace: "nx_abcd1234" }), P.assetsBlock({ texture: true, sound: false, namespace: "nx_abcd1234", config: false }));
    const b = P.assetsBlock({ texture: false, sound: false, namespace: "nx_abcd1234", config: true, configTemplates: ["mob"] });
    assert.match(b, /Settings to offer/);
    assert.match(b, /max_health: number = 20 hp 1\.\.1024/);
    assert.match(templateBrief(["gun"]), /fire_rate: int = 600 rpm 1\.\.1200 \[drives fireRate fire\]/);
    const TX = req(path.join(ROOT, "services/modbuilder/textures.js"));
    const a = TX.parseAssetsRequest({ texture: false, sound: false, namespace: "nx_abcd1234", config: true, configTemplates: ["mob", "gun"] }, "1.21.11", new Set(["1.21.11"]));
    assert.deepEqual([a.config, a.configTemplates], [true, ["mob", "gun"]]);
    assert.match(TX.parseAssetsRequest({ namespace: "nx_abcd1234", config: "yes" }, "1.21.11", new Set()).error, /config/);
  });
});

describe("portal route + ModSpec config section", () => {
  it("decideConfigRoute: off and designer builds decide nothing; on routes templates", () => {
    assert.deepEqual(decideConfigRoute({ text: "frost zombie mob", on: false, designRoute: false }), { route: false, templates: [] });
    assert.deepEqual(decideConfigRoute({ text: "frost zombie mob", on: true, designRoute: true }), { route: false, templates: [] });
    assert.deepEqual(decideConfigRoute({ text: "a frost zombie mob with an AK-47 gun", on: true, designRoute: false }), { route: true, templates: ["mob", "gun"] });
    assert.deepEqual(decideConfigRoute({ text: "hello", on: true, designRoute: false, category: "economy" }), { route: true, templates: ["shop"] });
    assert.deepEqual(decideConfigRoute({ text: "hello", on: true, designRoute: false }), { route: true, templates: ["utility"] });
  });
  it("resolveBuildAssets: config alone creates the project and routes; off stays byte-identical (NONE)", async () => {
    const deps = { tierOf: async () => "free", projectForRootBuild: async () => null, createProject: async () => ({ id: "cp1", namespace: "nx_abcd1234" }), dataPackStudioOn: () => false, designerOn: () => false, itemStatesOn: () => false };
    const off = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "a frost zombie mob", mcVersion: "1.21.11" }, { ...deps, configStudioOn: () => false });
    assert.deepEqual(off, { plan: null, service: null, meta: null });
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text: "a frost zombie mob", mcVersion: "1.21.11" }, { ...deps, configStudioOn: () => true });
    assert.deepEqual(on.service, { texture: false, sound: false, namespace: "nx_abcd1234", config: true, configTemplates: ["mob"] });
    assert.deepEqual(on.meta?.config, { route: true, templates: ["mob"] });
  });
  it("a ModSpec may carry its settings; bad values are errors at config.values.<key>", () => {
    const base = { schemaVersion: 1, game: "minecraft", target: { version: "1.21.11" }, namespace: "nx_abcd1234", summary: "Frost zombies for winter biomes", routes: ["plugin"], requirements: [{ id: "REQ-1", text: "Frost zombies spawn" }], install: { side: "server", restartRequired: true } };
    const ok = validateModSpec({ ...base, config: { spec: mobSpec(), values: { "mobs.frost_zombie.max_health": 40 } } });
    assert.ok(ok.ok, JSON.stringify(!ok.ok && ok.errors));
    const bad = validateModSpec({ ...base, config: { spec: mobSpec(), values: { "mobs.frost_zombie.max_health": 99999 } } });
    assert.ok(!bad.ok && bad.errors.some((e) => e.path === "config.values.mobs.frost_zombie.max_health"));
    const rule = validateModSpec({ ...base, config: { spec: { ...mobSpec(), reload: undefined } } });
    assert.ok(!rule.ok && rule.errors.some((e) => e.code === "reload_without_command"));
    assert.ok(validateModSpec(base).ok, "no config section: as before");
  });
});

describe("the 'just tweak a setting' recogniser (no model)", () => {
  const spec = validateConfigSpec(mergeSpecs([instantiateTemplate("mob", { prefix: "mobs.frost_zombie", groupPrefix: "frost", reloadCommand: "/f reload" }), instantiateTemplate("gun", { prefix: "guns.ak47", groupPrefix: "ak", reloadCommand: "/f reload" })]));
  assert.ok(spec.ok);
  if (!spec.ok) return;
  it("resolves clauses to one setting each, with units", () => {
    const r = planConfigEdit("set the max health to 40 and the movement speed to 0.3", spec.spec);
    assert.deepEqual(r, { kind: "values", edits: [{ key: "mobs.frost_zombie.max_health", value: 40 }, { key: "mobs.frost_zombie.move_speed", value: 0.3 }], summary: ["Max health: 20 hp -> 40 hp", "Movement speed: 0.23 -> 0.3"] });
    const g = planConfigEdit("change the reload time to 3 seconds, magazine size to 40 and fire mode to semi", spec.spec);
    assert.ok(g.kind === "values");
    if (g.kind === "values") assert.deepEqual(g.edits, [{ key: "guns.ak47.reload_time", value: 60 }, { key: "guns.ak47.magazine_size", value: 40 }, { key: "guns.ak47.fire_mode", value: "semi" }]);
    const h = planConfigEdit("set max health to 10 hearts", spec.spec);
    assert.ok(h.kind === "values" && h.edits[0].value === 20);
  });
  it("anything ambiguous, structural or out of range goes to the model", () => {
    assert.equal(planConfigEdit("set damage to 9", spec.spec).kind, "model", "mob attack damage vs gun damage");
    assert.match((planConfigEdit("add a boss", spec.spec) as { reason: string }).reason, /structural/);
    assert.match((planConfigEdit("set max health to 5000", spec.spec) as { reason: string }).reason, /outside/);
    assert.equal(planConfigEdit("make it cooler", spec.spec).kind, "model");
  });
});

