function memStore(userId = "u1") {
  const revs: RevRow[] = [];
  const rows: AssetRow[] = [];
  let t = Date.parse("2026-10-10T10:00:00Z");
  const project = { id: "cp00000000000000000001", userId, namespace: "nx_frost001", rootBuildId: "b1", headRevisionId: null as string | null, title: null };
  const store: ConfigServiceDeps["store"] = {
    projectForRoot: async (r) => (r === "b1" ? project : null),
    assets: async () => rows,
    revisions: async () => revs,
    addRevision: async (_p, i) => {
      const head = revs[revs.length - 1]?.id ?? null;
      if (i.expectedHeadId !== undefined && i.expectedHeadId !== head) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const r = { id: `rev${revs.length + 1}`, seq: revs.length + 1, kind: i.kind, status: i.status ?? "pending", message: i.message ?? null, createdAt: new Date(t += 1000), manifest: i.manifest as RevRow["manifest"], modBuildId: null };
      revs.push(r); project.headRevisionId = r.id; return { id: r.id, seq: r.seq };
    },
    recordAsset: async (projectId, a) => { const row = { id: `a${rows.length + 1}`, projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) }; rows.push(row); return { id: row.id }; },
  };
  return { store, revs, rows, project };
}
const YML = "# FrostMobs\nmobs:\n  frost:\n    # Health in half-hearts (1-1024)\n    health: 40\n    speed: 0.25  # walk speed\n";
const PLUGIN = "name: FrostMobs\ncommands:\n  frost:\n    usage: /frost reload\n";
const src = (o: Partial<ConfigSource> = {}): ConfigSource => ({ buildId: "b1", pluginName: "FrostMobs", mcVersion: "1.21.11", configYml: YML, pluginYml: PLUGIN, declared: null, ...o });

describe("values-only service", () => {
  it("view (inferred), preview, save (revision kind config + values asset), stale head, no change, undo", async () => {
    const m = memStore();
    const deps: ConfigServiceDeps = { store: m.store, source: async (u, r) => (u === "u1" && r === "b1" ? src() : null) };
    const v = await configView(deps, "u1", "b1");
    assert.equal(v.source, "inferred");
    assert.deepEqual(v.values, { "mobs.frost.health": 40, "mobs.frost.speed": 0.25 });
    assert.equal(v.deliveryConnected, false);
    const pv = await previewConfig(deps, "u1", "b1", { "mobs.frost.health": 60 });
    assert.equal(pv.configYml, YML.replace("health: 40", "health: 60"));
    assert.equal(pv.applies, "reload");
    const s = await saveConfigValues(deps, { userId: "u1", rootBuildId: "b1", values: { "mobs.frost.health": 60 }, expectedHeadId: null });
    assert.equal(s.seq, 1);
    assert.equal(m.revs[0].kind, "config");
    assert.deepEqual(m.revs[0].manifest.map((e) => [e.path, e.role]), [["src/main/resources/config.yml", "config"]]);
    assert.equal(m.rows[0].mime, CONFIG_VALUES_MIME);
    assert.equal(m.revs[0].message, "Changed 1 setting: Health");
    await assert.rejects(saveConfigValues(deps, { userId: "u1", rootBuildId: "b1", values: { "mobs.frost.health": 70 }, expectedHeadId: null }), (e: { code: string }) => e.code === "stale_head");
    await assert.rejects(saveConfigValues(deps, { userId: "u1", rootBuildId: "b1", values: { "mobs.frost.health": 60 }, expectedHeadId: "rev1" }), (e: { code: string }) => e.code === "no_change");
    await assert.rejects(saveConfigValues(deps, { userId: "u1", rootBuildId: "b1", values: { "mobs.frost.health": 0 }, expectedHeadId: "rev1" }), (e: { code: string }) => e.code === "invalid_values");
    const s2 = await saveConfigValues(deps, { userId: "u1", rootBuildId: "b1", values: { "mobs.frost.speed": 0.4 }, expectedHeadId: "rev1" });
    assert.equal(s2.configYml, YML.replace("health: 40", "health: 60").replace("speed: 0.25", "speed: 0.4"), "builds on the previous save; comments kept");
    const v2 = await configView(deps, "u1", "b1");
    assert.deepEqual(v2.values, { "mobs.frost.health": 60, "mobs.frost.speed": 0.4 });
    assert.deepEqual(v2.history.map((h) => h.seq), [2, 1]);
    const u = await revertConfig(deps, { userId: "u1", rootBuildId: "b1", revisionId: "rev2", expectedHeadId: "rev2" });
    assert.equal(u.seq, 3);
    assert.deepEqual((await configView(deps, "u1", "b1")).values, { "mobs.frost.health": 60, "mobs.frost.speed": 0.25 });
    await assert.rejects(deliverConfigValues(deps, { userId: "u1", rootBuildId: "b1", serverId: "s1" }), (e: { status: number }) => e.status === 501);
  });
  it("ownership fails closed; declared schemas win; designer mods use the designer params", async () => {
    const m = memStore("someone-else");
    const deps: ConfigServiceDeps = { store: m.store, source: async () => src() };
    await assert.rejects(configView(deps, "u1", "b1"), (e: { status: number }) => e.status === 404);
    const declared = resolveSchema(src({ declared: { source: "declared", spec: mobSpec() } }), [], "nx_frost001");
    assert.equal(declared.source, "declared");
    const designs = ["void_reaper", "storm_staff"].map((n, i) => ({ id: `d${i}`, projectId: "p", revisionId: "r", assetKey: n, kind: "design", sha256: "0".repeat(64), size: 1, origin: "generated", mime: null, path: null, provenance: { spec: JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer", `${n}.json`), "utf8")) }, createdAt: new Date() }));
    const dz = resolveSchema(src({ pluginName: "VoidArsenal" }), designs, "nx_r7design");
    assert.equal(dz.source, "designer");
    assert.ok(dz.spec!.params.some((p) => p.key === "items.void_reaper.abilities.void_pull.cooldown_ticks" && p.type === "duration"));
    assert.equal(dz.spec!.reload!.command, "/voidarsenal reload");
  });
  it("HTTP: hidden (404) without a viewer or with the flag off; GET view; POST save / plan", async () => {
    const m = memStore();
    const mk = (o: Partial<ConfigApiDeps> = {}): ConfigApiDeps => ({ viewer: async () => ({ userId: "u1", preview: true }), flagOn: () => true, service: { store: m.store, source: async () => src() }, rateLimit: () => ({ ok: true }), ...o });
    assert.equal((await handleConfig(new Request("http://x/api/cyrus/config/v1?root=b1"), mk({ flagOn: () => false }))).status, 404);
    assert.equal((await handleConfig(new Request("http://x/api/cyrus/config/v1?root=b1"), mk({ viewer: async () => null }))).status, 404);
    const g = await handleConfig(new Request("http://x/api/cyrus/config/v1?root=b1"), mk());
    assert.equal(g.status, 200);
    assert.equal((await g.json()).source, "inferred");
    const post = (b: unknown) => handleConfig(new Request("http://x/api/cyrus/config/v1", { method: "POST", body: JSON.stringify(b) }), mk());
    const s = await post({ root: "b1", action: "save", values: { "mobs.frost.health": 50 }, expectedHeadId: null });
    assert.equal(s.status, 201);
    assert.equal((await post({ root: "b1", action: "save", values: { "mobs.frost.health": 55 }, expectedHeadId: null })).status, 409);
    const p = await (await post({ root: "b1", action: "plan", text: "set health to 70" })).json();
    assert.deepEqual(p.edits, [{ key: "mobs.frost.health", value: 70 }]);
    assert.equal((await post({ root: "b1", action: "nope" })).status, 400);
    assert.equal((await post({ root: "../x", action: "plan", text: "x" })).status, 400);
    assert.equal((await handleConfig(new Request("http://x/api/cyrus/config/v1?root=b1"), mk({ rateLimit: () => ({ ok: false, retryAfterSec: 9 }) }))).status, 429);
  });
});

