describe("deliverConfig through the delivery orchestrator (fake server)", () => {
  it("planApply: reload -> the mod's command, restart -> restart, live -> nothing", () => {
    const base = { jarChanged: false, managedChanged: false, datapacks: [], modelsChanged: false, managedConfigChanged: false, loaderChanged: false };
    assert.deepEqual([planApply({ ...base, config: { changed: true, applies: "reload", reloadCommand: "/frost reload" } }).mode, planApply({ ...base, config: { changed: true, applies: "reload", reloadCommand: "/frost reload" } }).pluginReload], ["none", "frost reload"]);
    assert.equal(planApply({ ...base, config: { changed: true, applies: "restart" } }).mode, "restart");
    assert.equal(planApply({ ...base, config: { changed: true, applies: "reload" } }).mode, "restart", "no reload command: restart");
    const live = planApply({ ...base, config: { changed: true, applies: "live" } });
    assert.deepEqual([live.mode, live.pluginReload], ["none", undefined]);
    assert.deepEqual(planApply(base), { mode: "none", reasons: [], consoleAfter: [], requireCameUp: false, handoff: false }, "no config: as before");
  });
  const setup = (reply = "FrostMobs config reloaded") => {
    const s = new FakeServer();
    seedServer(s);
    const w = (rel: string, d: Buffer | string) => { mkdirSync(path.dirname(path.join(s.dir, rel)), { recursive: true }); writeFileSync(path.join(s.dir, rel), d); };
    w("opt/mc/plugins/FrostMobs-1.0.0.jar", pluginJar("FrostMobs"));
    w("opt/mc/plugins/FrostMobs/config.yml", YML);
    s.booted = s.boot();
    const host = s.host({ env: { CYRUS_CONFIG_STUDIO: "1" } });
    const open = host.open.bind(host);
    host.open = async (id) => { const sess = await open(id); return { ...sess, console: async (cmd: string) => { s.consoleLog.push(cmd); return { ok: true as const, reply: cmd === "frost reload" ? reply : "ok" }; } }; };
    return { s, host };
  };
  const spec = () => { const r = validateConfigSpec({ schemaVersion: 1, reload: { command: "/frost reload" }, groups: [{ id: "s", label: "S" }], params: [
    { key: "mobs.frost.health", group: "s", type: "int", label: "Health", default: 40, min: 1, max: 1024, applies: "reload" },
    { key: "mobs.frost.speed", group: "s", type: "number", label: "Speed", default: 0.25, min: 0, max: 1, applies: "reload" },
    { key: "mobs.frost.biomes", group: "s", type: "list", label: "Biomes", default: [], item: { type: "text" }, applies: "restart" },
  ] }); assert.ok(r.ok); return (r as { spec: ConfigSpec }).spec; };
  const rel = (values: Record<string, unknown>, changed: string[]) => ({ projectId: "cp00000000000000000001", revisionId: "rev1", pluginName: "FrostMobs", spec: spec(), values: { ...defaultsOf(spec()), ...values } as never, changed });
  it("reload: the server's file is merged (comments kept), /frost reload sent, healthy", async () => {
    const { s, host } = setup();
    const r = await deliverConfig("srv1", rel({ "mobs.frost.health": 80 }, ["mobs.frost.health"]), host);
    assert.equal(r.outcome, "updated", JSON.stringify(r.steps));
    assert.equal(r.op, "config");
    assert.deepEqual(r.apply, { mode: "none", reasons: ["the mod re-reads its settings with /frost reload"], restarted: false, reloaded: false });
    assert.equal(s.read("opt/mc/plugins/FrostMobs/config.yml")!.toString(), YML.replace("health: 40", "health: 80"));
    assert.deepEqual(s.consoleLog, ["frost reload"]);
    assert.equal(s.restarts, 0);
    assert.ok(r.notes.some((n) => /FrostMobs config reloaded/.test(n)));
    const again = await deliverConfig("srv1", rel({ "mobs.frost.health": 80 }, ["mobs.frost.health"]), host);
    assert.equal(again.outcome, "unchanged");
    s.cleanup();
  });
  it("a failing reload reply rolls back to the exact old file and reloads it", async () => {
    const { s, host } = setup("Unknown or incomplete command, see below for error");
    const before = s.tree({ excludeJournal: true });
    const r = await deliverConfig("srv1", rel({ "mobs.frost.health": 80 }, ["mobs.frost.health"]), host);
    assert.equal(r.outcome, "rolled_back");
    assert.equal(r.failedStep, "apply");
    assert.equal(s.read("opt/mc/plugins/FrostMobs/config.yml")!.toString(), YML);
    assert.equal(s.tree({ excludeJournal: true }), before);
    assert.deepEqual(s.consoleLog, ["frost reload", "frost reload"], "reloaded again on the old file");
    s.cleanup();
  });
  it("a restart setting restarts; bad values, unknown keys, a missing mod and the flag are refused before anything changes", async () => {
    const { s, host } = setup();
    const r = await deliverConfig("srv1", rel({ "mobs.frost.biomes": ["ICE_SPIKES"] }, ["mobs.frost.biomes"]), host);
    assert.equal(r.outcome, "updated");
    assert.equal(s.restarts, 1);
    assert.match(s.read("opt/mc/plugins/FrostMobs/config.yml")!.toString(), /biomes: \[ICE_SPIKES\]/);
    const before = s.tree({ excludeJournal: true });
    assert.match((await deliverConfig("srv1", rel({ "mobs.frost.health": 5000 }, ["mobs.frost.health"]), host)).error!, /outside the allowed/);
    assert.match((await deliverConfig("srv1", rel({}, ["mobs.nope"]), host)).error!, /not a setting/);
    assert.match((await deliverConfig("srv1", { ...rel({ "mobs.frost.health": 50 }, ["mobs.frost.health"]), pluginName: "Missing" }, host)).error!, /not installed/);
    const offHost = s.host();
    assert.match((await deliverConfig("srv1", rel({ "mobs.frost.health": 50 }, ["mobs.frost.health"]), offHost)).error!, /CYRUS_CONFIG_STUDIO/);
    assert.equal(s.tree({ excludeJournal: true }), before);
    assert.ok(s.files(`${BASE.slice(1)}/plugins`).includes("FrostMobs-1.0.0.jar"));
    s.cleanup();
  });
});

