// REAL Config Studio runs ON node-2 (not part of the unit suite: real javac, real Paper boots via Test Flight).
//   scripts/devhost run --lock -- npx tsx test/cyrus-config-real.ts --out /tank/nxeon-build/tmp/cyrus-r23-config/results.json
// No real client, no AI model: the mod is a hand-written fixture (what the model would write) that reads its stats
// through the generated CyrusSettings class; the settings schema is the mob template.
// Per lane (1.21.11 on JDK 21, 26.2 on JDK 25):
//   1. ConfigSpec (mob template) -> config.yml (renderConfigYml) + CyrusSettings.java (javaSettingsClass); verifyTunables
//      says every key is read; javac (0 warnings) -> jar.
//   2. Flight A (baseline): plugin enabled, a frost zombie spawned, its REAL attributes = the defaults (plugin readout +
//      the vanilla `attribute` command).
//   3. Studio path: saveConfigValues (values-only revision, in-memory store) -> config.yml text; a bad value (5000 hp)
//      is REFUSED by the studio; deliverConfig (the real orchestrator, journaled, against a copy of the server dir)
//      merges the values into the server's file and issues the mod's reload command; its health probe uses flight A.
//   4. Flight B: boots with the OLD config, spawns, writes the DELIVERED config.yml, runs the command the orchestrator
//      issued (/frostmobs reload) on the live server -> the existing zombie and a new one carry the NEW values
//      (plugin readout + vanilla `attribute`); then a hand-edited bad file (5000 hp, "fast" speed) + reload -> clamped
//      to 1024 and the bad speed falls back to its default, with the notes in the reply.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { instantiateTemplate, renderConfigYml, defaultsOf, readValues } from "../lib/cyrus/config";
import { javaSettingsClass } from "../lib/cyrus/config/exporters";
import { verifyTunables } from "../lib/cyrus/config/verify";
import { saveConfigValues, previewConfig, type ConfigServiceDeps } from "../lib/cyrus/config/service";
import { deliverConfig } from "../lib/cyrus/delivery/orchestrator";
import type { DeliveryHost, HealthReport, ServerSession } from "../lib/cyrus/delivery/types";
import type { AssetRow, RevRow } from "../lib/cyrus/studios/service";
import { LocalGuestFs } from "../lib/mods/guest-fs";

const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r23-config/run-${Date.now().toString(36)}`;
const LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const PKG = "dev.nxeon.plugins.frostmobs";
const P = "mobs.frost_zombie.";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: TestFlightSpec, label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 14; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
const walk = (dir: string, out: string[] = []): string[] => { for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); } return out; };

/** The schema: the mob template's stats + combat (what Cyrus offers a mob mod), reloaded with /frostmobs reload. */
const SPEC = instantiateTemplate("mob", { prefix: "mobs.frost_zombie", reloadCommand: "/frostmobs reload", include: ["max_health", "armor", "move_speed", "knockback_resistance", "scale", "attack_damage", "knockback"] });
const F = javaSettingsClass(SPEC, { pkg: PKG }).fields;

/** What the model would write: a mod that reads every stat through the generated settings class. */
const MAIN = `package ${PKG};

import java.util.ArrayList;
import java.util.List;
import org.bukkit.Bukkit;
import org.bukkit.World;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Zombie;
import org.bukkit.plugin.java.JavaPlugin;

public class FrostMobs extends JavaPlugin {
    static final String TAG = "cyrus_frost";

    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String n : CyrusSettings.load(getConfig())) getLogger().warning(n);
        getLogger().info("FrostMobs settings loaded");
    }

    private static void set(LivingEntity e, Attribute a, double v) {
        AttributeInstance i = e.getAttribute(a);
        if (i != null) i.setBaseValue(v);
    }

    private static void apply(Zombie z) {
        set(z, Attribute.MAX_HEALTH, CyrusSettings.${F[P + "max_health"]});
        set(z, Attribute.ARMOR, CyrusSettings.${F[P + "armor"]});
        set(z, Attribute.MOVEMENT_SPEED, CyrusSettings.${F[P + "move_speed"]});
        set(z, Attribute.KNOCKBACK_RESISTANCE, CyrusSettings.${F[P + "knockback_resistance"]});
        set(z, Attribute.SCALE, CyrusSettings.${F[P + "scale"]});
        set(z, Attribute.ATTACK_DAMAGE, CyrusSettings.${F[P + "attack_damage"]});
        set(z, Attribute.ATTACK_KNOCKBACK, CyrusSettings.${F[P + "knockback"]});
        z.setHealth(CyrusSettings.${F[P + "max_health"]});
    }

    private static List<Zombie> frost() {
        List<Zombie> out = new ArrayList<>();
        for (World w : Bukkit.getWorlds()) for (Zombie z : w.getEntitiesByClass(Zombie.class)) if (z.getScoreboardTags().contains(TAG)) out.add(z);
        return out;
    }

    private static String base(LivingEntity e, Attribute a) {
        AttributeInstance i = e.getAttribute(a);
        return i == null ? "none" : String.valueOf(i.getBaseValue());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0] : "";
        switch (sub) {
            case "spawn" -> {
                World w = Bukkit.getWorlds().get(0);
                Zombie z = w.spawn(w.getSpawnLocation(), Zombie.class, zz -> {
                    zz.addScoreboardTag(TAG);
                    zz.setPersistent(true);
                    zz.setRemoveWhenFarAway(false);
                    zz.setAI(false);
                    zz.setInvulnerable(true);
                });
                apply(z);
                sender.sendMessage("spawned frost zombie " + frost().size());
            }
            case "stats" -> {
                List<Zombie> all = frost();
                sender.sendMessage("frost zombies: " + all.size());
                for (Zombie z : all) sender.sendMessage("stats health=" + base(z, Attribute.MAX_HEALTH) + " speed=" + base(z, Attribute.MOVEMENT_SPEED) + " damage=" + base(z, Attribute.ATTACK_DAMAGE) + " scale=" + base(z, Attribute.SCALE) + " armor=" + base(z, Attribute.ARMOR) + " hp=" + z.getHealth());
            }
            case "reload" -> {
                reloadConfig();
                List<String> notes = CyrusSettings.load(getConfig());
                List<Zombie> all = frost();
                for (Zombie z : all) apply(z);
                sender.sendMessage("FrostMobs config reloaded (" + all.size() + " frost zombies updated)");
                for (String n : notes) sender.sendMessage(n);
            }
            default -> sender.sendMessage("FrostMobs: /frostmobs <spawn|stats|reload>");
        }
        return true;
    }
}
`;
const PLUGIN_YML = (mc: string) => `name: FrostMobs
version: '1.0.0'
main: ${PKG}.FrostMobs
api-version: '${mc}'
description: 'Frost zombies with editable stats (Cyrus Config Studio flight fixture)'
author: Nxeon Mod Builder
commands:
