}

/** deliverConfig against a copy of the server dir; the console command is recorded and replayed on the live flight server. */
async function deliver(lane: (typeof LANES)[number], jarPath: string, oldYml: string, values: Record<string, unknown>, changed: string[], health: HealthReport) {
