// REAL Config Studio runs ON node-2 (not part of the unit suite: real javac, real Paper boots via Test Flight).
//   scripts/devhost run --lock -- npx tsx test/cyrus-config-real.ts --out /tank/nxeon-build/tmp/cyrus-r23-config/results.json
// No real client, no AI model: the mod is a hand-written fixture (what the model would write) that reads its stats
// through the generated CyrusSettings class; the settings schema is the mob template.
// Per lane (1.21.11 on JDK 21, 26.2 on JDK 25):
//   1. ConfigSpec (mob template) -> config.yml (renderConfigYml) + CyrusSettings.java (javaSettingsClass); verifyTunables
//      says every key is read; javac (0 warnings) -> jar.
//   2. Flight A (baseline): plugin enabled, a frost zombie spawned, its REAL attributes = the defaults (plugin readout +
//      the vanilla `attribute` command).
//   3. Studio path: saveConfigValues (values-only revision, in-memory store) -> config.yml text; a bad value (5000 hp)
//      is REFUSED by the studio; deliverConfig (the real orchestrator, journaled, against a copy of the server dir)
//      merges the values into the server's file and issues the mod's reload command; its health probe uses flight A.
//   4. Flight B: boots with the OLD config, spawns, writes the DELIVERED config.yml, runs the command the orchestrator
//      issued (/frostmobs reload) on the live server -> the existing zombie and a new one carry the NEW values
//      (plugin readout + vanilla `attribute`); then a hand-edited bad file (5000 hp, "fast" speed) + reload -> clamped
//      to 1024 and the bad speed falls back to its default, with the notes in the reply.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { instantiateTemplate, renderConfigYml, defaultsOf, readValues } from "../lib/cyrus/config";
import { javaSettingsClass } from "../lib/cyrus/config/exporters";
import { verifyTunables } from "../lib/cyrus/config/verify";
import { saveConfigValues, previewConfig, type ConfigServiceDeps } from "../lib/cyrus/config/service";
import { deliverConfig } from "../lib/cyrus/delivery/orchestrator";
import type { DeliveryHost, HealthReport, ServerSession } from "../lib/cyrus/delivery/types";
import type { AssetRow, RevRow } from "../lib/cyrus/studios/service";
import { LocalGuestFs } from "../lib/mods/guest-fs";

const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r23-config/run-${Date.now().toString(36)}`;
const LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const PKG = "dev.nxeon.plugins.frostmobs";
const P = "mobs.frost_zombie.";
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: TestFlightSpec, label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 14; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}
const walk = (dir: string, out: string[] = []): string[] => { for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); } return out; };

/** The schema: the mob template's stats + combat (what Cyrus offers a mob mod), reloaded with /frostmobs reload. */
const SPEC = instantiateTemplate("mob", { prefix: "mobs.frost_zombie", reloadCommand: "/frostmobs reload", include: ["max_health", "armor", "move_speed", "knockback_resistance", "scale", "attack_damage", "knockback"] });
const F = javaSettingsClass(SPEC, { pkg: PKG }).fields;

/** What the model would write: a mod that reads every stat through the generated settings class. */
const MAIN = `package ${PKG};

import java.util.ArrayList;
import java.util.List;
import org.bukkit.Bukkit;
import org.bukkit.World;
import org.bukkit.attribute.Attribute;
import org.bukkit.attribute.AttributeInstance;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Zombie;
import org.bukkit.plugin.java.JavaPlugin;

public class FrostMobs extends JavaPlugin {
    static final String TAG = "cyrus_frost";

    @Override
    public void onEnable() {
        saveDefaultConfig();
        for (String n : CyrusSettings.load(getConfig())) getLogger().warning(n);
        getLogger().info("FrostMobs settings loaded");
    }

    private static void set(LivingEntity e, Attribute a, double v) {
        AttributeInstance i = e.getAttribute(a);
        if (i != null) i.setBaseValue(v);
    }

    private static void apply(Zombie z) {
        set(z, Attribute.MAX_HEALTH, CyrusSettings.${F[P + "max_health"]});
        set(z, Attribute.ARMOR, CyrusSettings.${F[P + "armor"]});
        set(z, Attribute.MOVEMENT_SPEED, CyrusSettings.${F[P + "move_speed"]});
        set(z, Attribute.KNOCKBACK_RESISTANCE, CyrusSettings.${F[P + "knockback_resistance"]});
        set(z, Attribute.SCALE, CyrusSettings.${F[P + "scale"]});
        set(z, Attribute.ATTACK_DAMAGE, CyrusSettings.${F[P + "attack_damage"]});
        set(z, Attribute.ATTACK_KNOCKBACK, CyrusSettings.${F[P + "knockback"]});
        z.setHealth(CyrusSettings.${F[P + "max_health"]});
    }

    private static List<Zombie> frost() {
        List<Zombie> out = new ArrayList<>();
        for (World w : Bukkit.getWorlds()) for (Zombie z : w.getEntitiesByClass(Zombie.class)) if (z.getScoreboardTags().contains(TAG)) out.add(z);
        return out;
    }

    private static String base(LivingEntity e, Attribute a) {
        AttributeInstance i = e.getAttribute(a);
        return i == null ? "none" : String.valueOf(i.getBaseValue());
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        String sub = args.length > 0 ? args[0] : "";
        switch (sub) {
            case "spawn" -> {
                World w = Bukkit.getWorlds().get(0);
                Zombie z = w.spawn(w.getSpawnLocation(), Zombie.class, zz -> {
                    zz.addScoreboardTag(TAG);
                    zz.setPersistent(true);
                    zz.setRemoveWhenFarAway(false);
                    zz.setAI(false);
                    zz.setInvulnerable(true);
                });
                apply(z);
                sender.sendMessage("spawned frost zombie " + frost().size());
            }
            case "stats" -> {
                List<Zombie> all = frost();
                sender.sendMessage("frost zombies: " + all.size());
                for (Zombie z : all) sender.sendMessage("stats health=" + base(z, Attribute.MAX_HEALTH) + " speed=" + base(z, Attribute.MOVEMENT_SPEED) + " damage=" + base(z, Attribute.ATTACK_DAMAGE) + " scale=" + base(z, Attribute.SCALE) + " armor=" + base(z, Attribute.ARMOR) + " hp=" + z.getHealth());
            }
            case "reload" -> {
                reloadConfig();
                List<String> notes = CyrusSettings.load(getConfig());
                List<Zombie> all = frost();
                for (Zombie z : all) apply(z);
                sender.sendMessage("FrostMobs config reloaded (" + all.size() + " frost zombies updated)");
                for (String n : notes) sender.sendMessage(n);
            }
            default -> sender.sendMessage("FrostMobs: /frostmobs <spawn|stats|reload>");
        }
        return true;
    }
}
`;
const PLUGIN_YML = (mc: string) => `name: FrostMobs
version: '1.0.0'
main: ${PKG}.FrostMobs
api-version: '${mc}'
description: 'Frost zombies with editable stats (Cyrus Config Studio flight fixture)'
author: Nxeon Mod Builder
commands:
  frostmobs:
    description: 'FrostMobs: spawn, stats, reload'
    usage: '/frostmobs <spawn|stats|reload>'
    permission: frostmobs.admin
permissions:
  frostmobs.admin:
    description: 'Use /frostmobs'
    default: op
`;

function build(lane: (typeof LANES)[number], configYml: string) {
  const dir = path.join(RUN, lane.version);
  rmSync(dir, { recursive: true, force: true });
  const settings = javaSettingsClass(SPEC, { pkg: PKG });
  const src = path.join(dir, "src");
  const files = [{ rel: settings.path, content: settings.source }, { rel: `src/main/java/${PKG.replace(/\./g, "/")}/FrostMobs.java`, content: MAIN }];
  for (const f of files) { const abs = path.join(dir, f.rel); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const verify = verifyTunables(SPEC, files, { accessorClass: "CyrusSettings" });
  const verifyMainOnly = verifyTunables(SPEC, files.slice(1));
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  const sources = walk(path.join(dir, "src/main/java")).filter((f) => f.endsWith(".java")).sort();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 6000)); }
  writeFileSync(path.join(classes, "plugin.yml"), PLUGIN_YML(lane.version));
  writeFileSync(path.join(classes, "config.yml"), configYml);
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, "FrostMobs-1.0.0.jar");
  execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  void src;
  return { jarPath, jarSha256: sha(readFileSync(jarPath)), javacWarnings: (javacOut.match(/warning:/g) ?? []).length, sources: sources.length, verify: { ok: verify.ok, read: verify.read.length, viaAccessor: verify.accessor, unread: verify.unread, mainAloneReadsNone: verifyMainOnly.unread.length === SPEC.params.length } };
}

/** The studio's values-only save path with an in-memory store (the same service the API uses). */
function studio(configYml: string) {
  const revs: RevRow[] = []; const rows: AssetRow[] = []; let t = Date.now();
  const project = { id: "cp0000000000000000r23f", userId: "owner", namespace: "nx_r23frost", rootBuildId: "b-r23", headRevisionId: null as string | null, title: null };
  const deps: ConfigServiceDeps = {
    source: async () => ({ buildId: "b-r23", pluginName: "FrostMobs", mcVersion: "1.21.11", configYml, pluginYml: PLUGIN_YML("1.21.11"), declared: { source: "declared", spec: SPEC } }),
    store: {
      projectForRoot: async () => project, assets: async () => rows, revisions: async () => revs,
      addRevision: async (_p, i) => { const r = { id: `rev${revs.length + 1}`, seq: revs.length + 1, kind: i.kind, status: i.status ?? "pending", message: i.message ?? null, createdAt: new Date(t += 1000), manifest: i.manifest as RevRow["manifest"], modBuildId: null }; revs.push(r); project.headRevisionId = r.id; return { id: r.id, seq: r.seq }; },
      recordAsset: async (projectId, a) => { rows.push({ id: `a${rows.length}`, projectId, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) }); return { id: `a${rows.length}` }; },
    },
  };
  return { deps, revs, rows };
}

/** deliverConfig against a copy of the server dir; the console command is recorded and replayed on the live flight server. */
async function deliver(lane: (typeof LANES)[number], jarPath: string, oldYml: string, values: Record<string, unknown>, changed: string[], health: HealthReport) {
  const root = mkdtempSync(path.join(RUN, "srv-"));
  const w = (rel: string, d: Buffer | string) => { mkdirSync(path.dirname(path.join(root, rel)), { recursive: true }); writeFileSync(path.join(root, rel), d); };
  w("opt/mc/server.properties", "level-name=world\n");
  w("opt/mc/version_history.json", JSON.stringify({ currentVersion: `${lane.version} (MC: ${lane.version})` }));
  w("opt/mc/plugins/FrostMobs-1.0.0.jar", readFileSync(jarPath));
  w("opt/mc/plugins/FrostMobs/config.yml", oldYml);
  const issued: string[] = [];
  const fs = new LocalGuestFs(root);
  const session: ServerSession = {
    fs, base: "/opt/mc", levelName: "world", mcVersion: lane.version,
    async restart() { return { ok: false, error: "not used: the settings apply with /frostmobs reload" }; },
    async console(cmd) { issued.push(cmd); return { ok: true, reply: "queued: replayed on the Test Flight server (flight B)" }; },
    async health() { return health; },
  };
  const host: DeliveryHost = {
    env: { CYRUS_DELIVERY: "1", CYRUS_CONFIG_STUDIO: "1" }, async open() { return session; },
    managed: { ensure: async () => ({ ok: false, error: "unused" }), release: async () => ({ ok: true, action: "not_held" }), snapshot: async () => null, restore: async () => ({ ok: true }) },
    jar: { install: async () => ({ ok: false, error: "unused" }), remove: async () => ({ ok: true }) },
  };
  const r = await deliverConfig("flight", { projectId: "cp0000000000000000r23f", revisionId: "rev1", pluginName: "FrostMobs", spec: SPEC, values: { ...defaultsOf(SPEC), ...values } as never, changed }, host);
  const delivered = readFileSync(path.join(root, "opt/mc/plugins/FrostMobs/config.yml"), "utf8");
  const bad = await deliverConfig("flight", { projectId: "cp0000000000000000r23f", revisionId: "rev1", pluginName: "FrostMobs", spec: SPEC, values: { ...defaultsOf(SPEC), [P + "max_health"]: 5000 } as never, changed: [P + "max_health"] }, host);
  rmSync(root, { recursive: true, force: true });
  return { result: { outcome: r.outcome, ok: r.ok, apply: r.apply, steps: r.steps.map((s) => `${s.step}:${s.status}${s.detail ? ` (${s.detail.slice(0, 140)})` : ""}`), notes: r.notes }, issued, delivered, badValue: { outcome: bad.outcome, error: bad.error } };
}

function healthFrom(report: Awaited<ReturnType<typeof fly>>["report"]): HealthReport {
  const c = (id: string) => report.checks.find((x) => x.id === id);
  const enabled = (c("plugins_enabled")?.evidence ?? []).map((l) => /^(\S+): enabled/.exec(l)?.[1]).filter((n): n is string => !!n);
  return { real: true, cameUp: c("boot_done")?.status === "pass", answered: c("rcon_checks")?.status === "pass", pluginsEnabled: enabled, errorLines: c("startup_log_clean")?.status === "fail" ? (c("startup_log_clean")?.evidence ?? []).slice(0, 5) : [], datapacksLoaded: [], evidence: (c("boot_done")?.evidence ?? []).slice(0, 2) };
}
const checksOf = (r: Awaited<ReturnType<typeof fly>>) => r.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 40) }));
const attr = (a: string) => `attribute @e[type=minecraft:zombie,tag=cyrus_frost,limit=1,sort=nearest] minecraft:${a} base get`;

async function main() {
  const oi = process.argv.indexOf("--out");
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", what: "Cyrus Config Studio: mob stats via config, studio values-only save, deliverConfig, live /reload, bad values", realClient: false, aiModel: "none (hand-written fixture mod + the mob template schema)", schemaKeys: SPEC.params.map((p) => p.key), lanes: [] as unknown[] };
  mkdirSync(RUN, { recursive: true });
  const defaultYml = renderConfigYml(SPEC, defaultsOf(SPEC), ["FrostMobs configuration (generated by Cyrus from the settings schema)."]);
  res.defaultConfigYml = defaultYml;
  const NEW = { [P + "max_health"]: 60, [P + "move_speed"]: 0.3, [P + "attack_damage"]: 7, [P + "scale"]: 1.5 };
  for (const lane of LANES) {
    const L: Record<string, unknown> = { version: lane.version, jdk: lane.release };
    (res.lanes as unknown[]).push(L);
    try {
      const b = build(lane, defaultYml);
      L.build = { javacWarnings: b.javacWarnings, sources: b.sources, jarSha256: b.jarSha256, verify: b.verify };
      console.log(`${lane.version}: javac ok (${b.javacWarnings} warnings), verify read=${b.verify.read}/${SPEC.params.length}`);
      // flight A: baseline
      const base: RconCheck[] = [
        { id: "plugins", command: "plugins", expect: ["FrostMobs"] },
        { id: "difficulty", command: "difficulty easy", required: false },
        { id: "spawn", command: "frostmobs spawn", expect: ["spawned frost zombie 1"] },
        { id: "stats-defaults", command: "frostmobs stats", expect: ["frost zombies: 1", "stats health=20.0 speed=0.23 damage=3.0 scale=1.0 armor=0.0 hp=20.0"] },
        { id: "vanilla-max-health-default", command: attr("max_health"), expect: ["20"] },
      ];
      const fa = await fly({ version: lane.version, plugins: [{ localPath: b.jarPath, sha256: b.jarSha256 }], rcon: base, timeouts: { bootSec: 240, totalSec: 480 } }, `flight A ${lane.version}`);
      L.flightA = { overall: fa.summary.overall, line: describeSummary(fa.summary), bootMs: fa.report.bootMs, paper: fa.report.engine?.paper ?? null, jdk: fa.report.engine?.jdk?.version ?? null, checks: checksOf(fa) };
      console.log(`flight A ${lane.version}: ${describeSummary(fa.summary)}`);
      // studio path
      const st = studio(defaultYml);
      const bad = await saveConfigValues(st.deps, { userId: "owner", rootBuildId: "b-r23", values: { [P + "max_health"]: 5000 }, expectedHeadId: null }).then(() => "saved (WRONG)").catch((e: { code?: string; message?: string }) => `${e.code}: ${e.message}`);
      const pv = await previewConfig(st.deps, "owner", "b-r23", NEW);
      const saved = await saveConfigValues(st.deps, { userId: "owner", rootBuildId: "b-r23", values: NEW, expectedHeadId: null });
      L.studio = { badValueRefused: bad, preview: { applies: pv.applies, written: pv.written }, save: { revisionId: saved.revisionId, seq: saved.seq, kind: st.revs[0]?.kind, applies: saved.applies, patch: saved.patch, warnings: saved.warnings.map((w) => w.message) }, configYmlChangedLines: saved.configYml.split("\n").filter((l, i) => l !== defaultYml.split("\n")[i]) };
      const d = await deliver(lane, b.jarPath, defaultYml, NEW, saved.patch.map((p) => p.key), healthFrom(fa.report));
      L.delivery = { ...d.result, issued: d.issued, deliveredEqualsStudio: d.delivered === saved.configYml, badValue: d.badValue, readBack: readValues(SPEC, d.delivered).values };
      console.log(`deliverConfig ${lane.version}: ${d.result.outcome}; issued ${d.issued.join(", ")}`);
      // flight B: old config -> delivered config + the issued reload on the live server -> new values; then a bad file
      const badYml = d.delivered.replace(/max_health: 60\.0/, "max_health: 5000.0").replace(/move_speed: 0\.3/, 'move_speed: "fast"');
      const reloadCmd = d.issued[0] ?? "frostmobs reload";
      const rc: RconCheck[] = [
        { id: "plugins", command: "plugins", expect: ["FrostMobs"] },
        { id: "difficulty", command: "difficulty easy", required: false },
        { id: "spawn-before", command: "frostmobs spawn", expect: ["spawned frost zombie 1"] },
        { id: "stats-before", command: "frostmobs stats", expect: ["stats health=20.0 speed=0.23 damage=3.0 scale=1.0"] },
        { id: "deliver-and-reload", writeFile: { path: "plugins/FrostMobs/config.yml", content: d.delivered }, command: reloadCmd, expect: ["FrostMobs config reloaded (1 frost zombies updated)"], expectNot: ["clamped", "not a number", "Unknown"] },
        { id: "stats-after-reload", command: "frostmobs stats", expect: ["stats health=60.0 speed=0.3 damage=7.0 scale=1.5 armor=0.0 hp=60.0"] },
        { id: "vanilla-max-health", command: attr("max_health"), expect: ["60"] },
        { id: "vanilla-movement-speed", command: attr("movement_speed"), expect: ["0.3"] },
        { id: "vanilla-scale", command: attr("scale"), expect: ["1.5"] },
        { id: "vanilla-attack-damage", command: attr("attack_damage"), expect: ["7"] },
        { id: "spawn-after", command: "frostmobs spawn", expect: ["spawned frost zombie 2"] },
        { id: "stats-new-zombie", command: "frostmobs stats", expect: ["frost zombies: 2"], expectNot: ["health=20.0"] },
        { id: "bad-file-clamped", writeFile: { path: "plugins/FrostMobs/config.yml", content: badYml }, command: "frostmobs reload", expect: ["FrostMobs config reloaded (2 frost zombies updated)", `clamped ${P}max_health 5000.0 -> 1024.0`, `${P}move_speed is not a number; using 0.23`] },
        { id: "stats-after-bad-file", command: "frostmobs stats", expect: ["stats health=1024.0 speed=0.23 damage=7.0 scale=1.5"] },
      ];
      const fb = await fly({ version: lane.version, plugins: [{ localPath: b.jarPath, sha256: b.jarSha256 }], files: [{ path: "plugins/FrostMobs/config.yml", content: defaultYml }], rcon: rc, timeouts: { bootSec: 240, totalSec: 600 } }, `flight B ${lane.version}`);
      L.flightB = { overall: fb.summary.overall, line: describeSummary(fb.summary), bootMs: fb.report.bootMs, peakRssMb: fb.report.peakRssKb ? Math.round(fb.report.peakRssKb / 1024) : null, paper: fb.report.engine?.paper ?? null, jdk: fb.report.engine?.jdk?.version ?? null, checks: checksOf(fb) };
      console.log(`flight B ${lane.version}: ${describeSummary(fb.summary)}`);
    } catch (e) { L.error = String((e as Error).message ?? e).slice(0, 4000); console.error(L.error); }
  }
  res.leftovers = { runsDir: readdirSync(path.join(TF, "runs")).length };
  if (oi > 0) { mkdirSync(path.dirname(process.argv[oi + 1]), { recursive: true }); writeFileSync(process.argv[oi + 1], JSON.stringify(res, null, 1)); }
  console.log(JSON.stringify(res, null, 1).slice(0, 6000));
  rmSync(RUN, { recursive: true, force: true });
}

main().catch((e) => { console.error(e); process.exit(1); });

