content.content:
/* Cyrus studios (R1b): Texture Studio, Sound Studio shell, locked states, the mod Assets tab, the Library browser.
   Ported from the approved mockups (/root/agent-notes/cyrus-designs/src/common.css + texture/locked/mod-assets),
   which copy the v5 tokens of app/dashboard/cyrus/studio.css. Everything hangs off .cys inside .cyrus-root and every
   class is cys-* (the portal's globals also define .glass / .btn / .kbd ...). One accent (violet); cyan only means
   "live"; green/amber/red only mean pass/warn/fail. Light theme follows the portal toggle (html[data-theme=light]). */

.cyrus-root .cys {
  --line-3: rgb(167 139 250 / 0.4);
  --accent-solid: #7c4dff; --on-accent: #fff;
  --accent-soft: rgb(167 139 250 / 0.14); --accent-line: rgb(167 139 250 / 0.5);
  --ok: #34e3a2; --warn: #ffb44f; --bad: #ff6b8a;
  --ok-soft: rgb(52 227 162 / 0.1); --warn-soft: rgb(255 180 79 / 0.1); --bad-soft: rgb(255 90 130 / 0.1);
  --pop-shadow: 0 26px 70px -20px rgb(0 0 0 / 0.9), 0 0 0 1px rgb(150 160 255 / 0.14);
  --check-a: #2b2545; --check-b: #221d3a; --well: rgb(7 4 18 / 0.55);
  --mono: var(--font-jb), ui-monospace, monospace; --display: var(--font-space), var(--font-inter), sans-serif;
  --r-sm: 7px; --r: 10px; --r-md: 12px; --r-lg: 16px; --r-xl: 20px;
  position: absolute; inset: 0; display: flex; flex-direction: column; min-width: 0; overflow: hidden; isolation: isolate;
  color: var(--ink); font-size: 13px; line-height: 1.45; font-feature-settings: "ss01", "cv11";
}
html[data-theme="light"] .cyrus-root .cys {
  --line-3: rgb(91 33 182 / 0.32);
  --accent-solid: #7c3aed; --accent-soft: rgb(109 61 240 / 0.09); --accent-line: rgb(109 61 240 / 0.4);
  --ok: #047a52; --warn: #8a4b00; --bad: #c8204f;
  --ok-soft: rgb(4 122 82 / 0.08); --warn-soft: rgb(196 110 0 / 0.08); --bad-soft: rgb(200 32 79 / 0.07);
  --pop-shadow: 0 24px 60px -20px rgb(20 22 60 / 0.3), 0 0 0 1px rgb(30 36 90 / 0.1);
  --check-a: #ece8f6; --check-b: #f8f6fd; --well: #f6f3fd;
}
/* deep space: a faint aurora curtain + sparse stars (the mockup's .cyrus::before) */
.cyrus-root .cys::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(1px 1px at 12% 18%, rgb(255 255 255 / .55), transparent 60%), radial-gradient(1px 1px at 78% 12%, rgb(255 255 255 / .4), transparent 60%),
    radial-gradient(1px 1px at 64% 72%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 28% 84%, rgb(255 255 255 / .3), transparent 60%),
    radial-gradient(1px 1px at 91% 58%, rgb(255 255 255 / .35), transparent 60%), radial-gradient(1px 1px at 44% 30%, rgb(255 255 255 / .25), transparent 60%),
    linear-gradient(118deg, transparent 8%, rgb(40 200 170 / .07) 18%, transparent 28%, transparent 62%, rgb(124 77 255 / .07) 74%, transparent 86%),
    radial-gradient(120% 70% at 50% -10%, rgb(60 30 130 / .35), transparent 60%), var(--bg); }
html[data-theme="light"] .cyrus-root .cys::before { background: linear-gradient(118deg, transparent 8%, rgb(8 145 178 / .05) 18%, transparent 30%, transparent 60%, rgb(124 58 237 / .06) 74%, transparent 88%), radial-gradient(120% 70% at 50% -10%, rgb(124 58 237 / .07), transparent 60%), var(--bg); }
.cys :where(button, input, select, textarea) { font: inherit; color: inherit; }
.cys :where(button) { cursor: pointer; background: none; border: 0; padding: 0; text-align: inherit; }
.cys :where(a) { color: inherit; text-decoration: none; }
.cys :focus-visible { outline: 2px solid var(--accent-ink); outline-offset: 2px; border-radius: 6px; }
.cys * { scrollbar-width: thin; scrollbar-color: rgb(var(--glow) / .28) transparent; }
.cys .mono { font-family: var(--mono); }
.cys svg.cys-i { width: 1em; height: 1em; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }

/* surfaces */
.cys .cys-glass { background: linear-gradient(180deg, var(--surface-2), var(--surface)); backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%); border: 1px solid var(--line); box-shadow: var(--panel-shadow); }
.cys .cys-soft { background: var(--surface-soft); border: 1px solid var(--line); }
.cys .cys-hairline { position: relative; }
.cys .cys-hairline::before { content: ""; position: absolute; inset: 0 12% auto 12%; height: 1px; pointer-events: none; background: linear-gradient(90deg, transparent, rgb(var(--glow) / .55), rgb(103 232 249 / .4), transparent); }
html[data-theme="light"] .cyrus-root .cys .cys-hairline::before { background: linear-gradient(90deg, transparent, rgb(124 58 237 / .3), rgb(8 145 178 / .25), transparent); }
.cys .cys-panel { border-radius: var(--r-lg); min-height: 0; display: flex; flex-direction: column; }
.cys .cys-ph { display: flex; align-items: center; gap: 8px; padding: 12px 14px 8px; }
.cys .cys-eyebrow { font: 600 10px/1 var(--mono); letter-spacing: .2em; text-transform: uppercase; color: var(--muted); }
.cys .cys-ph .cys-eyebrow { flex: 1; }
.cys .cys-sep { height: 1px; background: var(--line); margin: 4px 0; }
.cys .cys-hint { font-size: 11.5px; color: var(--muted); line-height: 1.45; }

/* top bar (TopBar.tsx anatomy) */
.cys .cys-top { height: 60px; flex: none; display: flex; align-items: center; gap: 12px; padding: 0 16px 0 18px; position: relative; z-index: 5; }
.cys .cys-brand { display: flex; flex-direction: column; line-height: 1; }
.cys .cys-brand small { margin-top: 4px; font: 600 8px/1 var(--font-inter), sans-serif; letter-spacing: .36em; text-transform: uppercase; color: var(--muted); }
.cys .cys-crumbs { display: flex; align-items: center; gap: 2px; padding: 4px; border-radius: 12px; margin-left: 10px; min-width: 0; }
.cys .cys-crumb { display: flex; align-items: center; gap: 6px; padding: 4px 8px; border-radius: 8px; font-size: 12.5px; color: var(--muted); white-space: nowrap; }
.cys a.cys-crumb:hover { color: var(--ink); background: rgb(var(--glow) / .07); }
