/* Cyrus Config and Stats Studio mockup (v5). Uses the shared studio kit (../../src/common.css): one accent (violet),
   cyan only for "live" (the preview clock), ok/warn/bad only for checks. */
.ws { flex: 1; min-height: 0; display: grid; grid-template-columns: 220px minmax(0, 1fr) 360px; gap: 14px; padding: 0 16px 16px; }
.rail-g { border-radius: 18px; padding: 10px; display: flex; flex-direction: column; gap: 2px; min-height: 0; overflow: auto; }
.rail-g .g { display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 10px; font-size: 13px; color: var(--ink-2); }
.rail-g .g:hover { background: rgb(var(--glow) / .07); color: var(--ink); }
.rail-g .g.on { background: rgb(var(--glow) / .14); color: var(--ink); box-shadow: inset 0 0 0 1px rgb(var(--glow) / .25); }
.rail-g .g .n { margin-left: auto; font: 500 10.5px/1 var(--mono); color: var(--muted); }
.rail-g .g .ch { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 6px var(--accent); }
.rail-g .legend { margin-top: auto; padding: 10px; border-top: 1px solid var(--line); display: flex; flex-direction: column; gap: 7px; font-size: 11.5px; color: var(--muted); }
.form { border-radius: 20px; display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.fh { display: flex; align-items: center; gap: 10px; padding: 14px 16px 10px; flex-wrap: wrap; }
.fh h1 { margin: 0; font: 600 18px/1 var(--display); letter-spacing: -.01em; }
.fh .sp { flex: 1; }
.fh .search { position: relative; width: 220px; }
.fh .search svg { position: absolute; left: 10px; top: 9px; color: var(--muted); font-size: 14px; }
.fh .search input { padding-left: 30px; }
.bar2 { display: flex; align-items: center; gap: 8px; padding: 0 16px 12px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.rows { overflow: auto; padding: 6px 16px 16px; display: flex; flex-direction: column; gap: 4px; }
.gh { display: flex; align-items: baseline; gap: 8px; padding: 14px 2px 6px; }
.gh h2 { margin: 0; font: 600 13px/1 var(--display); }
.gh span { font-size: 11.5px; color: var(--muted); }
.row { display: grid; grid-template-columns: minmax(170px, 1.1fr) minmax(220px, 1.6fr) auto; gap: 14px; align-items: center; padding: 10px 12px; border-radius: 12px; border: 1px solid transparent; }
.row:hover { background: rgb(var(--glow) / .04); border-color: var(--line); }
.row.changed { background: rgb(var(--glow) / .06); border-color: rgb(var(--glow) / .22); }
.row .lb b { display: flex; align-items: center; gap: 7px; font-weight: 500; font-size: 13px; }
.row .lb small { display: block; color: var(--muted); font-size: 11.5px; margin-top: 3px; line-height: 1.4; }
.row .lb .k { font: 500 10px/1 var(--mono); color: var(--faint); margin-top: 5px; display: block; }
.ctl { display: flex; align-items: center; gap: 10px; min-width: 0; }
.ctl input[type=range] { flex: 1; accent-color: var(--accent-solid); min-width: 80px; }
.ctl .num { width: 92px; display: flex; align-items: center; border: 1px solid var(--line-2); border-radius: 10px; background: var(--well); height: 32px; }
.ctl .num input { width: 100%; background: none; border: 0; outline: 0; padding: 0 8px; font: 500 12.5px/1 var(--mono); color: var(--ink); }
.ctl .num span { padding-right: 8px; font-size: 11px; color: var(--muted); white-space: nowrap; }
.track { position: relative; flex: 1; height: 26px; }
.track input { position: absolute; inset: 0; width: 100%; margin: 0; }
.track .safe { position: absolute; top: 11px; height: 4px; border-radius: 3px; background: color-mix(in srgb, var(--ok) 35%, transparent); pointer-events: none; }
.right { display: flex; align-items: center; gap: 6px; justify-content: flex-end; }
.warnrow { grid-column: 1 / -1; display: flex; gap: 8px; align-items: flex-start; padding: 8px 10px; border-radius: 9px; font-size: 12px; color: var(--warn); background: var(--warn-soft); border: 1px solid color-mix(in srgb, var(--warn) 30%, transparent); }
.warnrow svg { flex: none; margin-top: 2px; }
.tog { width: 38px; height: 22px; border-radius: 999px; background: var(--surface-3); border: 1px solid var(--line-2); position: relative; }
.tog::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--muted); transition: .2s; }
.tog.on { background: var(--accent-solid); border-color: transparent; } .tog.on::after { left: 18px; background: #fff; }
.tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.tbl th { font: 600 9.5px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); text-align: left; padding: 6px; }
.tbl td { padding: 3px 4px; } .tbl td input { height: 28px; font-size: 12px; }
.listchips { display: flex; flex-wrap: wrap; gap: 6px; }
.pv { border-radius: 20px; display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.stage { position: relative; height: 300px; display: grid; place-items: end center; background: radial-gradient(circle, rgb(var(--glow) / .12) 1px, transparent 1.2px) 0 0 / 22px 22px, var(--well); border-bottom: 1px solid var(--line); overflow: hidden; }
.stage .ground { position: absolute; left: 0; right: 0; bottom: 40px; height: 1px; background: var(--line-2); }
.stage .live { position: absolute; top: 12px; left: 12px; display: flex; gap: 6px; }
.mob { position: relative; margin-bottom: 40px; transform-origin: bottom center; }
.mob .body { width: 46px; height: 60px; border-radius: 8px; background: linear-gradient(180deg, #6ee7b7, #2f855a); box-shadow: inset 0 -6px 0 rgb(0 0 0 / .2); position: relative; }
.mob .head { width: 44px; height: 40px; border-radius: 8px; background: linear-gradient(180deg, #9ae6b4, #38a169); margin: 0 auto 4px; position: relative; }
.mob .head::before, .mob .head::after { content: ""; position: absolute; top: 15px; width: 8px; height: 6px; background: #0b1f15; border-radius: 2px; }
.mob .head::before { left: 9px; } .mob .head::after { right: 9px; }
.mob .arm { position: absolute; top: 50px; width: 14px; height: 52px; border-radius: 6px; background: #48bb78; transform-origin: top center; }
.mob .arm.l { left: -14px; } .mob .arm.r { right: -14px; }
.mob .leg { position: absolute; bottom: -46px; width: 18px; height: 46px; border-radius: 5px; background: #2b6cb0; transform-origin: top center; animation: walk var(--walk, 1s) ease-in-out infinite alternate; }
.mob .leg.l { left: 4px; } .mob .leg.r { right: 4px; animation-direction: alternate-reverse; }
.mob .arm { animation: swing var(--atk, 1s) ease-in-out infinite alternate; }
@keyframes walk { from { transform: rotate(-24deg); } to { transform: rotate(24deg); } }
@keyframes swing { from { transform: rotate(-70deg); } to { transform: rotate(-95deg); } }
.gunv { margin-bottom: 120px; position: relative; width: 220px; height: 70px; }
.gunv .rcv { position: absolute; left: 40px; top: 18px; width: 150px; height: 26px; border-radius: 6px; background: linear-gradient(180deg, #4a4f63, #2b2e3b); }
.gunv .brl { position: absolute; left: 186px; top: 24px; width: 40px; height: 9px; border-radius: 3px; background: #23252f; }
.gunv .mag { position: absolute; left: 100px; top: 40px; width: 22px; height: 38px; border-radius: 3px; background: #3a3f52; transform-origin: top center; animation: mag var(--rel, 2.5s) ease-in-out infinite; }
.gunv .stk { position: absolute; left: 0; top: 22px; width: 46px; height: 22px; border-radius: 6px 3px 3px 10px; background: #5b4636; }
.gunv .flash { position: absolute; left: 224px; top: 14px; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, #fff7c2, #ffb44f 45%, transparent 70%); opacity: 0; animation: flash var(--fire, .1s) steps(1) infinite; }
@keyframes mag { 0%, 60% { transform: translateY(0); } 70%, 85% { transform: translateY(46px); opacity: .2; } 100% { transform: translateY(0); } }
@keyframes flash { 0% { opacity: 1; } 40% { opacity: 0; } }
.readout { padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
.readout .r { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
.readout .r b { margin-left: auto; font: 500 12px/1 var(--mono); }
.readout .r .meter { width: 90px; height: 5px; border-radius: 3px; background: var(--surface-3); overflow: hidden; }
.readout .r .meter i { display: block; height: 100%; background: var(--cyan); }
.clockbar { display: flex; align-items: center; gap: 8px; padding: 10px 14px; border-top: 1px solid var(--line); }
.drawer { position: absolute; left: 236px; right: 392px; bottom: 16px; border-radius: 18px; z-index: 20; max-height: 56%; display: flex; flex-direction: column; overflow: hidden; }
.drawer .dh { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--line); }
.drawer .dh h3 { margin: 0; font: 600 14px/1 var(--display); }
.drawer .db { display: grid; grid-template-columns: 1fr 1fr; gap: 0; min-height: 0; overflow: auto; }
.drawer .changes { padding: 10px 16px; display: flex; flex-direction: column; gap: 6px; border-right: 1px solid var(--line); }
.drawer .ci { display: grid; grid-template-columns: 1fr auto auto auto; gap: 8px; align-items: center; font-size: 12.5px; }
.drawer .ci .from { color: var(--muted); text-decoration: line-through; font-family: var(--mono); font-size: 11.5px; }
.drawer .ci .to { font-family: var(--mono); font-size: 11.5px; color: var(--accent-ink); }
.drawer pre { margin: 0; padding: 10px 16px; font: 11.5px/1.6 var(--mono); color: var(--ink-2); white-space: pre-wrap; }
.drawer pre .add { color: var(--ok); } .drawer pre .del { color: var(--bad); } .drawer pre .cm { color: var(--faint); }
.drawer .df { display: flex; align-items: center; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--line); }
.cmdbox { display: flex; gap: 8px; padding: 10px 16px; border-top: 1px solid var(--line); align-items: center; }
.cmdbox input { flex: 1; }
.ro-banner { display: none; }
@media (max-width: 1180px) { .ws { grid-template-columns: 200px minmax(0, 1fr); } .pv { grid-column: 1 / -1; } .drawer { left: 16px; right: 16px; } }
@media (max-width: 760px) {
  .ws { display: flex; flex-direction: column; padding: 0 10px 80px; }
  .rail-g { flex-direction: row; overflow-x: auto; padding: 6px; border-radius: 14px; } .rail-g .legend { display: none; } .rail-g .g { white-space: nowrap; }
  .row { grid-template-columns: 1fr; gap: 8px; } .right { justify-content: flex-start; }
  .fh .search { width: 100%; } .stage { height: 220px; }
  .ro-banner { display: flex; gap: 8px; align-items: center; margin: 0 16px 10px; padding: 10px 12px; border-radius: 12px; font-size: 12px; color: var(--ink-2); background: var(--accent-soft); border: 1px solid var(--accent-line); }
  .drawer { position: static; margin: 0 0 14px; } .drawer .db { grid-template-columns: 1fr; }
  .cmdbox, .save-only { display: none !important; }
}

