// Cyrus Config and Stats Studio mockup: renders a ConfigSpec (the real template data, abbreviated) as the generated
// form. MODE "mob" = a creature mod (preview walks at the speed stat); MODE "gun" = a weapon mod with the diff drawer.
(function () {
  const MODE = window.MODE;
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
  const SPECS = {
    mob: {
      title: "Frost Zombies", source: "Declared by Cyrus", reload: "/frostmobs reload", cat: "Creatures",
      groups: [["stats", "Stats", "How tough and fast the frost zombie is"], ["combat", "Combat", "How hard it hits"], ["drops", "Drops", "What it leaves behind"], ["spawning", "Spawning", "Where and how often it appears"]],
      params: [
        { k: "mobs.frost_zombie.max_health", g: "stats", t: "number", l: "Max health", h: "A diamond sword deals about 7 per hit.", d: 20, v: 60, u: "hp", min: 1, max: 1024, step: 1, safe: [4, 200], a: "reload" },
        { k: "mobs.frost_zombie.move_speed", g: "stats", t: "number", l: "Movement speed", h: "Zombie 0.23, player 0.1. Drives the walk clip.", d: 0.23, v: 0.3, u: "", min: 0, max: 1, step: 0.01, safe: [0.1, 0.4], a: "reload", vis: "walk" },
        { k: "mobs.frost_zombie.armor", g: "stats", t: "number", l: "Armor", d: 0, v: 0, min: 0, max: 30, step: 1, safe: [0, 20], a: "reload" },
        { k: "mobs.frost_zombie.scale", g: "stats", t: "number", l: "Size", h: "Big mobs get stuck in caves and doors.", d: 1, v: 1.5, u: "x", min: 0.1, max: 8, step: 0.05, safe: [0.5, 3], a: "reload", vis: "scale" },
        { k: "mobs.frost_zombie.attack_damage", g: "combat", t: "number", l: "Attack damage", h: "A player has 20 health.", d: 3, v: 26, u: "hp", min: 0, max: 100, step: 0.5, safe: [1, 20], a: "reload" },
        { k: "mobs.frost_zombie.attack_interval", g: "combat", t: "duration", l: "Time between attacks", d: 1, v: 1, u: "s", min: 0.05, max: 10, step: 0.05, safe: [0.5, 3], a: "reload", vis: "attack" },
        { k: "mobs.frost_zombie.burns_in_daylight", g: "combat", t: "bool", l: "Burns in daylight", d: false, v: false, a: "reload" },
        { k: "mobs.frost_zombie.drops", g: "drops", t: "table", l: "Drops", d: null, v: [["minecraft:packed_ice", "0.5", "1", "2"], ["minecraft:diamond", "0.02", "1", "1"]], cols: ["Item", "Chance", "Min", "Max"], a: "reload" },
        { k: "mobs.frost_zombie.spawn_weight", g: "spawning", t: "int", l: "Spawn weight", h: "Zombies are 100; 0 turns natural spawning off.", d: 10, v: 10, min: 0, max: 1000, step: 1, safe: [1, 100], a: "restart" },
        { k: "mobs.frost_zombie.biomes", g: "spawning", t: "list", l: "Spawn biomes", d: null, v: ["snowy_plains", "ice_spikes", "frozen_peaks"], a: "restart" },
      ],
      presets: ["Easy", "Normal", "Hard", "Custom"], preset: "Custom",
    },
    gun: {
      title: "Tactical Arsenal", source: "Declared by Cyrus", reload: "/arsenal reload", cat: "Weapons",
      groups: [["damage", "Damage", ""], ["firing", "Firing", ""], ["ammo", "Ammo", ""], ["handling", "Handling", ""], ["sounds", "Sounds", ""]],
      params: [
        { k: "guns.ak47.damage", g: "damage", t: "number", l: "Damage per hit", d: 6, v: 6, u: "hp", min: 0, max: 100, step: 0.5, safe: [2, 20], a: "reload" },
        { k: "guns.ak47.headshot_multiplier", g: "damage", t: "number", l: "Headshot multiplier", d: 2, v: 2, u: "x", min: 1, max: 10, step: 0.1, safe: [1, 3], a: "reload" },
        { k: "guns.ak47.fire_rate", g: "firing", t: "int", l: "Fire rate", h: "Above 1200 rpm the game cannot keep up (one shot per tick).", d: 600, v: 750, u: "rpm", min: 1, max: 1200, step: 10, safe: [40, 900], a: "reload", vis: "fire" },
        { k: "guns.ak47.fire_mode", g: "firing", t: "enum", l: "Fire mode", d: "auto", v: "auto", opts: ["semi", "burst", "auto"], a: "reload" },
        { k: "guns.ak47.magazine_size", g: "ammo", t: "int", l: "Magazine size", d: 30, v: 40, u: "rounds", min: 1, max: 500, step: 1, safe: [1, 100], a: "reload" },
        { k: "guns.ak47.reload_time", g: "ammo", t: "duration", l: "Reload time", h: "Drives the reload clip.", d: 2.5, v: 2, u: "s", min: 0.05, max: 20, step: 0.05, safe: [0.5, 5], a: "reload", vis: "reload" },
        { k: "guns.ak47.spread", g: "handling", t: "number", l: "Spread", d: 2, v: 2, u: "deg", min: 0, max: 45, step: 0.1, safe: [0, 10], a: "reload" },
        { k: "guns.ak47.recoil", g: "handling", t: "number", l: "Recoil", d: 1.5, v: 1.5, u: "deg", min: 0, max: 20, step: 0.1, safe: [0, 6], a: "reload" },
        { k: "guns.ak47.fire_sound", g: "sounds", t: "sound", l: "Fire sound", d: "minecraft:entity.firework_rocket.blast", v: "nx_ak9f2c11:ak47.fire", a: "reload" },
      ],
      presets: ["Easy", "Normal", "Hard", "Custom"], preset: "Custom",
    },
  };
  const S = SPECS[MODE];
  const changed = (p) => JSON.stringify(p.v) !== JSON.stringify(p.d) && p.d !== null;
  const APPL = { live: ["Live", "ok", "Takes effect at once"], reload: ["Reload", "acc", `Takes effect with ${S.reload}`], restart: ["Restart", "warn", "Takes effect after a server restart"] };
  const badge = (a) => `<span class="tag ${APPL[a][1]}" title="${APPL[a][2]}">${a === "restart" ? I("server") : a === "reload" ? I("restore") : I("check")}${APPL[a][0]}</span>`;
  const unbal = (p) => p.safe && typeof p.v === "number" && (p.v < p.safe[0] || p.v > p.safe[1]);
  function control(p) {
    if (p.t === "bool") return `<div class="ctl"><span class="tog ${p.v ? "on" : ""}" role="switch" aria-checked="${p.v}"></span><span class="hint">${p.v ? "On" : "Off"}</span></div>`;
    if (p.t === "enum") return `<div class="ctl"><div class="seg sm glass-soft">${p.opts.map((o) => `<button class="${o === p.v ? "on" : ""}">${o}</button>`).join("")}</div></div>`;
    if (p.t === "sound") return `<div class="ctl"><button class="btn sm" aria-label="Play">${I("play")}</button><input class="field mono" value="${esc(p.v)}"><button class="btn sm">${I("library")}Pick</button></div>`;
    if (p.t === "list") return `<div class="ctl"><div class="listchips">${p.v.map((x) => `<span class="fchip">${esc(x)} ${I("close")}</span>`).join("")}<span class="fchip">${I("plus")}Add</span></div></div>`;
    if (p.t === "table") return `<div class="ctl"><table class="tbl"><tr>${p.cols.map((c) => `<th>${c}</th>`).join("")}<th></th></tr>${p.v.map((r) => `<tr>${r.map((c, i) => `<td><input class="field ${i ? "mono" : ""}" value="${esc(c)}"></td>`).join("")}<td><button class="ib sm">${I("close")}</button></td></tr>`).join("")}<tr><td colspan="5"><button class="btn xs">${I("plus")}Add a row</button></td></tr></table></div>`;
    const pct = (x) => ((x - p.min) / (p.max - p.min)) * 100;
    const safe = p.safe ? `<span class="safe" style="left:${pct(p.safe[0])}%;width:${pct(p.safe[1]) - pct(p.safe[0])}%"></span>` : "";
    return `<div class="ctl"><div class="track">${safe}<input type="range" min="${p.min}" max="${p.max}" step="${p.step}" value="${p.v}" data-k="${p.k}" aria-label="${esc(p.l)}"></div><label class="num"><input value="${p.v}" data-n="${p.k}" aria-label="${esc(p.l)} value"><span>${p.u || ""}</span></label></div>`;
  }
  function row(p) {
    const w = unbal(p) ? `<div class="warnrow">${I("warn")}<span>${esc(p.l)} ${p.v}${p.u ? " " + p.u : ""} is ${p.v > p.safe[1] ? "above" : "below"} the balanced range (${p.safe[0]}-${p.safe[1]}${p.u ? " " + p.u : ""}). ${p.k.endsWith("attack_damage") ? "Two hits kill a player in full iron armor." : "It still saves; players may find it unfair."}</span></div>` : "";
    return `<div class="row ${changed(p) ? "changed" : ""}" data-row="${p.k}"><div class="lb"><b>${esc(p.l)}${p.vis ? `<span class="tag dim" title="Plays in the preview">${I("eye")}preview</span>` : ""}</b>${p.h ? `<small>${esc(p.h)}</small>` : ""}<span class="k">${p.k}</span></div>${control(p)}<div class="right">${badge(p.a)}<button class="ib sm" title="Reset to ${p.d}" ${changed(p) ? "" : "disabled"}>${I("restore")}</button></div>${w}</div>`;
  }
  function render() {
    const q = new URLSearchParams(location.search);
    const search = q.get("search") || "";
    const ps = S.params.filter((p) => !search || (p.l + p.k).toLowerCase().includes(search));
    const nChanged = S.params.filter(changed).length;
    $("rail").outerHTML = rail();
    $("top").outerHTML = topbar(`<a class="crumb" href="#"><span class="dot" style="background:#f472b6;box-shadow:0 0 8px #f472b6"></span>${S.title}</a>${I("chevR")}<span class="crumb on">${I("gauge")}Config</span>`, `<div class="seg glass-soft hide-n"><a>${I("image")}Texture</a><a>${I("wave")}Sound</a><a>${I("cube")}Model</a><a class="on">${I("gauge")}Config</a></div><a class="chip glass-soft hide-n">${I("package")}Mod assets</a>`);
    $("groups").innerHTML = S.groups.map(([id, label], i) => `<a class="g ${i === 0 ? "on" : ""}">${esc(label)}${S.params.some((p) => p.g === id && changed(p)) ? '<span class="ch"></span>' : ""}<span class="n">${S.params.filter((p) => p.g === id).length}</span></a>`).join("") +
      `<div class="legend"><span class="eyebrow">How changes apply</span>${badge("reload")}<span>${esc(S.reload)}, no restart</span>${badge("restart")}<span>Needs a server restart</span></div>`;
    $("fh").innerHTML = `<h1>Config and stats</h1><span class="tag ok">${I("check")}${S.source}</span><span class="sp"></span><label class="search"><span>${I("search")}</span><input class="field" placeholder="Search settings" value="${esc(search)}"></label>`;
    $("bar2").innerHTML = `<span class="eyebrow">Preset</span><div class="seg sm glass-soft">${S.presets.map((x) => `<button class="${x === S.preset ? "on" : ""}">${x}</button>`).join("")}</div><span class="sp" style="flex:1"></span>
      <span class="tag acc">${nChanged} changed</span><button class="btn sm ghost">${I("restore")}Reset all</button><button class="btn sm" id="diffBtn">${I("split")}Review changes</button><button class="btn sm primary save-only">${I("check")}Save revision</button>`;
    $("rows").innerHTML = S.groups.map(([id, label, help]) => { const rs = ps.filter((p) => p.g === id); return rs.length ? `<div class="gh"><h2>${esc(label)}</h2><span>${esc(help)}</span></div>${rs.map(row).join("")}` : ""; }).join("") || `<p class="hint" style="padding:20px">No setting matches "${esc(search)}".</p>`;
    $("cmd").innerHTML = `<span style="color:var(--accent-ink);display:flex">${I("sparkle")}</span><input class="field" placeholder='Or type it: "set movement speed to 0.3 and max health to 60"'><button class="btn sm">Apply</button><span class="hint">no AI, no tokens</span>`;
    preview();
    if (q.get("diff")) drawer();
  }
  function preview() {
    const get = (end) => S.params.find((p) => p.k.endsWith(end));
    let html = "";
    if (MODE === "mob") {
      const sp = get("move_speed").v / 0.23, sc = get("scale").v, atk = 1 / get("attack_interval").v;
      html = `<div class="stage"><div class="live"><span class="tag" style="color:var(--cyan);border-color:color-mix(in srgb,var(--cyan) 45%,transparent)"><span class="dot live"></span>live preview</span></div><div class="ground"></div>
        <div class="mob" style="--walk:${(0.5 / sp).toFixed(2)}s;--atk:${(0.6 / atk).toFixed(2)}s;transform:scale(${sc})"><div class="head"></div><div class="body"><span class="arm l"></span><span class="arm r"></span><span class="leg l"></span><span class="leg r"></span></div></div></div>
        <div class="readout"><span class="eyebrow">What the stats do to the model</span>
        <div class="r">${I("play")}Walk clip<span class="meter"><i style="width:${Math.min(100, sp * 50)}%"></i></span><b>${sp.toFixed(2)}x</b></div>
        <div class="r">${I("loop")}Attack clip<span class="meter"><i style="width:${Math.min(100, atk * 50)}%"></i></span><b>${atk.toFixed(2)}x</b></div>
        <div class="r">${I("zoomin")}Size<span class="meter"><i style="width:${Math.min(100, sc * 33)}%"></i></span><b>${sc.toFixed(2)}x</b></div>
        <p class="hint">An approximation for feel. The server is the truth: Cyrus checks every value against its limits again when it saves.</p></div>`;
    } else {
      const fr = get("fire_rate").v, rl = get("reload_time").v;
      html = `<div class="stage"><div class="live"><span class="tag" style="color:var(--cyan);border-color:color-mix(in srgb,var(--cyan) 45%,transparent)"><span class="dot live"></span>live preview</span></div><div class="ground"></div>
        <div class="gunv" style="--fire:${(60 / fr).toFixed(3)}s;--rel:${(rl + 1).toFixed(2)}s"><span class="stk"></span><span class="rcv"></span><span class="brl"></span><span class="mag"></span><span class="flash"></span></div></div>
        <div class="readout"><span class="eyebrow">What the stats do to the model</span>
        <div class="r">${I("play")}Fire clip<span class="meter"><i style="width:${Math.min(100, (fr / 600) * 50)}%"></i></span><b>${(fr / 600).toFixed(2)}x</b></div>
        <div class="r">${I("history")}Time between shots<b>${(60 / fr).toFixed(3)} s</b></div>
        <div class="r">${I("restore")}Reload clip<span class="meter"><i style="width:${Math.min(100, (2.5 / rl) * 50)}%"></i></span><b>${(2.5 / rl).toFixed(2)}x</b></div>
        <p class="hint">An approximation for feel. The server is the truth.</p></div>`;
    }
    $("pv").innerHTML = `<div class="ph"><span class="eyebrow">Preview</span><div class="seg sm glass-soft"><button class="on">${MODE === "mob" ? "Walk" : "Fire"}</button><button>${MODE === "mob" ? "Attack" : "Reload"}</button><button>Idle</button></div></div>${html}
      <div class="clockbar"><button class="ib on" aria-label="Pause">${I("pause")}</button><button class="ib" aria-label="Loop">${I("loop")}</button><span class="hint">Clock speed follows the stats</span></div>`;
  }
  function drawer() {
    const ch = S.params.filter(changed);
    const yml = ch.map((p) => { const key = p.k.split(".").pop(); return `<span class="del">-    ${key}: ${p.d}</span>\n<span class="add">+    ${key}: ${p.v}</span>`; }).join("\n");
    const d = document.createElement("div");
    d.className = "drawer glass hairline";
    d.innerHTML = `<div class="dh"><span style="color:var(--accent-ink);display:flex">${I("split")}</span><h3>Review ${ch.length} changes</h3><span class="tag acc">${I("restore")}${esc(S.reload)}</span><span class="hint">No restart, no rebuild, no tokens</span><span style="flex:1"></span><button class="ib">${I("close")}</button></div>
      <div class="db"><div class="changes"><span class="eyebrow">Settings</span>${ch.map((p) => `<div class="ci"><span>${esc(p.l)}</span><span class="from">${p.d}${p.u ? " " + p.u : ""}</span>${I("chevR")}<span class="to">${p.v}${p.u ? " " + p.u : ""}</span></div>`).join("")}
        ${ch.some(unbal) ? `<div class="warnrow" style="margin-top:6px">${I("warn")}<span>${ch.filter(unbal).length} value is outside its balanced range. You can still save it.</span></div>` : ""}</div>
      <pre><span class="cm"># config.yml: only these lines change. Comments and your own keys stay.</span>\n${yml}</pre></div>
      <div class="df"><span class="hint">Saved as revision 8. Undo any time from History.</span><span style="flex:1"></span><button class="btn sm ghost">Keep editing</button><button class="btn sm" title="Not connected yet: delivery to servers needs the owner's switch">${I("server")}Save and send to a server</button><button class="btn sm primary">${I("check")}Save revision</button></div>`;
    document.querySelector(".cyrus").appendChild(d);
  }
  window.addEventListener("DOMContentLoaded", () => {
    const q = new URLSearchParams(location.search);
    if (q.get("theme") === "light") document.documentElement.dataset.theme = "light";
    render();
  });
})();

