"use client";
// Cyrus Config and Stats Studio: the Config page of the studio shell. A form GENERATED from the mod's ConfigSpec
// (lib/cyrus/config): groups rail, search, presets, per-setting reset, balance warnings, "applies" badges, a review
// drawer (the exact config.yml lines that change, from the server's preview), Save revision (values only: no model, no
// build), undo from history, and the "just type it" box (deterministic, no AI). The preview stage runs on Model
// Studio's PlaybackClock: stats with a `visual` link (walk speed, attack speed, fire rate, reload, size) set the clock
// speed through applyToClock, so the clip plays faster or slower as the number moves. Narrow screens are read only.
// Approved mockups: /root/agent-notes/cyrus-designs/v5-config/config-mob.html + config-gun.html.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { StudioShell, useToast, type StudioMod } from "./StudioShell";
import { SI } from "./icons";
import { applyToClock, visualEffects, type VisualEffects } from "@/lib/cyrus/config/visual";
import { balanceWarnings, checkValue, fmt, fromSeconds, sameValue, toSeconds } from "@/lib/cyrus/config/values";
import type { Applies, ConfigParam, ConfigSpec, ConfigValue, ConfigValues, ScalarValue } from "@/lib/cyrus/config/spec";
import { PlaybackClock } from "@/lib/cyrus/modelstudio/clock";
import "./config-studio.css";

type View = {
  project: { id: string; namespace: string } | null; pluginName: string | null; mcVersion: string; buildId: string;
  source: "declared" | "designer" | "inferred" | "none"; spec: ConfigSpec | null; notes: string[];
  values: ConfigValues; shipped: ConfigValues; defaults: ConfigValues; changedFromDefaults: string[]; preset: string;
  headRevisionId: string | null; history: { revisionId: string; seq: number; createdAt: string; message: string | null; patch: { key: string; from: unknown; to: unknown }[] }[];
  deliveryConnected: boolean;
};
type Preview = { configYml: string; patch: { key: string; from: ConfigValue; to: ConfigValue }[]; applies: Applies | "none"; errors: { key: string; message: string }[]; warnings: { key: string; message: string }[] };

const API = "/api/cyrus/config/v1";
async function api<T>(init?: { method: "POST"; body: unknown }, q = ""): Promise<T> {
  const r = await fetch(`${API}${q}`, init ? { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(init.body) } : { cache: "no-store" });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw Object.assign(new Error((j as { error?: string }).error ?? "Something went wrong."), { status: r.status, body: j });
  return j as T;
}

const SOURCE_LABEL: Record<View["source"], string> = { declared: "Declared by Cyrus", designer: "From the item designs", inferred: "Read from config.yml", none: "No settings" };
const APPLIES: Record<Applies, { label: string; cls: string; icon: string }> = {
  live: { label: "Live", cls: "ok", icon: "check" }, reload: { label: "Reload", cls: "acc", icon: "restore" }, restart: { label: "Restart", cls: "warn", icon: "server" },
};
const numericT = (p: ConfigParam) => p.type === "number" || p.type === "int" || p.type === "duration";

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const m = window.matchMedia("(max-width: 760px)"); const f = () => setN(m.matches); f(); m.addEventListener("change", f); return () => m.removeEventListener("change", f); }, []);
  return n;
}

export function ConfigStudio({ mod, showModel = false }: { mod: StudioMod; showModel?: boolean }) {
  return (
    <StudioShell mod={mod} current="Config" studio="config" showModel={showModel} showConfig>
      <ConfigBody mod={mod} />
    </StudioShell>
  );
}

function ConfigBody({ mod }: { mod: StudioMod }) {
  const toast = useToast();
  const narrow = useNarrow();
  const [view, setView] = useState<View | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [vals, setVals] = useState<ConfigValues>({});
  const [group, setGroup] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [review, setReview] = useState<Preview | null>(null);
  const [busy, setBusy] = useState(false);
  const [cmd, setCmd] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const load = useCallback(async () => {
    try { const v = await api<View>(undefined, `?root=${encodeURIComponent(mod.rootId)}`); setView(v); setVals(v.values); setErr(null); }
    catch (e) { setErr((e as Error).message); }
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);
  const spec = view?.spec ?? null;
  const readOnly = narrow;
  const changedKeys = useMemo(() => (spec && view ? spec.params.filter((p) => !sameValue(vals[p.key], view.values[p.key])).map((p) => p.key) : []), [spec, view, vals]);
  const fx = useMemo(() => (spec ? visualEffects(spec, vals) : null), [spec, vals]);
  const set = (k: string, v: ConfigValue) => setVals((o) => ({ ...o, [k]: v }));
  const presetOn = useMemo(() => { if (!spec) return "default"; for (const pr of spec.presets) if (Object.entries(pr.values).every(([k, v]) => sameValue(vals[k], v))) return pr.id; return spec.params.every((p) => sameValue(vals[p.key], view?.defaults[p.key])) ? "default" : "custom"; }, [spec, vals, view]);

  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s settings…</div>;
  if (!spec) return (
    <main className="cfg-ws one"><section className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
      <div className="cys-empty" style={{ maxWidth: 460 }}><SI n="gauge" /><p><b>This mod has no settings Cyrus can edit yet.</b></p><p className="cys-hint">{view.notes[0] ?? "Ask Cyrus to make its numbers configurable in your next change."}</p></div>
    </section></main>
  );

  const groups = [...spec.groups].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const ql = q.trim().toLowerCase();
  const shown = spec.params.filter((p) => (!ql || `${p.label} ${p.key} ${p.help ?? ""} ${p.tags.join(" ")}`.toLowerCase().includes(ql)) && (!group || ql || p.group === group));
  const unbalanced = spec.params.filter((p) => balanceWarnings(p, vals[p.key]).length);
  const strongest = changedKeys.reduce<Applies | null>((a, k) => { const ap = spec.params.find((p) => p.key === k)!.applies; return !a || (ap === "restart" || (ap === "reload" && a === "live")) ? ap : a; }, null);

  const openReview = async () => {
    setBusy(true);
    try { setReview(await api<Preview>({ method: "POST", body: { root: mod.rootId, action: "preview", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])) } })); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const save = async () => {
    setBusy(true);
    try {
      const r = await api<{ seq: number; applies: string }>({ method: "POST", body: { root: mod.rootId, action: "save", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])), expectedHeadId: view.headRevisionId } });
      toast(`Saved as revision ${r.seq}. ${r.applies === "reload" && spec.reload ? `Takes effect with ${spec.reload.command}.` : r.applies === "restart" ? "Takes effect after a server restart." : ""}`);
      setReview(null); await load();
    } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const undo = async (revisionId: string) => {
    setBusy(true);
    try { const r = await api<{ seq: number }>({ method: "POST", body: { root: mod.rootId, action: "revert", revisionId, expectedHeadId: view.headRevisionId } }); toast(`Undone as revision ${r.seq}.`); await load(); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const runCmd = async () => {
    if (!cmd.trim()) return;
    try {
      const r = await api<{ kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] } | { kind: "model"; reason: string }>({ method: "POST", body: { root: mod.rootId, action: "plan", text: cmd } });
      if (r.kind === "values") { setVals((o) => ({ ...o, ...Object.fromEntries(r.edits.map((e) => [e.key, e.value])) })); toast(r.summary.join("; ")); setCmd(""); }
      else toast(`Cyrus can't do that without the AI: ${r.reason}. Change it in the form or ask in a normal change.`, true);
    } catch (e) { toast((e as Error).message, true); }
  };

  return (
    <>
      {readOnly && <div className="cfg-ro"><SI n="phone" />Read only on a phone: open this page on a bigger screen to change settings.</div>}
      <main className="cfg-ws">
        <nav className="cfg-rail cys-panel cys-glass" aria-label="Setting groups">
          <button className={`cfg-g ${!group ? "on" : ""}`} onClick={() => setGroup(null)}>All settings<span className="n">{spec.params.length}</span></button>
          {groups.map((g) => (
            <button key={g.id} className={`cfg-g ${group === g.id ? "on" : ""}`} onClick={() => setGroup(g.id)}>
              {g.label}{spec.params.some((p) => p.group === g.id && changedKeys.includes(p.key)) && <span className="ch" aria-label="changed" />}
              <span className="n">{spec.params.filter((p) => p.group === g.id).length}</span>
            </button>
          ))}
          <div className="cfg-legend">
            <span className="cys-eyebrow">How changes apply</span>
            {spec.reload && <><Badge a="reload" />  <span>{spec.reload.command}, no restart</span></>}
            <Badge a="restart" /><span>Needs a server restart</span>
          </div>
        </nav>
        <section className="cfg-form cys-panel cys-glass cys-hairline">
          <div className="cfg-fh">
            <h1>Config and stats</h1>
            <span className={`cys-tag ${view.source === "inferred" ? "dim" : "ok"}`}><SI n={view.source === "inferred" ? "info" : "check"} />{SOURCE_LABEL[view.source]}</span>
            <span className="sp" />
            <label className="cfg-search"><SI n="search" /><input className="cys-field" placeholder="Search settings" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Search settings" /></label>
          </div>
          <div className="cfg-bar">
            {spec.presets.length > 0 && <><span className="cys-eyebrow">Preset</span>
              <div className="cys-seg sm cys-soft" role="group" aria-label="Presets">
                {spec.presets.map((pr) => <button key={pr.id} className={presetOn === pr.id ? "on" : ""} disabled={readOnly} onClick={() => setVals((o) => ({ ...o, ...pr.values }))}>{pr.label}</button>)}
                <button className={presetOn === "custom" ? "on" : ""} disabled>Custom</button>
              </div></>}
            <span className="sp" />
            {changedKeys.length > 0 && <span className="cys-tag acc">{changedKeys.length} unsaved</span>}
            {view.history.length > 0 && <button className="cys-btn sm ghost" onClick={() => setShowHistory((x) => !x)}><SI n="history" />History</button>}
            <button className="cys-btn sm ghost" disabled={readOnly || !changedKeys.length} onClick={() => setVals(view.values)}><SI n="undo" />Discard</button>
            <button className="cys-btn sm" disabled={readOnly || busy || !changedKeys.length} onClick={openReview}><SI n="split" />Review changes</button>
          </div>
          {view.source === "inferred" && <p className="cfg-note"><SI n="info" />Cyrus read these settings from the mod&apos;s config.yml. Types come from the file; limits only where its comments state them.</p>}
          <div className="cfg-rows">
            {groups.map((g) => {
              const rs = shown.filter((p) => p.group === g.id);
              if (!rs.length) return null;
              return (
                <div key={g.id}>
                  <div className="cfg-gh"><h2>{g.label}</h2>{g.help && <span>{g.help}</span>}</div>
                  {rs.map((p) => <Row key={p.key} p={p} v={vals[p.key]} saved={view.values[p.key]} def={view.defaults[p.key]} readOnly={readOnly || !!p.readOnly} onChange={(v) => set(p.key, v)} />)}
                </div>
              );
            })}
            {!shown.length && <p className="cys-hint" style={{ padding: 20 }}>No setting matches “{q}”.</p>}
          </div>
          {!readOnly && (
            <div className="cfg-cmd">
              <span className="ic"><SI n="sparkle" /></span>
              <input className="cys-field" value={cmd} onChange={(e) => setCmd(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void runCmd(); }} placeholder={`Or type it: "set ${spec.params.find(numericT)?.label.toLowerCase() ?? "a setting"} to …"`} aria-label="Type a change" />
              <button className="cys-btn sm" onClick={runCmd}>Apply</button><span className="cys-hint">no AI, no tokens</span>
            </div>
          )}
          {review && (
            <div className="cfg-drawer cys-glass cys-hairline" role="dialog" aria-label="Review changes">
              <div className="dh"><SI n="split" /><h3>Review {review.patch.length} change{review.patch.length === 1 ? "" : "s"}</h3>
                {review.applies !== "none" && <Badge a={review.applies as Applies} />}
                <span className="cys-hint">{review.applies === "reload" && spec.reload ? `${spec.reload.command}: no restart, no rebuild, no tokens` : review.applies === "restart" ? "Needs a server restart; no rebuild, no tokens" : "No rebuild, no tokens"}</span>
                <span className="sp" /><button className="cys-ib" onClick={() => setReview(null)} aria-label="Close"><SI n="close" /></button></div>
              <div className="db">
                <div className="changes"><span className="cys-eyebrow">Settings</span>
                  {review.patch.map((op) => { const p = spec.params.find((x) => x.key === op.key)!; return <div key={op.key} className="ci"><span>{p.label}</span><span className="from">{fmt(p, op.from)}</span><SI n="chevR" /><span className="to">{fmt(p, op.to)}</span></div>; })}
                  {review.errors.map((e) => <div key={e.key} className="cfg-warn bad"><SI n="warn" />{e.message}</div>)}
                  {review.warnings.length > 0 && <div className="cfg-warn"><SI n="warn" />{review.warnings.length} value{review.warnings.length === 1 ? " is" : "s are"} outside the balanced range. You can still save.</div>}
                </div>
                <pre aria-label="config.yml changes">{yamlDiff(view, review)}</pre>
              </div>
              <div className="df"><span className="cys-hint">A new revision; undo any time from History.</span><span className="sp" />
                <button className="cys-btn sm ghost" onClick={() => setReview(null)}>Keep editing</button>
                <button className="cys-btn sm" disabled title={view.deliveryConnected ? "" : "Sending settings to a server is not connected yet"}><SI n="server" />Save and send to a server</button>
                <button className="cys-btn sm primary" disabled={busy || review.errors.length > 0} onClick={save}><SI n="check" />Save revision</button></div>
            </div>
          )}
          {showHistory && (
            <div className="cfg-drawer cys-glass" role="dialog" aria-label="History">
              <div className="dh"><SI n="history" /><h3>Settings history</h3><span className="sp" /><button className="cys-ib" onClick={() => setShowHistory(false)} aria-label="Close"><SI n="close" /></button></div>
              <div className="hist">{view.history.map((h) => (
                <div key={h.revisionId} className="hi"><span className="cys-tag dim">rev {h.seq}</span><span className="m">{h.message ?? "Settings change"}</span><span className="cys-hint">{new Date(h.createdAt).toLocaleString()}</span>
                  {!readOnly && <button className="cys-btn xs" disabled={busy} onClick={() => undo(h.revisionId)}><SI n="undo" />Undo</button>}</div>
              ))}</div>
            </div>
          )}
        </section>
        <PreviewPanel spec={spec} fx={fx} />
      </main>
      {unbalanced.length > 0 && strongest === null && null}
    </>
  );
}

function yamlDiff(view: View, r: Preview): string {
  const a = (view.history.length ? "" : "").split("\n");
  void a;
  const lines = r.configYml.split("\n");
  const keys = new Set(r.patch.map((p) => p.key.split(".").pop()!));
  const out: string[] = ["# config.yml: only these lines change. Comments and other keys stay."];
  lines.forEach((l) => { const m = /^\s*([A-Za-z0-9_-]+):/.exec(l); if (m && keys.has(m[1])) out.push(`+ ${l.trim()}`); });
  for (const op of r.patch) out.splice(1 + r.patch.indexOf(op) * 2, 0, `- ${op.key.split(".").pop()}: ${Array.isArray(op.from) || (op.from && typeof op.from === "object") ? JSON.stringify(op.from) : String(op.from)}`);
  return out.join("\n");
}

function Badge({ a }: { a: Applies }) {
  const x = APPLIES[a];
  return <span className={`cys-tag ${x.cls}`} title={a === "restart" ? "Takes effect after a server restart" : a === "reload" ? "Takes effect with the mod's reload command" : "Takes effect at once"}><SI n={x.icon} />{x.label}</span>;
}

function Row({ p, v, saved, def, readOnly, onChange }: { p: ConfigParam; v: ConfigValue; saved: ConfigValue; def: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void }) {
  const dirty = !sameValue(v, saved);
  const warns = balanceWarnings(p, v);
  const [bad, setBad] = useState<string | null>(null);
  return (
    <div className={`cfg-row ${dirty ? "changed" : ""}`} data-key={p.key}>
      <div className="lb">
        <b>{p.label}{p.visual && <span className="cys-tag dim" title="Plays in the preview"><SI n="eye" />preview</span>}</b>
        {p.help && <small>{p.help}</small>}
        <span className="k mono">{p.key}</span>
      </div>
      <Control p={p} v={v} readOnly={readOnly} onChange={onChange} onBad={setBad} />
      <div className="right"><Badge a={p.applies} /><button className="cys-ib sm" title={`Reset to ${fmt(p, def)}`} aria-label={`Reset ${p.label}`} disabled={readOnly || sameValue(v, def)} onClick={() => onChange(def)}><SI n="restore" /></button></div>
      {bad && <div className="cfg-warn bad"><SI n="warn" />{bad}</div>}
      {!bad && warns.map((w) => <div key={w.code} className="cfg-warn"><SI n="warn" />{w.message}. It still saves.</div>)}
    </div>
  );
}

function Control({ p, v, readOnly, onChange, onBad }: { p: ConfigParam; v: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void; onBad: (m: string | null) => void }) {
  const [text, setText] = useState<string | null>(null);
  if (p.type === "bool") return <div className="ctl"><button role="switch" aria-checked={!!v} aria-label={p.label} className={`cfg-tog ${v ? "on" : ""}`} disabled={readOnly} onClick={() => onChange(!v)} /><span className="cys-hint">{v ? "On" : "Off"}</span></div>;
  if (p.type === "enum") {
    const opts = p.options ?? [];
    return opts.length <= 4
      ? <div className="ctl"><div className="cys-seg sm cys-soft" role="radiogroup" aria-label={p.label}>{opts.map((o) => <button key={String(o.value)} role="radio" aria-checked={o.value === v} className={o.value === v ? "on" : ""} disabled={readOnly} onClick={() => onChange(o.value)}>{o.label ?? String(o.value)}</button>)}</div></div>
      : <div className="ctl"><select className="cys-field" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(opts.find((o) => String(o.value) === e.target.value)!.value)}>{opts.map((o) => <option key={String(o.value)} value={String(o.value)}>{o.label ?? String(o.value)}</option>)}</select></div>;
  }
  if (p.type === "color") return <div className="ctl"><input type="color" className="cfg-color" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(e.target.value)} /><input className="cys-field mono" style={{ width: 110 }} value={String(v)} readOnly={readOnly} aria-label={`${p.label} hex`} onChange={(e) => onChange(e.target.value)} /></div>;
  if (p.type === "text" || p.type === "sound-ref" || p.type === "asset-ref") return <div className="ctl"><input className={`cys-field ${p.type !== "text" ? "mono" : ""}`} value={String(v)} readOnly={readOnly} maxLength={p.maxLength ?? 256} aria-label={p.label} onChange={(e) => { const c = checkValue(p, e.target.value); onBad(c.ok ? null : c.error.message); onChange(e.target.value); }} /></div>;
  if (p.type === "list") {
    const arr = (v as ScalarValue[]) ?? [];
    return <div className="ctl"><div className="cys-chiprow">{arr.map((x, i) => <span key={i} className="cys-fchip">{String(x)}{!readOnly && <button aria-label={`Remove ${x}`} onClick={() => onChange(arr.filter((_, j) => j !== i))}><SI n="close" /></button>}</span>)}
      {!readOnly && <input className="cys-field cfg-add" placeholder="Add…" aria-label={`Add to ${p.label}`} onKeyDown={(e) => { if (e.key === "Enter" && e.currentTarget.value.trim()) { const raw = e.currentTarget.value.trim(); const val = p.item?.type === "number" || p.item?.type === "int" ? Number(raw) : raw; onChange([...arr, val]); e.currentTarget.value = ""; } }} />}</div></div>;
  }
  if (p.type === "table") {
    const rows = (v as Record<string, ScalarValue>[]) ?? [];
    const cols = p.columns ?? [];
    return <div className="ctl"><table className="cfg-tbl"><thead><tr>{cols.map((c) => <th key={c.key}>{c.label}</th>)}<th /></tr></thead><tbody>
      {rows.map((r, i) => <tr key={i}>{cols.map((c) => <td key={c.key}><input className={`cys-field ${c.type !== "text" ? "mono" : ""}`} value={String(r[c.key] ?? "")} readOnly={readOnly} aria-label={`${c.label} row ${i + 1}`} onChange={(e) => { const x = c.type === "number" || c.type === "int" ? (e.target.value === "" ? "" : Number(e.target.value)) : e.target.value; onChange(rows.map((rr, j) => (j === i ? { ...rr, [c.key]: x as ScalarValue } : rr))); }} /></td>)}
        <td>{!readOnly && <button className="cys-ib sm" aria-label={`Remove row ${i + 1}`} onClick={() => onChange(rows.filter((_, j) => j !== i))}><SI n="close" /></button>}</td></tr>)}
      {!readOnly && <tr><td colSpan={cols.length + 1}><button className="cys-btn xs" onClick={() => onChange([...rows, Object.fromEntries(cols.map((c) => [c.key, c.default ?? (c.type === "text" ? "" : c.type === "bool" ? false : c.min ?? 0)])) as Record<string, ScalarValue>])}><SI n="plus" />Add a row</button></td></tr>}
    </tbody></table></div>;
  }
  if (p.type === "range") {
    const [a, b] = v as number[];
    return <div className="ctl"><label className="cfg-num"><input value={a} readOnly={readOnly} aria-label={`${p.label} low`} onChange={(e) => onChange([Number(e.target.value), b])} /></label><span className="cys-hint">to</span><label className="cfg-num"><input value={b} readOnly={readOnly} aria-label={`${p.label} high`} onChange={(e) => onChange([a, Number(e.target.value)])} /><span>{p.unit ?? ""}</span></label></div>;
  }
  // number / int / duration: a slider over the hard limits with the balanced band, plus a typed field with the unit
  const dur = p.type === "duration";
  const shownV = dur ? toSeconds(p, v as number) : (v as number);
  const lo = p.min !== undefined ? (dur ? toSeconds(p, p.min) : p.min) : undefined;
  const hi = p.max !== undefined ? (dur ? toSeconds(p, p.max) : p.max) : undefined;
  const step = dur ? (p.durationUnit === "ticks" ? 0.05 : 0.1) : p.step ?? (p.type === "int" ? 1 : 0.01);
  const pct = (x: number) => (lo !== undefined && hi !== undefined && hi > lo ? ((x - lo) / (hi - lo)) * 100 : 0);
  const sMin = p.safe?.min !== undefined ? (dur ? toSeconds(p, p.safe.min) : p.safe.min) : lo;
  const sMax = p.safe?.max !== undefined ? (dur ? toSeconds(p, p.safe.max) : p.safe.max) : hi;
  const commit = (raw: string) => {
    const n = Number(raw);
    if (raw.trim() === "" || !Number.isFinite(n)) { onBad(`${p.label} needs a number`); return; }
    const stored = dur ? fromSeconds(p, n) : n;
    const c = checkValue(p, stored);
    if (!c.ok) { onBad(c.error.message); return; }
    onBad(null); onChange(c.value); setText(null);
  };
  return (
    <div className="ctl">
      {lo !== undefined && hi !== undefined && (
        <div className="cfg-track">
          {p.safe && sMin !== undefined && sMax !== undefined && <span className="safe" style={{ left: `${pct(sMin)}%`, width: `${pct(sMax) - pct(sMin)}%` }} />}
          <input type="range" min={lo} max={hi} step={step} value={shownV} disabled={readOnly} aria-label={p.label} onChange={(e) => commit(e.target.value)} />
        </div>
      )}
      <label className="cfg-num"><input inputMode="decimal" value={text ?? String(Math.round(shownV * 1e4) / 1e4)} readOnly={readOnly} aria-label={`${p.label} value`} onChange={(e) => setText(e.target.value)} onBlur={(e) => commit(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") commit((e.target as HTMLInputElement).value); }} /><span>{dur ? "s" : p.unit ?? ""}</span></label>
    </div>
  );
}

/** The preview stage: a stand-in creature or weapon whose clip phase comes from a PlaybackClock driven by the stats. */
function PreviewPanel({ spec, fx }: { spec: ConfigSpec; fx: VisualEffects | null }) {
  const kind = spec.params.some((p) => p.visual?.channel === "fireRate") ? "gun" : spec.params.some((p) => p.visual?.channel === "clipRate" && p.visual.clip === "walk") ? "mob" : spec.params.some((p) => p.visual?.channel === "attackRate") ? "melee" : null;
  const clips = kind === "gun" ? ["fire", "reload"] : kind === "melee" ? ["swing"] : ["walk", "attack"];
  const [clip, setClip] = useState(clips[0]);
  const [playing, setPlaying] = useState(true);
  const clock = useRef<PlaybackClock | null>(null);
  const [t, setT] = useState(0);
  useEffect(() => { clock.current = new PlaybackClock({ end: 1, loop: true }); clock.current.play(); return () => { clock.current = null; }; }, []);
  useEffect(() => { if (clock.current && fx) applyToClock(clock.current, fx, clip); }, [fx, clip]);
  useEffect(() => { const c = clock.current; if (!c) return; if (playing) c.play(); else c.pause(); }, [playing]);
  useEffect(() => {
    let raf = 0, last = performance.now();
    const loop = (now: number) => { const c = clock.current; if (c) { c.tick(Math.min(0.1, (now - last) / 1000)); setT(c.time); } last = now; raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);
  if (!kind || !fx) return (
    <aside className="cfg-pv cys-panel cys-glass"><div className="cys-ph"><span className="cys-eyebrow">Preview</span></div>
      <div className="cys-empty" style={{ padding: 24 }}><SI n="eye" /><p className="cys-hint">None of these settings has a visual. Speed, attack speed, size and fire rate stats play here when a mod has them.</p></div></aside>
  );
  const phase = Math.sin(t * Math.PI * 2);
  const rate = fx.clipRates[clip] ?? 1;
  return (
    <aside className="cfg-pv cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Preview</span>
        <div className="cys-seg sm cys-soft" role="group" aria-label="Clip">{clips.map((c) => <button key={c} className={clip === c ? "on" : ""} onClick={() => setClip(c)}>{c[0].toUpperCase() + c.slice(1)}</button>)}</div></div>
      <div className="cfg-stage">
        <span className="live cys-tag"><span className="cys-dot live" />live preview</span>
        <span className="ground" />
        {kind === "gun" ? (
          <div className="gunv" style={{ transform: `translateX(${clip === "fire" ? -Math.max(0, phase) * 6 : 0}px)` }}>
            <span className="stk" /><span className="rcv" /><span className="brl" />
            <span className="mag" style={{ transform: `translateY(${clip === "reload" ? Math.max(0, phase) * 40 : 0}px)`, opacity: clip === "reload" && phase > 0.5 ? 0.3 : 1 }} />
            <span className="flash" style={{ opacity: clip === "fire" && phase > 0.6 ? 1 : 0 }} />
          </div>
        ) : (
          <div className="mob" style={{ transform: `scale(${Math.min(3, fx.scale)})` }}>
            <div className="head" />
            <div className="body">
              <span className="arm l" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 - phase * 25 : phase * 18}deg)` }} />
              <span className="arm r" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 + phase * 25 : -phase * 18}deg)` }} />
              <span className="leg l" style={{ transform: `rotate(${clip === "walk" ? phase * 24 : 0}deg)` }} />
              <span className="leg r" style={{ transform: `rotate(${clip === "walk" ? -phase * 24 : 0}deg)` }} />
            </div>
          </div>
        )}
      </div>
      <div className="cfg-readout">
        <span className="cys-eyebrow">What the stats do to the model</span>
        {Object.entries(fx.clipRates).map(([c, r]) => <div key={c} className="r"><SI n="play" />{c[0].toUpperCase() + c.slice(1)} clip<span className="meter"><i style={{ width: `${Math.min(100, r * 50)}%` }} /></span><b className="mono">{r.toFixed(2)}x</b></div>)}
        {fx.fireIntervalS !== null && <div className="r"><SI n="history" />Time between shots<b className="mono">{fx.fireIntervalS.toFixed(3)} s</b></div>}
        {fx.scale !== 1 && <div className="r"><SI n="zoomin" />Size<span className="meter"><i style={{ width: `${Math.min(100, fx.scale * 33)}%` }} /></span><b className="mono">{fx.scale.toFixed(2)}x</b></div>}
        <p className="cys-hint">An approximation for feel, played at {rate.toFixed(2)}x. The server is the truth: Cyrus checks every value against its limits again when it saves.</p>
      </div>
      <div className="cfg-clock"><button className={`cys-ib ${playing ? "on" : ""}`} aria-label={playing ? "Pause" : "Play"} onClick={() => setPlaying((x) => !x)}><SI n={playing ? "pause" : "play"} /></button><span className="cys-hint">Clock speed follows the stats</span></div>
    </aside>
  );
}

toolu_014RgGtPm9hjzDY7XsuhscrS.content:
"use client";
// Cyrus Config and Stats Studio: the Config page of the studio shell. A form GENERATED from the mod's ConfigSpec
// (lib/cyrus/config): groups rail, search, presets, per-setting reset, balance warnings, "applies" badges, a review
// drawer (the exact config.yml lines that change, from the server's preview), Save revision (values only: no model, no
// build), undo from history, and the "just type it" box (deterministic, no AI). The preview stage runs on Model
// Studio's PlaybackClock: stats with a `visual` link (walk speed, attack speed, fire rate, reload, size) set the clock
// speed through applyToClock, so the clip plays faster or slower as the number moves. Narrow screens are read only.
// Approved mockups: /root/agent-notes/cyrus-designs/v5-config/config-mob.html + config-gun.html.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { StudioShell, useToast, type StudioMod } from "./StudioShell";
import { SI } from "./icons";
import { applyToClock, visualEffects, type VisualEffects } from "@/lib/cyrus/config/visual";
import { balanceWarnings, checkValue, fmt, fromSeconds, sameValue, toSeconds } from "@/lib/cyrus/config/values";
import type { Applies, ConfigParam, ConfigSpec, ConfigValue, ConfigValues, ScalarValue } from "@/lib/cyrus/config/spec";
import { PlaybackClock } from "@/lib/cyrus/modelstudio/clock";
import "./config-studio.css";

type View = {
  project: { id: string; namespace: string } | null; pluginName: string | null; mcVersion: string; buildId: string;
  source: "declared" | "designer" | "inferred" | "none"; spec: ConfigSpec | null; notes: string[];
  values: ConfigValues; shipped: ConfigValues; defaults: ConfigValues; changedFromDefaults: string[]; preset: string;
  headRevisionId: string | null; history: { revisionId: string; seq: number; createdAt: string; message: string | null; patch: { key: string; from: unknown; to: unknown }[] }[];
  deliveryConnected: boolean;
};
type Preview = { configYml: string; patch: { key: string; from: ConfigValue; to: ConfigValue }[]; applies: Applies | "none"; errors: { key: string; message: string }[]; warnings: { key: string; message: string }[] };

const API = "/api/cyrus/config/v1";
async function api<T>(init?: { method: "POST"; body: unknown }, q = ""): Promise<T> {
  const r = await fetch(`${API}${q}`, init ? { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(init.body) } : { cache: "no-store" });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw Object.assign(new Error((j as { error?: string }).error ?? "Something went wrong."), { status: r.status, body: j });
  return j as T;
}

const SOURCE_LABEL: Record<View["source"], string> = { declared: "Declared by Cyrus", designer: "From the item designs", inferred: "Read from config.yml", none: "No settings" };
const APPLIES: Record<Applies, { label: string; cls: string; icon: string }> = {
  live: { label: "Live", cls: "ok", icon: "check" }, reload: { label: "Reload", cls: "acc", icon: "restore" }, restart: { label: "Restart", cls: "warn", icon: "server" },
};
const numericT = (p: ConfigParam) => p.type === "number" || p.type === "int" || p.type === "duration";

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const m = window.matchMedia("(max-width: 760px)"); const f = () => setN(m.matches); f(); m.addEventListener("change", f); return () => m.removeEventListener("change", f); }, []);
  return n;
}

export function ConfigStudio({ mod, showModel = false }: { mod: StudioMod; showModel?: boolean }) {
  return (
    <StudioShell mod={mod} current="Config" studio="config" showModel={showModel} showConfig>
      <ConfigBody mod={mod} />
    </StudioShell>
  );
}

function ConfigBody({ mod }: { mod: StudioMod }) {
  const toast = useToast();
  const narrow = useNarrow();
  const [view, setView] = useState<View | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [vals, setVals] = useState<ConfigValues>({});
  const [group, setGroup] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [review, setReview] = useState<Preview | null>(null);
  const [busy, setBusy] = useState(false);
  const [cmd, setCmd] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const load = useCallback(async () => {
    try { const v = await api<View>(undefined, `?root=${encodeURIComponent(mod.rootId)}`); setView(v); setVals(v.values); setErr(null); }
    catch (e) { setErr((e as Error).message); }
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);
  const spec = view?.spec ?? null;
  const readOnly = narrow;
  const changedKeys = useMemo(() => (spec && view ? spec.params.filter((p) => !sameValue(vals[p.key], view.values[p.key])).map((p) => p.key) : []), [spec, view, vals]);
  const fx = useMemo(() => (spec ? visualEffects(spec, vals) : null), [spec, vals]);
  const set = (k: string, v: ConfigValue) => setVals((o) => ({ ...o, [k]: v }));
  const presetOn = useMemo(() => { if (!spec) return "default"; for (const pr of spec.presets) if (Object.entries(pr.values).every(([k, v]) => sameValue(vals[k], v))) return pr.id; return spec.params.every((p) => sameValue(vals[p.key], view?.defaults[p.key])) ? "default" : "custom"; }, [spec, vals, view]);

  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s settings…</div>;
  if (!spec) return (
    <main className="cfg-ws one"><section className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
      <div className="cys-empty" style={{ maxWidth: 460 }}><SI n="gauge" /><p><b>This mod has no settings Cyrus can edit yet.</b></p><p className="cys-hint">{view.notes[0] ?? "Ask Cyrus to make its numbers configurable in your next change."}</p></div>
    </section></main>
  );

  const groups = [...spec.groups].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const ql = q.trim().toLowerCase();
  const shown = spec.params.filter((p) => (!ql || `${p.label} ${p.key} ${p.help ?? ""} ${p.tags.join(" ")}`.toLowerCase().includes(ql)) && (!group || ql || p.group === group));
  const unbalanced = spec.params.filter((p) => balanceWarnings(p, vals[p.key]).length);
  const strongest = changedKeys.reduce<Applies | null>((a, k) => { const ap = spec.params.find((p) => p.key === k)!.applies; return !a || (ap === "restart" || (ap === "reload" && a === "live")) ? ap : a; }, null);

  const openReview = async () => {
    setBusy(true);
    try { setReview(await api<Preview>({ method: "POST", body: { root: mod.rootId, action: "preview", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])) } })); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const save = async () => {
    setBusy(true);
    try {
      const r = await api<{ seq: number; applies: string }>({ method: "POST", body: { root: mod.rootId, action: "save", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])), expectedHeadId: view.headRevisionId } });
      toast(`Saved as revision ${r.seq}. ${r.applies === "reload" && spec.reload ? `Takes effect with ${spec.reload.command}.` : r.applies === "restart" ? "Takes effect after a server restart." : ""}`);
      setReview(null); await load();
    } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const undo = async (revisionId: string) => {
    setBusy(true);
    try { const r = await api<{ seq: number }>({ method: "POST", body: { root: mod.rootId, action: "revert", revisionId, expectedHeadId: view.headRevisionId } }); toast(`Undone as revision ${r.seq}.`); await load(); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const runCmd = async () => {
    if (!cmd.trim()) return;
    try {
      const r = await api<{ kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] } | { kind: "model"; reason: string }>({ method: "POST", body: { root: mod.rootId, action: "plan", text: cmd } });
      if (r.kind === "values") { setVals((o) => ({ ...o, ...Object.fromEntries(r.edits.map((e) => [e.key, e.value])) })); toast(r.summary.join("; ")); setCmd(""); }
      else toast(`Cyrus can't do that without the AI: ${r.reason}. Change it in the form or ask in a normal change.`, true);
    } catch (e) { toast((e as Error).message, true); }
  };

  return (
    <>
      {readOnly && <div className="cfg-ro"><SI n="phone" />Read only on a phone: open this page on a bigger screen to change settings.</div>}
      <main className="cfg-ws">
        <nav className="cfg-rail cys-panel cys-glass" aria-label="Setting groups">
          <button className={`cfg-g ${!group ? "on" : ""}`} onClick={() => setGroup(null)}>All settings<span className="n">{spec.params.length}</span></button>
          {groups.map((g) => (
            <button key={g.id} className={`cfg-g ${group === g.id ? "on" : ""}`} onClick={() => setGroup(g.id)}>
              {g.label}{spec.params.some((p) => p.group === g.id && changedKeys.includes(p.key)) && <span className="ch" aria-label="changed" />}
              <span className="n">{spec.params.filter((p) => p.group === g.id).length}</span>
            </button>
          ))}
          <div className="cfg-legend">
            <span className="cys-eyebrow">How changes apply</span>
            {spec.reload && <><Badge a="reload" />  <span>{spec.reload.command}, no restart</span></>}
            <Badge a="restart" /><span>Needs a server restart</span>
          </div>
        </nav>
        <section className="cfg-form cys-panel cys-glass cys-hairline">
          <div className="cfg-fh">
            <h1>Config and stats</h1>
            <span className={`cys-tag ${view.source === "inferred" ? "dim" : "ok"}`}><SI n={view.source === "inferred" ? "info" : "check"} />{SOURCE_LABEL[view.source]}</span>
            <span className="sp" />
            <label className="cfg-search"><SI n="search" /><input className="cys-field" placeholder="Search settings" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Search settings" /></label>
          </div>
          <div className="cfg-bar">
            {spec.presets.length > 0 && <><span className="cys-eyebrow">Preset</span>
              <div className="cys-seg sm cys-soft" role="group" aria-label="Presets">
                {spec.presets.map((pr) => <button key={pr.id} className={presetOn === pr.id ? "on" : ""} disabled={readOnly} onClick={() => setVals((o) => ({ ...o, ...pr.values }))}>{pr.label}</button>)}
                <button className={presetOn === "custom" ? "on" : ""} disabled>Custom</button>
              </div></>}
            <span className="sp" />
            {changedKeys.length > 0 && <span className="cys-tag acc">{changedKeys.length} unsaved</span>}
            {view.history.length > 0 && <button className="cys-btn sm ghost" onClick={() => setShowHistory((x) => !x)}><SI n="history" />History</button>}
            <button className="cys-btn sm ghost" disabled={readOnly || !changedKeys.length} onClick={() => setVals(view.values)}><SI n="undo" />Discard</button>
            <button className="cys-btn sm" disabled={readOnly || busy || !changedKeys.length} onClick={openReview}><SI n="split" />Review changes</button>
          </div>
          {view.source === "inferred" && <p className="cfg-note"><SI n="info" />Cyrus read these settings from the mod&apos;s config.yml. Types come from the file; limits only where its comments state them.</p>}
          <div className="cfg-rows">
            {groups.map((g) => {
              const rs = shown.filter((p) => p.group === g.id);
              if (!rs.length) return null;
              return (
                <div key={g.id}>
                  <div className="cfg-gh"><h2>{g.label}</h2>{g.help && <span>{g.help}</span>}</div>
                  {rs.map((p) => <Row key={p.key} p={p} v={vals[p.key]} saved={view.values[p.key]} def={view.defaults[p.key]} readOnly={readOnly || !!p.readOnly} onChange={(v) => set(p.key, v)} />)}
                </div>
              );
            })}
            {!shown.length && <p className="cys-hint" style={{ padding: 20 }}>No setting matches “{q}”.</p>}
          </div>
          {!readOnly && (
            <div className="cfg-cmd">
              <span className="ic"><SI n="sparkle" /></span>
              <input className="cys-field" value={cmd} onChange={(e) => setCmd(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void runCmd(); }} placeholder={`Or type it: "set ${spec.params.find(numericT)?.label.toLowerCase() ?? "a setting"} to …"`} aria-label="Type a change" />
              <button className="cys-btn sm" onClick={runCmd}>Apply</button><span className="cys-hint">no AI, no tokens</span>
            </div>
          )}
          {review && (
            <div className="cfg-drawer cys-glass cys-hairline" role="dialog" aria-label="Review changes">
              <div className="dh"><SI n="split" /><h3>Review {review.patch.length} change{review.patch.length === 1 ? "" : "s"}</h3>
                {review.applies !== "none" && <Badge a={review.applies as Applies} />}
                <span className="cys-hint">{review.applies === "reload" && spec.reload ? `${spec.reload.command}: no restart, no rebuild, no tokens` : review.applies === "restart" ? "Needs a server restart; no rebuild, no tokens" : "No rebuild, no tokens"}</span>
                <span className="sp" /><button className="cys-ib" onClick={() => setReview(null)} aria-label="Close"><SI n="close" /></button></div>
              <div className="db">
                <div className="changes"><span className="cys-eyebrow">Settings</span>
                  {review.patch.map((op) => { const p = spec.params.find((x) => x.key === op.key)!; return <div key={op.key} className="ci"><span>{p.label}</span><span className="from">{fmt(p, op.from)}</span><SI n="chevR" /><span className="to">{fmt(p, op.to)}</span></div>; })}
                  {review.errors.map((e) => <div key={e.key} className="cfg-warn bad"><SI n="warn" />{e.message}</div>)}
                  {review.warnings.length > 0 && <div className="cfg-warn"><SI n="warn" />{review.warnings.length} value{review.warnings.length === 1 ? " is" : "s are"} outside the balanced range. You can still save.</div>}
                </div>
                <pre aria-label="config.yml changes">{yamlDiff(view, review)}</pre>
              </div>
              <div className="df"><span className="cys-hint">A new revision; undo any time from History.</span><span className="sp" />
                <button className="cys-btn sm ghost" onClick={() => setReview(null)}>Keep editing</button>
                <button className="cys-btn sm" disabled title={view.deliveryConnected ? "" : "Sending settings to a server is not connected yet"}><SI n="server" />Save and send to a server</button>
                <button className="cys-btn sm primary" disabled={busy || review.errors.length > 0} onClick={save}><SI n="check" />Save revision</button></div>
            </div>
          )}
          {showHistory && (
            <div className="cfg-drawer cys-glass" role="dialog" aria-label="History">
              <div className="dh"><SI n="history" /><h3>Settings history</h3><span className="sp" /><button className="cys-ib" onClick={() => setShowHistory(false)} aria-label="Close"><SI n="close" /></button></div>
              <div className="hist">{view.history.map((h) => (
                <div key={h.revisionId} className="hi"><span className="cys-tag dim">rev {h.seq}</span><span className="m">{h.message ?? "Settings change"}</span><span className="cys-hint">{new Date(h.createdAt).toLocaleString()}</span>
                  {!readOnly && <button className="cys-btn xs" disabled={busy} onClick={() => undo(h.revisionId)}><SI n="undo" />Undo</button>}</div>
              ))}</div>
            </div>
          )}
        </section>
        <PreviewPanel spec={spec} fx={fx} />
      </main>
      {unbalanced.length > 0 && strongest === null && null}
    </>
  );
}

function yamlDiff(view: View, r: Preview): string {
  const a = (view.history.length ? "" : "").split("\n");
  void a;
  const lines = r.configYml.split("\n");
  const keys = new Set(r.patch.map((p) => p.key.split(".").pop()!));
  const out: string[] = ["# config.yml: only these lines change. Comments and other keys stay."];
  lines.forEach((l) => { const m = /^\s*([A-Za-z0-9_-]+):/.exec(l); if (m && keys.has(m[1])) out.push(`+ ${l.trim()}`); });
  for (const op of r.patch) out.splice(1 + r.patch.indexOf(op) * 2, 0, `- ${op.key.split(".").pop()}: ${Array.isArray(op.from) || (op.from && typeof op.from === "object") ? JSON.stringify(op.from) : String(op.from)}`);
  return out.join("\n");
}

function Badge({ a }: { a: Applies }) {
  const x = APPLIES[a];
  return <span className={`cys-tag ${x.cls}`} title={a === "restart" ? "Takes effect after a server restart" : a === "reload" ? "Takes effect with the mod's reload command" : "Takes effect at once"}><SI n={x.icon} />{x.label}</span>;
}

function Row({ p, v, saved, def, readOnly, onChange }: { p: ConfigParam; v: ConfigValue; saved: ConfigValue; def: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void }) {
  const dirty = !sameValue(v, saved);
  const warns = balanceWarnings(p, v);
  const [bad, setBad] = useState<string | null>(null);
  return (
    <div className={`cfg-row ${dirty ? "changed" : ""}`} data-key={p.key}>
      <div className="lb">
        <b>{p.label}{p.visual && <span className="cys-tag dim" title="Plays in the preview"><SI n="eye" />preview</span>}</b>
        {p.help && <small>{p.help}</small>}
        <span className="k mono">{p.key}</span>
      </div>
      <Control p={p} v={v} readOnly={readOnly} onChange={onChange} onBad={setBad} />
      <div className="right"><Badge a={p.applies} /><button className="cys-ib sm" title={`Reset to ${fmt(p, def)}`} aria-label={`Reset ${p.label}`} disabled={readOnly || sameValue(v, def)} onClick={() => onChange(def)}><SI n="restore" /></button></div>
      {bad && <div className="cfg-warn bad"><SI n="warn" />{bad}</div>}
      {!bad && warns.map((w) => <div key={w.code} className="cfg-warn"><SI n="warn" />{w.message}. It still saves.</div>)}
    </div>
  );
}

function Control({ p, v, readOnly, onChange, onBad }: { p: ConfigParam; v: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void; onBad: (m: string | null) => void }) {
  const [text, setText] = useState<string | null>(null);
  if (p.type === "bool") return <div className="ctl"><button role="switch" aria-checked={!!v} aria-label={p.label} className={`cfg-tog ${v ? "on" : ""}`} disabled={readOnly} onClick={() => onChange(!v)} /><span className="cys-hint">{v ? "On" : "Off"}</span></div>;
  if (p.type === "enum") {
    const opts = p.options ?? [];
    return opts.length <= 4
      ? <div className="ctl"><div className="cys-seg sm cys-soft" role="radiogroup" aria-label={p.label}>{opts.map((o) => <button key={String(o.value)} role="radio" aria-checked={o.value === v} className={o.value === v ? "on" : ""} disabled={readOnly} onClick={() => onChange(o.value)}>{o.label ?? String(o.value)}</button>)}</div></div>
      : <div className="ctl"><select className="cys-field" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(opts.find((o) => String(o.value) === e.target.value)!.value)}>{opts.map((o) => <option key={String(o.value)} value={String(o.value)}>{o.label ?? String(o.value)}</option>)}</select></div>;
  }
  if (p.type === "color") return <div className="ctl"><input type="color" className="cfg-color" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(e.target.value)} /><input className="cys-field mono" style={{ width: 110 }} value={String(v)} readOnly={readOnly} aria-label={`${p.label} hex`} onChange={(e) => onChange(e.target.value)} /></div>;
  if (p.type === "text" || p.type === "sound-ref" || p.type === "asset-ref") return <div className="ctl"><input className={`cys-field ${p.type !== "text" ? "mono" : ""}`} value={String(v)} readOnly={readOnly} maxLength={p.maxLength ?? 256} aria-label={p.label} onChange={(e) => { const c = checkValue(p, e.target.value); onBad(c.ok ? null : c.error.message); onChange(e.target.value); }} /></div>;
  if (p.type === "list") {
    const arr = (v as ScalarValue[]) ?? [];
    return <div className="ctl"><div className="cys-chiprow">{arr.map((x, i) => <span key={i} className="cys-fchip">{String(x)}{!readOnly && <button aria-label={`Remove ${x}`} onClick={() => onChange(arr.filter((_, j) => j !== i))}><SI n="close" /></button>}</span>)}
      {!readOnly && <input className="cys-field cfg-add" placeholder="Add…" aria-label={`Add to ${p.label}`} onKeyDown={(e) => { if (e.key === "Enter" && e.currentTarget.value.trim()) { const raw = e.currentTarget.value.trim(); const val = p.item?.type === "number" || p.item?.type === "int" ? Number(raw) : raw; onChange([...arr, val]); e.currentTarget.value = ""; } }} />}</div></div>;
  }
  if (p.type === "table") {
    const rows = (v as Record<string, ScalarValue>[]) ?? [];
    const cols = p.columns ?? [];
    return <div className="ctl"><table className="cfg-tbl"><thead><tr>{cols.map((c) => <th key={c.key}>{c.label}</th>)}<th /></tr></thead><tbody>
      {rows.map((r, i) => <tr key={i}>{cols.map((c) => <td key={c.key}><input className={`cys-field ${c.type !== "text" ? "mono" : ""}`} value={String(r[c.key] ?? "")} readOnly={readOnly} aria-label={`${c.label} row ${i + 1}`} onChange={(e) => { const x = c.type === "number" || c.type === "int" ? (e.target.value === "" ? "" : Number(e.target.value)) : e.target.value; onChange(rows.map((rr, j) => (j === i ? { ...rr, [c.key]: x as ScalarValue } : rr))); }} /></td>)}
        <td>{!readOnly && <button className="cys-ib sm" aria-label={`Remove row ${i + 1}`} onClick={() => onChange(rows.filter((_, j) => j !== i))}><SI n="close" /></button>}</td></tr>)}
      {!readOnly && <tr><td colSpan={cols.length + 1}><button className="cys-btn xs" onClick={() => onChange([...rows, Object.fromEntries(cols.map((c) => [c.key, c.default ?? (c.type === "text" ? "" : c.type === "bool" ? false : c.min ?? 0)])) as Record<string, ScalarValue>])}><SI n="plus" />Add a row</button></td></tr>}
    </tbody></table></div>;
  }
  if (p.type === "range") {
    const [a, b] = v as number[];
    return <div className="ctl"><label className="cfg-num"><input value={a} readOnly={readOnly} aria-label={`${p.label} low`} onChange={(e) => onChange([Number(e.target.value), b])} /></label><span className="cys-hint">to</span><label className="cfg-num"><input value={b} readOnly={readOnly} aria-label={`${p.label} high`} onChange={(e) => onChange([a, Number(e.target.value)])} /><span>{p.unit ?? ""}</span></label></div>;
  }
  // number / int / duration: a slider over the hard limits with the balanced band, plus a typed field with the unit
  const dur = p.type === "duration";
  const shownV = dur ? toSeconds(p, v as number) : (v as number);
  const lo = p.min !== undefined ? (dur ? toSeconds(p, p.min) : p.min) : undefined;
  const hi = p.max !== undefined ? (dur ? toSeconds(p, p.max) : p.max) : undefined;
  const step = dur ? (p.durationUnit === "ticks" ? 0.05 : 0.1) : p.step ?? (p.type === "int" ? 1 : 0.01);
  const pct = (x: number) => (lo !== undefined && hi !== undefined && hi > lo ? ((x - lo) / (hi - lo)) * 100 : 0);
  const sMin = p.safe?.min !== undefined ? (dur ? toSeconds(p, p.safe.min) : p.safe.min) : lo;
  const sMax = p.safe?.max !== undefined ? (dur ? toSeconds(p, p.safe.max) : p.safe.max) : hi;
  const commit = (raw: string) => {
    const n = Number(raw);
    if (raw.trim() === "" || !Number.isFinite(n)) { onBad(`${p.label} needs a number`); return; }
    const stored = dur ? fromSeconds(p, n) : n;
    const c = checkValue(p, stored);
    if (!c.ok) { onBad(c.error.message); return; }
    onBad(null); onChange(c.value); setText(null);
  };
  return (
    <div className="ctl">
      {lo !== undefined && hi !== undefined && (
        <div className="cfg-track">
          {p.safe && sMin !== undefined && sMax !== undefined && <span className="safe" style={{ left: `${pct(sMin)}%`, width: `${pct(sMax) - pct(sMin)}%` }} />}
          <input type="range" min={lo} max={hi} step={step} value={shownV} disabled={readOnly} aria-label={p.label} onChange={(e) => commit(e.target.value)} />
        </div>
      )}
      <label className="cfg-num"><input inputMode="decimal" value={text ?? String(Math.round(shownV * 1e4) / 1e4)} readOnly={readOnly} aria-label={`${p.label} value`} onChange={(e) => setText(e.target.value)} onBlur={(e) => commit(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") commit((e.target as HTMLInputElement).value); }} /><span>{dur ? "s" : p.unit ?? ""}</span></label>
    </div>
  );
}

/** The preview stage: a stand-in creature or weapon whose clip phase comes from a PlaybackClock driven by the stats. */
function PreviewPanel({ spec, fx }: { spec: ConfigSpec; fx: VisualEffects | null }) {
  const kind = spec.params.some((p) => p.visual?.channel === "fireRate") ? "gun" : spec.params.some((p) => p.visual?.channel === "clipRate" && p.visual.clip === "walk") ? "mob" : spec.params.some((p) => p.visual?.channel === "attackRate") ? "melee" : null;
  const clips = kind === "gun" ? ["fire", "reload"] : kind === "melee" ? ["swing"] : ["walk", "attack"];
  const [clip, setClip] = useState(clips[0]);
  const [playing, setPlaying] = useState(true);
  const clock = useRef<PlaybackClock | null>(null);
  const [t, setT] = useState(0);
  useEffect(() => { clock.current = new PlaybackClock({ end: 1, loop: true }); clock.current.play(); return () => { clock.current = null; }; }, []);
  useEffect(() => { if (clock.current && fx) applyToClock(clock.current, fx, clip); }, [fx, clip]);
  useEffect(() => { const c = clock.current; if (!c) return; if (playing) c.play(); else c.pause(); }, [playing]);
  useEffect(() => {
    let raf = 0, last = performance.now();
    const loop = (now: number) => { const c = clock.current; if (c) { c.tick(Math.min(0.1, (now - last) / 1000)); setT(c.time); } last = now; raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);
  if (!kind || !fx) return (
    <aside className="cfg-pv cys-panel cys-glass"><div className="cys-ph"><span className="cys-eyebrow">Preview</span></div>
      <div className="cys-empty" style={{ padding: 24 }}><SI n="eye" /><p className="cys-hint">None of these settings has a visual. Speed, attack speed, size and fire rate stats play here when a mod has them.</p></div></aside>
  );
  const phase = Math.sin(t * Math.PI * 2);
  const rate = fx.clipRates[clip] ?? 1;
  return (
    <aside className="cfg-pv cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Preview</span>
        <div className="cys-seg sm cys-soft" role="group" aria-label="Clip">{clips.map((c) => <button key={c} className={clip === c ? "on" : ""} onClick={() => setClip(c)}>{c[0].toUpperCase() + c.slice(1)}</button>)}</div></div>
      <div className="cfg-stage">
        <span className="live cys-tag"><span className="cys-dot live" />live preview</span>
        <span className="ground" />
        {kind === "gun" ? (
          <div className="gunv" style={{ transform: `translateX(${clip === "fire" ? -Math.max(0, phase) * 6 : 0}px)` }}>
            <span className="stk" /><span className="rcv" /><span className="brl" />
            <span className="mag" style={{ transform: `translateY(${clip === "reload" ? Math.max(0, phase) * 40 : 0}px)`, opacity: clip === "reload" && phase > 0.5 ? 0.3 : 1 }} />
            <span className="flash" style={{ opacity: clip === "fire" && phase > 0.6 ? 1 : 0 }} />
          </div>
        ) : (
          <div className="mob" style={{ transform: `scale(${Math.min(3, fx.scale)})` }}>
            <div className="head" />
            <div className="body">
              <span className="arm l" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 - phase * 25 : phase * 18}deg)` }} />
              <span className="arm r" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 + phase * 25 : -phase * 18}deg)` }} />
              <span className="leg l" style={{ transform: `rotate(${clip === "walk" ? phase * 24 : 0}deg)` }} />
              <span className="leg r" style={{ transform: `rotate(${clip === "walk" ? -phase * 24 : 0}deg)` }} />
            </div>
          </div>
        )}
      </div>
      <div className="cfg-readout">
        <span className="cys-eyebrow">What the stats do to the model</span>
        {Object.entries(fx.clipRates).map(([c, r]) => <div key={c} className="r"><SI n="play" />{c[0].toUpperCase() + c.slice(1)} clip<span className="meter"><i style={{ width: `${Math.min(100, r * 50)}%` }} /></span><b className="mono">{r.toFixed(2)}x</b></div>)}
        {fx.fireIntervalS !== null && <div className="r"><SI n="history" />Time between shots<b className="mono">{fx.fireIntervalS.toFixed(3)} s</b></div>}
        {fx.scale !== 1 && <div className="r"><SI n="zoomin" />Size<span className="meter"><i style={{ width: `${Math.min(100, fx.scale * 33)}%` }} /></span><b className="mono">{fx.scale.toFixed(2)}x</b></div>}
        <p className="cys-hint">An approximation for feel, played at {rate.toFixed(2)}x. The server is the truth: Cyrus checks every value against its limits again when it saves.</p>
      </div>
      <div className="cfg-clock"><button className={`cys-ib ${playing ? "on" : ""}`} aria-label={playing ? "Pause" : "Play"} onClick={() => setPlaying((x) => !x)}><SI n={playing ? "pause" : "play"} /></button><span className="cys-hint">Clock speed follows the stats</span></div>
    </aside>
  );
}

