.cys .cfg-track .safe { position: absolute; top: 15px; height: 4px; border-radius: 3px; background: color-mix(in srgb, var(--ok) 35%, transparent); pointer-events: none; }
.cys .cfg-num { width: 96px; flex: none; display: flex; align-items: center; border: 1px solid var(--line-2); border-radius: 10px; background: var(--well); height: 32px; }
