.cys .cfg-tog.on { background: var(--accent-solid); border-color: transparent; } .cys .cfg-tog.on::after { left: 18px; background: #fff; }
.cys .cfg-color { width: 36px; height: 32px; padding: 2px; border-radius: 9px; border: 1px solid var(--line-2); background: var(--well); }
.cys .cfg-add { width: 110px; height: 26px; }
.cys .cys-fchip button { display: inline-flex; color: var(--muted); }
.cys .cfg-tbl { width: 100%; border-collapse: collapse; font-size: 12px; }
.cys .cfg-tbl th { font: 600 9.5px/1 var(--mono); letter-spacing: .1em; text-transform: uppercase; color: var(--muted); text-align: left; padding: 6px 4px; }
.cys .cfg-tbl td { padding: 3px 4px; } .cys .cfg-tbl td .cys-field { height: 28px; font-size: 12px; }
.cys .cfg-cmd { display: flex; gap: 8px; padding: 10px 16px; border-top: 1px solid var(--line); align-items: center; }
.cys .cfg-cmd .ic { color: var(--accent-ink); display: flex; }
.cys .cfg-cmd input { flex: 1; }
.cys .cfg-drawer { position: absolute; left: 12px; right: 12px; bottom: 12px; border-radius: 18px; z-index: 20; max-height: 62%; display: flex; flex-direction: column; overflow: hidden; background: var(--solid); box-shadow: var(--pop-shadow); }
.cys .cfg-drawer .dh { display: flex; align-items: center; gap: 10px; padding: 12px 16px; border-bottom: 1px solid var(--line); }
.cys .cfg-drawer .dh > svg { color: var(--accent-ink); }
.cys .cfg-drawer h3 { margin: 0; font: 600 14px/1 var(--display); white-space: nowrap; }
.cys .cfg-drawer .db { display: grid; grid-template-columns: 1fr 1fr; min-height: 0; overflow: auto; }
.cys .cfg-drawer .changes { padding: 10px 16px; display: flex; flex-direction: column; gap: 6px; border-right: 1px solid var(--line); }
.cys .cfg-drawer .ci { display: grid; grid-template-columns: 1fr auto auto auto; gap: 8px; align-items: center; font-size: 12.5px; }
.cys .cfg-drawer .ci .from { color: var(--muted); text-decoration: line-through; font: 11.5px var(--mono); }
.cys .cfg-drawer .ci .to { font: 11.5px var(--mono); color: var(--accent-ink); }
.cys .cfg-drawer pre { margin: 0; padding: 10px 16px; font: 11.5px/1.6 var(--mono); color: var(--ink-2); white-space: pre-wrap; word-break: break-all; }
.cys .cfg-drawer pre .add { color: var(--ok); } .cys .cfg-drawer pre .del { color: var(--bad); } .cys .cfg-drawer pre .cm { color: var(--faint); }
.cys .cfg-drawer .df { display: flex; align-items: center; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--line); }
.cys .cfg-drawer .hist { overflow: auto; padding: 8px 16px 14px; display: flex; flex-direction: column; gap: 6px; }
.cys .cfg-drawer .hi { display: grid; grid-template-columns: auto 1fr auto auto; gap: 10px; align-items: center; font-size: 12.5px; padding: 6px 0; border-bottom: 1px solid var(--line); }
.cys .cfg-pv { overflow: hidden; }
.cys .cfg-pv .cys-ph { justify-content: space-between; }
.cys .cfg-stage { position: relative; height: 300px; display: grid; place-items: end center; background: radial-gradient(circle, rgb(var(--glow) / .12) 1px, transparent 1.2px) 0 0 / 22px 22px, var(--well); border-bottom: 1px solid var(--line); border-top: 1px solid var(--line); overflow: hidden; }
.cys .cfg-stage .ground { position: absolute; left: 0; right: 0; bottom: 46px; height: 1px; background: var(--line-2); }
