.cys .cfg-stage .mob { position: relative; margin-bottom: 86px; transform-origin: bottom center; transition: transform .25s; }
.cys .cfg-stage .mob .head { width: 44px; height: 40px; border-radius: 8px; background: linear-gradient(180deg, #9ae6b4, #38a169); margin: 0 auto 4px; position: relative; }
.cys .cfg-stage .mob .head::before, .cys .cfg-stage .mob .head::after { content: ""; position: absolute; top: 15px; width: 8px; height: 6px; background: #0b1f15; border-radius: 2px; }
.cys .cfg-stage .mob .head::before { left: 9px; } .cys .cfg-stage .mob .head::after { right: 9px; }
.cys .cfg-stage .mob .body { width: 46px; height: 52px; border-radius: 8px; background: linear-gradient(180deg, #6ee7b7, #2f855a); position: relative; }
.cys .cfg-stage .mob .arm { position: absolute; top: 4px; width: 14px; height: 44px; border-radius: 6px; background: #48bb78; transform-origin: top center; }
