.cys .cfg-stage .mob .leg.l { left: 4px; } .cys .cfg-stage .mob .leg.r { right: 4px; }
.cys .cfg-stage .gunv { margin-bottom: 120px; position: relative; width: 230px; height: 70px; }
.cys .cfg-stage .gunv .rcv { position: absolute; left: 40px; top: 18px; width: 150px; height: 26px; border-radius: 6px; background: linear-gradient(180deg, #4a4f63, #2b2e3b); }
.cys .cfg-stage .gunv .brl { position: absolute; left: 186px; top: 24px; width: 40px; height: 9px; border-radius: 3px; background: #23252f; }
.cys .cfg-stage .gunv .mag { position: absolute; left: 100px; top: 40px; width: 22px; height: 38px; border-radius: 3px; background: #3a3f52; }
.cys .cfg-stage .gunv .stk { position: absolute; left: 0; top: 22px; width: 46px; height: 22px; border-radius: 6px 3px 3px 10px; background: #5b4636; }
.cys .cfg-stage .gunv .flash { position: absolute; left: 224px; top: 14px; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, #fff7c2, #ffb44f 45%, transparent 70%); }
.cys .cfg-readout { padding: 12px 14px; display: flex; flex-direction: column; gap: 7px; }
.cys .cfg-readout .r { display: flex; align-items: center; gap: 8px; font-size: 12.5px; }
.cys .cfg-readout .r b { margin-left: auto; font-size: 12px; font-weight: 500; }
.cys .cfg-readout .meter { width: 90px; height: 5px; border-radius: 3px; background: var(--surface-3); overflow: hidden; }
.cys .cfg-readout .meter i { display: block; height: 100%; background: var(--cyan); }
.cys .cfg-clock { display: flex; align-items: center; gap: 8px; padding: 10px 14px; border-top: 1px solid var(--line); margin-top: auto; }
.cys .cfg-ro { display: flex; gap: 8px; align-items: center; margin: 0 12px 10px; padding: 10px 12px; border-radius: 12px; font-size: 12px; color: var(--ink-2); background: var(--accent-soft); border: 1px solid var(--accent-line); }
@media (max-width: 1180px) { .cys .cfg-ws { grid-template-columns: 200px minmax(0, 1fr); overflow: auto; } .cys .cfg-pv { grid-column: 1 / -1; } }
@media (max-width: 760px) {
  .cys .cfg-ws { display: flex; flex-direction: column; padding: 0 10px 40px; overflow: auto; }
  .cys .cfg-rail { flex-direction: row; overflow-x: auto; padding: 6px; flex: none; } .cys .cfg-legend { display: none; } .cys .cfg-g { white-space: nowrap; width: auto; }
  .cys .cfg-form { overflow: visible; flex: none; } .cys .cfg-rows { overflow: visible; }
  .cys .cfg-fh { flex-wrap: wrap; } .cys .cfg-search { width: 100%; }
  .cys .cfg-bar { flex-wrap: wrap; }
  .cys .cfg-row { grid-template-columns: 1fr; } .cys .cfg-row .right { justify-content: flex-start; }
  .cys .cfg-pv { flex: none; } .cys .cfg-stage { height: 220px; }
}
EOF
mkdir -p "app/dashboard/cyrus/[id]/studio/config" && cat > "app/dashboard/cyrus/[id]/studio/config/page.tsx" <<'EOF'
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { modBuilderMetadata, requireModBuilderUser } from "@/lib/modbuilder/access";
import { configStudioViewer } from "@/lib/cyrus/config/deps";
import { modelStudioViewer } from "@/lib/cyrus/modelstudio/deps";
import { ConfigStudio } from "@/components/cyrus/studios/ConfigStudio";
import { studioContext } from "../../../studio-shared";

export const dynamic = "force-dynamic";
export async function generateMetadata(): Promise<Metadata> {
  return modBuilderMetadata("Config Studio · Cyrus");
}

/**
 * Full-page Config and Stats Studio. Gates: the Cyrus access rule -> the studios gate (studioContext: ownership of the
 * build) -> CYRUS_CONFIG_STUDIO (off: 404). Not plan-gated: editing numbers is not asset creation (owner decision
 * pending, proposed ungated); the API checks ownership on every request.
 */
export default async function ConfigStudioPage({ params }: { params: Promise<{ id: string }> }) {
  await requireModBuilderUser();
  const { id } = await params;
  const { mod } = await studioContext(id);
  if (!(await configStudioViewer())) notFound();
  const showModel = !!(await modelStudioViewer().catch(() => null));
  return <ConfigStudio mod={mod} showModel={showModel} />;
}
EOF
