cd /tank/dev-worktrees/cyrus-r23 && cat > test/e2e/cyrus-config-studio.shots.mjs <<'EOF'
// Cyrus Config and Stats Studio: screenshots + a real save through the API, run ON node-2 against the devhost dev server.
//   devhost db reset && devhost db push
//   devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//   devhost run -- npx tsx scripts/cyrus/config-fixtures.ts .studio-tokens.json > .config-tokens.json
//   devhost env set CYRUS_CONFIG_STUDIO=1 ; devhost dev
//   devhost run -- node test/e2e/cyrus-config-studio.shots.mjs .config-tokens.json .config-shots
//   devhost pull .config-shots /root/agent-notes/cyrus-designs/impl-shots   (files are prefixed config-)
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".config-shots", only = ""] = process.argv;
const want = (n) => !only || only.split(",").includes(n);
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
let failures = 0;

async function session(who, { theme = "dark", narrow = false } = {}) {
  const c = await browser.newContext({ viewport: narrow ? { width: 390, height: 844 } : { width: 1440, height: 900 }, deviceScaleFactor: narrow ? 2 : 1, colorScheme: theme });
  await c.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await c.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error" && !/favicon|Failed to load resource.*(404|503)/.test(m.text())) errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(`${BASE}/dashboard/cyrus/${T[who].buildId}/studio/config`, { waitUntil: "networkidle", timeout: 180000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForSelector(".cfg-row", { timeout: 90000 }).catch((e) => errs.push("wait " + String(e).slice(0, 120)));
  await page.waitForTimeout(900);
  return { c, page, errs };
}
async function done(name, s, info = "") {
  await s.page.screenshot({ path: `${out}/${name}.png`, fullPage: false, timeout: 120000 });
  if (s.errs.length) failures++;
  console.log(`${out}/${name}.png`, info, s.errs.length ? "ERR " + s.errs.join(" | ").slice(0, 600) : "");
  await s.c.close();
}
const setNum = async (page, key, v) => { const i = page.locator(`[data-key="${key}"] .cfg-num input`).first(); await i.fill(String(v)); await i.press("Enter"); };

if (want("mob-dark")) {
  const s = await session("frost");
  try { await setNum(s.page, "mobs.frost_zombie.attack_damage", 26); await setNum(s.page, "mobs.frost_zombie.scale", 1.5); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await s.page.waitForTimeout(500);
  await done("config-mob-dark", s);
}
if (want("mob-light")) {
  const s = await session("frost", { theme: "light" });
  try { await s.page.locator(".cfg-g", { hasText: "Spawning" }).click(); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("config-mob-light", s);
}
if (want("gun-review")) {
  const s = await session("gun");
  try {
    await setNum(s.page, "guns.ak47.fire_rate", 750); await setNum(s.page, "guns.ak47.magazine_size", 40); await setNum(s.page, "guns.ak47.reload_time", 2);
    await s.page.getByRole("button", { name: "Review changes" }).click(); await s.page.waitForSelector(".cfg-drawer pre .add", { timeout: 20000 });
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("config-gun-review-dark", s);
}
if (want("gun-saved")) {
  const s = await session("gun", { theme: "light" });
  let info = "";
  try {
    await setNum(s.page, "guns.ak47.damage", 8);
    await s.page.locator(".cfg-cmd input").fill("set the reload time to 3 seconds and fire mode to semi");
    await s.page.getByRole("button", { name: "Apply", exact: true }).click(); await s.page.waitForTimeout(700);
    await s.page.getByRole("button", { name: "Review changes" }).click(); await s.page.waitForSelector(".cfg-drawer .ci", { timeout: 20000 });
    await s.page.getByRole("button", { name: "Save revision" }).click(); await s.page.waitForSelector(".cys-toast", { timeout: 20000 });
    info = await s.page.locator(".cys-toast").innerText();
    await s.page.getByRole("button", { name: "History" }).click(); await s.page.waitForTimeout(400);
  } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("config-gun-saved-light", s, info);
}
if (want("search")) {
  const s = await session("frost");
  try { await s.page.getByLabel("Search settings").fill("speed"); await s.page.waitForTimeout(300); } catch (e) { s.errs.push("act " + String(e).slice(0, 200)); }
  await done("config-search-dark", s);
}
if (want("phone")) {
  const s = await session("frost", { narrow: true });
  await done("config-phone-dark", s);
}
if (want("phone-light")) {
  const s = await session("gun", { narrow: true, theme: "light" });
  await s.page.evaluate(() => document.querySelector(".cfg-pv")?.scrollIntoView());
  await done("config-phone-light", s);
}
await browser.close();
console.log(failures ? `${failures} shot(s) had errors` : "all shots clean");
EOF
timeout 1200 /opt/nxeon/scripts/devhost db reset 2>&1 | tail -2; timeout 1200 /opt/nxeon/scripts/devhost db push 2>&1 | tail -2

